export const ART_DICTIONARY = [
  {"artistEn":"Albrecht Dürer","artistKo":"알브레히트 뒤러","artistKeys":["durer","duerer","albrecht"],"titleEn":"Knight, Death and the Devil","titleKo":"기사, 죽음 그리고 악마","titleKeys":["knight","death","devil"],"year":"1513","desc":"갑옷을 입은 기사가 죽음과 악마의 위협 속에서도 굳건히 말을 몰고 나아가는 장면을 새긴 동판화다. 흔들리지 않는 신앙과 의지를 상징하는 도상으로 해석되며, 뒤러 판화 기술의 정점을 보여준다."},
  {"artistEn":"Albrecht Dürer","artistKo":"알브레히트 뒤러","artistKeys":["durer","duerer","albrecht"],"titleEn":"Melencolia I","titleKo":"멜랑콜리아 I","titleKeys":["melencolia","melancholia"],"year":"1514","desc":"날개 달린 인물이 턱을 괴고 깊은 생각에 잠긴 모습을 새긴 동판화다. 다면체, 마방진, 모래시계 등 수수께끼 같은 상징물로 가득해 수많은 해석을 낳았으며, 뒤러의 3대 동판화 중 하나로 꼽힌다."},
  {"artistEn":"Albrecht Dürer","artistKo":"알브레히트 뒤러","artistKeys":["durer","duerer","albrecht"],"titleEn":"Praying Hands","titleKo":"기도하는 손","titleKeys":["praying","hands"],"year":"1508","desc":"기도하기 위해 모은 두 손을 그린 소묘로, 제단화 작업을 위한 습작으로 제작되었다. 푸른빛 바탕 종이에 흰 하이라이트를 더한 정교한 기법과 단순한 소재에 담긴 경건함 덕분에 세계적으로 사랑받는 이미지가 되었다."},
  {"artistEn":"Albrecht Dürer","artistKo":"알브레히트 뒤러","artistKeys":["durer","duerer","albrecht"],"titleEn":"Self-Portrait with Fur-Trimmed Robe","titleKo":"모피 코트를 입은 자화상","titleKeys":["self","portrait","fur"],"year":"1500","desc":"모피 코트를 입고 정면을 응시하는 화가 자신의 모습을 그린 자화상이다. 그리스도 도상을 연상시키는 엄격한 정면 구도로 예술가의 자의식을 선언한 기념비적 작품으로 평가되며, 뮌헨 알테 피나코테크에 있다."},
  {"artistEn":"Albrecht Dürer","artistKo":"알브레히트 뒤러","artistKeys":["durer","duerer","albrecht"],"titleEn":"The Four Apostles","titleKo":"네 명의 사도","titleKeys":["four","apostles"],"year":"1526","desc":"요한, 베드로, 마르코, 바울 네 성인을 두 폭의 패널에 나누어 그린 대형 작품이다. 종교개혁기의 신앙 고백이 담긴 뒤러 만년의 걸작으로, 네 인물의 서로 다른 기질을 표현한 개성적 묘사가 돋보인다."},
  {"artistEn":"Albrecht Dürer","artistKo":"알브레히트 뒤러","artistKeys":["durer","duerer","albrecht"],"titleEn":"Young Hare","titleKo":"어린 산토끼","titleKeys":["young","hare","rabbit"],"year":"1502","desc":"산토끼 한 마리를 놀랍도록 정밀하게 그린 수채화로, 털 한 올 한 올까지 살아 있는 듯한 묘사가 압권이다. 자연 관찰에 바탕한 뒤러의 대표적 습작이자 북유럽 르네상스의 아이콘으로, 빈 알베르티나 미술관에 소장되어 있다."},
  {"artistEn":"Alfred Sisley","artistKo":"알프레드 시슬레","artistKeys":["sisley","alfred sisley"],"titleEn":"Flood at Port-Marly","titleKo":"포르마를리의 홍수","titleKeys":["flood","port-marly","marly"],"year":"1876","desc":"센 강이 범람해 물에 잠긴 포르마를리 마을의 모습을 그린 연작 중 대표작이다. 재난의 현장임에도 물에 비친 하늘과 건물의 반영이 고요하고 서정적으로 표현되어, 시슬레 최고의 걸작으로 평가된다."},
  {"artistEn":"Alfred Sisley","artistKo":"알프레드 시슬레","artistKeys":["sisley","alfred sisley"],"titleEn":"Snow at Louveciennes","titleKo":"루브시엔의 눈","titleKeys":["snow","louveciennes"],"year":"1878","desc":"눈 내리는 루브시엔 마을의 골목길을 우산 쓴 행인 한 명과 함께 그린 겨울 풍경이다. 흰 눈에 덮인 담장과 나무의 미묘한 색조 변화가 섬세하며, 평생 풍경화에 전념한 시슬레의 조용한 시정이 배어 있다."},
  {"artistEn":"Alfred Sisley","artistKo":"알프레드 시슬레","artistKeys":["sisley","alfred sisley"],"titleEn":"The Bridge at Villeneuve-la-Garenne","titleKo":"빌뇌브라가렌의 다리","titleKeys":["bridge","villeneuve"],"year":"1872","desc":"센 강 위에 놓인 철교와 강변 마을을 밝은 여름 빛 속에 그린 작품이다. 잔잔한 수면에 비친 다리와 집들의 반영, 맑은 하늘의 표현에서 초기 인상주의 풍경화의 신선함이 그대로 전해진다."},
  {"artistEn":"Alphonse Mucha","artistKo":"알폰스 무하","artistKeys":["mucha","alphonse mucha","alphonsemucha","alfons mucha"],"titleEn":"Gismonda","titleKo":"지스몽다","titleKeys":["gismonda"],"year":"1894","desc":"대배우 사라 베르나르의 연극을 알리기 위해 제작한 포스터로, 무하를 하루아침에 유명하게 만들었다. 길쭉한 세로 화면과 모자이크풍 장식이 아르누보 포스터 양식의 시작을 알린 작품이다."},
  {"artistEn":"Alphonse Mucha","artistKo":"알폰스 무하","artistKeys":["mucha","alphonse mucha","alphonsemucha","alfons mucha"],"titleEn":"The Four Seasons","titleKo":"사계","titleKeys":["four","seasons"],"year":"1896","desc":"봄, 여름, 가을, 겨울을 각각 여성의 모습으로 의인화한 네 폭의 장식 패널이다. 흐르는 머리칼과 식물 문양이 어우러진 아르누보 장식미술의 정수로, 무하의 연작 중 가장 사랑받는다."},
  {"artistEn":"Alphonse Mucha","artistKo":"알폰스 무하","artistKeys":["mucha","alphonse mucha","alphonsemucha","alfons mucha"],"titleEn":"The Slav Epic","titleKo":"슬라브 서사시","titleKeys":["slav","epic"],"year":"1912-1926","desc":"슬라브 민족의 역사와 신화를 담은 20점의 초대형 연작이다. 파리에서 성공한 무하가 고국으로 돌아와 만년의 열정을 바친 필생의 역작으로, 상업 포스터 화가를 넘어선 면모를 보여준다."},
  {"artistEn":"Alphonse Mucha","artistKo":"알폰스 무하","artistKeys":["mucha","alphonse mucha","alphonsemucha","alfons mucha"],"titleEn":"Zodiac","titleKo":"황도 12궁","titleKeys":["zodiac"],"year":"1896","desc":"별자리 문양의 후광을 배경으로 비잔틴풍 장신구를 한 여인의 옆모습을 그렸다. 잡지 '라 플륌'의 달력 도안으로 제작되었으며, 무하의 장식 패널 중 가장 널리 사랑받는 이미지가 되었다."},
  {"artistEn":"Amedeo Modigliani","artistKo":"아메데오 모딜리아니","artistKeys":["modigliani","amedeo modigliani","amedeomodigliani"],"titleEn":"Portrait of Chaim Soutine","titleKo":"섕 수틴의 초상","titleKeys":["chaim","soutine"],"year":"1917","desc":"몽파르나스에서 함께 작업하던 화가 섕 수틴을 그린 초상이다. 비대칭의 얼굴과 단순화된 형태에서 두 보헤미안 화가의 우정과 거칠었던 파리 시절의 삶이 묻어난다."},
  {"artistEn":"Amedeo Modigliani","artistKo":"아메데오 모딜리아니","artistKeys":["modigliani","amedeo modigliani","amedeomodigliani"],"titleEn":"Portrait of Jeanne Hebuterne","titleKo":"잔 에뷔테른의 초상","titleKeys":["jeanne","hebuterne"],"year":"1918","desc":"모딜리아니의 연인이자 마지막 동반자였던 잔 에뷔테른을 그린 초상이다. 긴 목과 갸름한 얼굴, 텅 빈 아몬드형 눈동자가 모딜리아니 특유의 우아한 양식을 보여주는 대표적 초상화다."},
  {"artistEn":"Amedeo Modigliani","artistKo":"아메데오 모딜리아니","artistKeys":["modigliani","amedeo modigliani","amedeomodigliani"],"titleEn":"Reclining Nude","titleKo":"누워 있는 나부","titleKeys":["reclining","nude","nu couche"],"year":"1917","desc":"붉은 소파에 비스듬히 누운 여인을 길게 늘인 곡선으로 그린 누드 연작의 대표작이다. 1917년 파리 첫 개인전에 걸렸다가 경찰에 의해 철거되는 소동을 겪었고, 훗날 미술 경매 사상 최고가급에 거래되었다."},
  {"artistEn":"Amedeo Modigliani","artistKo":"아메데오 모딜리아니","artistKeys":["modigliani","amedeo modigliani","amedeomodigliani"],"titleEn":"Woman with a Fan","titleKo":"부채를 든 여인","titleKeys":["woman","fan","lunia"],"year":"1919","desc":"친구이자 뮤즈였던 루니아 체호프스카를 부채를 든 우아한 모습으로 그린 말년작이다. 2010년 파리 시립 현대미술관 도난 사건으로 사라져 아직까지 행방이 묘연한 작품이다."},
  {"artistEn":"An Gyeon","artistKo":"안견","artistKeys":["an gyeon","angyeon","an kyon"],"titleEn":"Mongyu Dowondo (Dream Journey to the Peach Blossom Land)","titleKo":"몽유도원도","titleKeys":["mongyu","dowondo","dream","peach"],"year":"1447","desc":"안평대군이 꿈에서 본 복사꽃 핀 이상향을 사흘 만에 그려낸 조선 초기 산수화의 걸작이다. 현실에서 꿈속 도원으로 이어지는 장대한 구성이 돋보이며, 현재 일본 덴리대학교에 소장되어 있다."},
  {"artistEn":"Andrew Wyeth","artistKo":"앤드루 와이어스","artistKeys":["wyeth","andrew wyeth","andrewwyeth"],"titleEn":"Christina's World","titleKo":"크리스티나의 세계","titleKeys":["christina","world"],"year":"1948","desc":"다리가 불편했던 이웃 크리스티나 올슨이 들판에 앉아 언덕 위 집을 바라보는 모습을 그렸다. 광활한 들판과 작은 인물의 대비가 강한 여운을 남기는 미국 사실주의의 명작이다."},
  {"artistEn":"Antoine Watteau","artistKo":"앙투안 바토","artistKeys":["watteau","antoine watteau","jean antoine watteau"],"titleEn":"Pierrot (Gilles)","titleKo":"피에로(질)","titleKeys":["pierrot","gilles"],"year":"c. 1719","desc":"흰 옷을 입은 광대 피에로가 화면 중앙에 홀로 우두커니 서 있는 초상이다. 무대 위 어릿광대의 공허한 표정에서 화려함 뒤의 쓸쓸함이 드러나며, 바토 말년의 대표작으로 루브르에 소장되어 있다."},
  {"artistEn":"Antoine Watteau","artistKo":"앙투안 바토","artistKeys":["watteau","antoine watteau","jean antoine watteau"],"titleEn":"Pilgrimage to Cythera","titleKo":"키테라 섬의 순례","titleKeys":["pilgrimage","cythera"],"year":"1717","desc":"사랑의 여신 비너스의 섬 키테라로 떠나는 연인들을 그린 작품으로, 로코코 특유의 우아하고 몽환적인 분위기가 화면 전체에 흐른다. 바토가 창시한 '페트 갈랑트(아연화)' 장르의 대표작이다."},
  {"artistEn":"Arnold Böcklin","artistKo":"아르놀트 뵈클린","artistKeys":["bocklin","boecklin","arnold bocklin"],"titleEn":"Isle of the Dead","titleKo":"죽음의 섬","titleKeys":["isle","dead"],"year":"1880","desc":"사이프러스 나무가 솟은 바위섬으로 흰 옷의 인물과 관을 실은 배가 다가가는 장면을 그린 작품이다. 다섯 가지 버전으로 제작되었으며, 죽음의 정적을 담은 상징주의의 대표적 이미지가 되었다."},
  {"artistEn":"Arnold Böcklin","artistKo":"아르놀트 뵈클린","artistKeys":["bocklin","boecklin","arnold bocklin"],"titleEn":"Self-Portrait with Death Playing the Fiddle","titleKo":"바이올린을 켜는 죽음이 있는 자화상","titleKeys":["self","portrait","death","fiddle"],"year":"1872","desc":"붓을 든 화가의 등 뒤에서 해골이 바이올린을 켜는 모습을 그린 자화상이다. 죽음의 선율에 귀 기울이는 예술가라는 바니타스적 주제를 담아, 뵈클린의 상징주의적 세계관을 압축해 보여준다."},
  {"artistEn":"Artemisia Gentileschi","artistKo":"아르테미시아 젠틸레스키","artistKeys":["gentileschi","artemisia"],"titleEn":"Judith Slaying Holofernes","titleKo":"홀로페르네스의 목을 베는 유디트","titleKeys":["judith","holofernes","slaying"],"year":"c. 1614–1620","desc":"유디트와 하녀가 힘을 합쳐 홀로페르네스의 목을 베는 장면을 강렬하게 그렸다. 카라바조의 영향을 받은 극적인 명암과 물리적 힘이 느껴지는 사실적 묘사로, 바로크 시대 여성 화가의 대표작으로 꼽힌다."},
  {"artistEn":"Artemisia Gentileschi","artistKo":"아르테미시아 젠틸레스키","artistKeys":["gentileschi","artemisia"],"titleEn":"Self-Portrait as the Allegory of Painting","titleKo":"회화의 알레고리로서의 자화상","titleKeys":["self","portrait","allegory","painting"],"year":"c. 1638–1639","desc":"화가 자신을 회화의 알레고리인 여신의 모습으로 그린 자화상이다. 붓과 팔레트를 들고 작업에 몰두하는 역동적인 자세로, 여성이라는 이유로 차별받던 시대에 예술가로서의 자부심을 당당히 드러냈다."},
  {"artistEn":"Artemisia Gentileschi","artistKo":"아르테미시아 젠틸레스키","artistKeys":["gentileschi","artemisia"],"titleEn":"Susanna and the Elders","titleKo":"수산나와 장로들","titleKeys":["susanna","elders"],"year":"1610","desc":"목욕하던 수산나가 장로들에게 위협받는 성서 장면을 그린 열일곱 살 무렵의 초기작이다. 수산나의 거부감과 불안을 정면으로 담아내, 같은 주제를 다룬 남성 화가들의 그림과 구별되는 시선을 보여준다."},
  {"artistEn":"Berthe Morisot","artistKo":"베르트 모리조","artistKeys":["morisot","berthe morisot"],"titleEn":"Summer's Day","titleKo":"여름날","titleKeys":["summer","day"],"year":"1879","desc":"불로뉴 숲의 호수에서 뱃놀이하는 두 여인을 그린 작품이다. 지그재그로 움직이는 활달한 붓질이 물결과 옷자락에 생동감을 불어넣으며, 여성 인상파 화가로서 모리조의 대담한 기량을 보여준다."},
  {"artistEn":"Berthe Morisot","artistKo":"베르트 모리조","artistKeys":["morisot","berthe morisot"],"titleEn":"The Cradle","titleKo":"요람","titleKeys":["cradle"],"year":"1872","desc":"언니 에드마가 얇은 망사 커튼 너머 잠든 아기를 바라보는 모습을 그린 작품이다. 1874년 첫 인상파 전시에 출품된 모리조의 대표작으로, 모성의 애틋한 시선과 투명한 흰색의 섬세한 표현이 돋보인다."},
  {"artistEn":"Berthe Morisot","artistKo":"베르트 모리조","artistKeys":["morisot","berthe morisot"],"titleEn":"Woman at Her Toilette","titleKo":"몸단장하는 여인","titleKeys":["woman","toilette"],"year":"1875-1880","desc":"거울 앞에서 머리를 매만지는 여인의 뒷모습을 은회색과 분홍빛의 부드러운 색조로 그린 작품이다. 사적인 실내 공간 속 여성의 일상을 깃털처럼 가벼운 붓질로 담아낸 모리조의 대표작이다."},
  {"artistEn":"Camille Corot","artistKo":"카미유 코로","artistKeys":["corot","camille corot","jean baptiste camille corot"],"titleEn":"Souvenir de Mortefontaine","titleKo":"모르트퐁텐의 추억","titleKeys":["souvenir","mortefontaine"],"year":"1864","desc":"호숫가의 커다란 나무 아래에서 여인과 아이들이 가지를 만지는 모습을 은빛 색조로 그린 작품이다. 기억 속 풍경을 시적으로 재구성한 코로 후기 화풍의 정수로, 루브르에 소장되어 있다."},
  {"artistEn":"Camille Corot","artistKo":"카미유 코로","artistKeys":["corot","camille corot","jean baptiste camille corot"],"titleEn":"The Bridge at Narni","titleKo":"나르니 다리","titleKeys":["bridge","narni"],"year":"1826","desc":"이탈리아 나르니의 고대 로마 다리 유적을 그린 초기 풍경화다. 현장에서 그린 유화 스케치의 신선한 빛 표현이 돋보이며, 야외 사생 전통이 인상주의로 이어지는 길목의 작품으로 평가된다."},
  {"artistEn":"Camille Pissarro","artistKo":"카미유 피사로","artistKeys":["pissarro","camille pissarro"],"titleEn":"Entrance to the Village of Voisins","titleKo":"부아쟁 마을 입구","titleKeys":["entrance","village","voisins"],"year":"1872","desc":"파리 근교 부아쟁 마을로 들어서는 가로수길을 그린 작품으로, 겨울 나무 사이로 아침 햇살이 길게 비친다. 소박한 농촌의 일상을 꾸밈없이 담아낸 피사로 특유의 겸손하고 서정적인 시선이 느껴진다."},
  {"artistEn":"Camille Pissarro","artistKo":"카미유 피사로","artistKeys":["pissarro","camille pissarro"],"titleEn":"Hoarfrost","titleKo":"서리","titleKeys":["hoarfrost","frost"],"year":"1873","desc":"서리 내린 시골길을 나뭇단을 진 농부가 걸어가는 겨울 아침 풍경이다. 1874년 첫 인상파 전시에 출품되어 그림자 표현을 두고 비평가의 조롱을 받았으나, 흙길에 어른거리는 빛과 그림자의 표현이 혁신적이었다."},
  {"artistEn":"Camille Pissarro","artistKo":"카미유 피사로","artistKeys":["pissarro","camille pissarro"],"titleEn":"The Boulevard Montmartre at Night","titleKo":"밤의 몽마르트르 대로","titleKeys":["boulevard","montmartre","night"],"year":"1897","desc":"호텔 창가에서 내려다본 몽마르트르 대로의 밤 풍경으로, 가로등과 상점 불빛이 비에 젖은 길 위에 번진다. 피사로가 같은 창에서 그린 대로 연작 중 유일한 야경이며, 근대 도시의 밤을 그린 걸작으로 꼽힌다."},
  {"artistEn":"Camille Pissarro","artistKo":"카미유 피사로","artistKeys":["pissarro","camille pissarro"],"titleEn":"The Red Roofs","titleKo":"붉은 지붕","titleKeys":["red","roofs"],"year":"1877","desc":"퐁투아즈 근교 마을의 붉은 지붕 집들이 겨울 나뭇가지 사이로 보이는 풍경을 그린 작품이다. 나무 사이로 겹쳐 보이는 집과 언덕의 구성이 치밀하며, 세잔과 함께 작업하던 시기의 견고한 화면 구축이 돋보인다."},
  {"artistEn":"Canaletto","artistKo":"카날레토","artistKeys":["canaletto"],"titleEn":"The Entrance to the Grand Canal, Venice","titleKo":"베네치아 대운하의 입구","titleKeys":["entrance","grand","canal"],"year":"c. 1730","desc":"베네치아 대운하 입구와 살루테 성당을 정밀하게 그린 도시 풍경화다. 곤돌라가 오가는 수면과 건축물의 세부가 사진처럼 정확하며, 18세기 베두타(도시 경관화)의 정점을 보여준다."},
  {"artistEn":"Canaletto","artistKo":"카날레토","artistKeys":["canaletto"],"titleEn":"The Stonemason's Yard","titleKo":"석공의 작업장","titleKeys":["stonemason","yard"],"year":"c. 1725","desc":"관광 명소가 아닌 베네치아 서민 지역의 석공 작업장을 그린 작품이다. 노동하는 사람들과 낡은 건물들을 꾸밈없이 담아, 화려한 경관화와는 다른 카날레토의 사실적 시선을 보여준다."},
  {"artistEn":"Caravaggio","artistKo":"카라바조","artistKeys":["caravaggio"],"titleEn":"Bacchus","titleKo":"바쿠스","titleKeys":["bacchus"],"year":"c. 1596","desc":"포도주 잔을 내미는 술의 신 바쿠스를 그린 초기작으로, 신을 이상화하지 않고 현실의 젊은이처럼 묘사했다. 시들기 시작한 과일 바구니의 정밀한 정물 묘사와 나른한 분위기가 특징이며, 우피치 미술관에 있다."},
  {"artistEn":"Caravaggio","artistKo":"카라바조","artistKeys":["caravaggio"],"titleEn":"David with the Head of Goliath","titleKo":"골리앗의 머리를 든 다윗","titleKeys":["david","goliath","head"],"year":"c. 1610","desc":"다윗이 골리앗의 잘린 머리를 들고 있는 장면으로, 골리앗의 얼굴에 화가 자신의 모습을 담은 것으로 전해진다. 어둠 속에서 떠오르는 인물과 승리 대신 연민이 감도는 비극적 정서가 인상적인 만년작이다."},
  {"artistEn":"Caravaggio","artistKo":"카라바조","artistKeys":["caravaggio"],"titleEn":"Judith Beheading Holofernes","titleKo":"홀로페르네스의 목을 베는 유디트","titleKeys":["judith","holofernes","beheading"],"year":"c. 1598–1599","desc":"유디트가 적장 홀로페르네스의 목을 베는 성서 장면을 충격적일 만큼 사실적으로 그렸다. 어둠을 가르는 강렬한 빛과 세 인물의 생생한 표정 대비가 바로크 회화의 극적 성격을 잘 보여준다."},
  {"artistEn":"Caravaggio","artistKo":"카라바조","artistKeys":["caravaggio"],"titleEn":"Medusa","titleKo":"메두사","titleKeys":["medusa"],"year":"1597","desc":"목이 잘리는 순간 비명을 지르는 메두사의 머리를 원형 방패 위에 그린 작품이다. 공포에 질려 크게 벌어진 입과 뒤엉킨 뱀 머리카락의 생생함이 압도적이며, 우피치 미술관의 인기 소장품이다."},
  {"artistEn":"Caravaggio","artistKo":"카라바조","artistKeys":["caravaggio"],"titleEn":"Supper at Emmaus","titleKo":"엠마오의 저녁 식사","titleKeys":["supper","emmaus"],"year":"1601","desc":"부활한 그리스도를 뒤늦게 알아본 제자들의 놀란 순간을 포착한 작품이다. 화면 밖으로 뻗은 팔과 식탁 끝에 아슬아슬하게 걸린 과일 바구니가 관람자를 장면 속으로 끌어들이며, 런던 내셔널 갤러리에 있다."},
  {"artistEn":"Caravaggio","artistKo":"카라바조","artistKeys":["caravaggio"],"titleEn":"The Calling of Saint Matthew","titleKo":"성 마태오의 소명","titleKeys":["calling","matthew"],"year":"1599–1600","desc":"세리 마태오가 그리스도의 부름을 받는 순간을 어두운 실내 장면으로 그렸다. 창으로 쏟아지는 한 줄기 빛이 극적인 긴장감을 만들어내는 바로크 명암법의 대표작으로, 로마 산 루이지 데이 프란체시 성당에 있다."},
  {"artistEn":"Caravaggio","artistKo":"카라바조","artistKeys":["caravaggio"],"titleEn":"The Conversion of Saint Paul","titleKo":"성 바울의 개종","titleKeys":["conversion","paul","damascus"],"year":"1601","desc":"다마스쿠스로 가던 사울이 말에서 떨어져 신의 빛에 휩싸이는 회심의 순간을 그렸다. 화면 대부분을 차지하는 말과 바닥에 쓰러져 팔을 벌린 인물의 파격적 구도가 당시 큰 논쟁을 불러일으킨 혁신작이다."},
  {"artistEn":"Caravaggio","artistKo":"카라바조","artistKeys":["caravaggio"],"titleEn":"The Entombment of Christ","titleKo":"그리스도의 매장","titleKeys":["entombment","christ"],"year":"1603–1604","desc":"그리스도의 시신을 무덤에 안치하는 순간을 기념비적인 구도로 그린 제단화다. 무너져 내리듯 사선으로 배치된 인물들과 강한 명암 대비가 깊은 애도의 감정을 전하며, 바티칸 미술관에 소장되어 있다."},
  {"artistEn":"Caspar David Friedrich","artistKo":"카스파르 다비트 프리드리히","artistKeys":["friedrich","caspar david friedrich"],"titleEn":"Chalk Cliffs on Rügen","titleKo":"뤼겐의 백악 절벽","titleKeys":["chalk","cliffs","rugen"],"year":"c. 1818","desc":"뤼겐 섬의 흰 절벽 사이로 푸른 바다를 내려다보는 세 인물을 그린 작품이다. 신혼여행의 기억을 담은 것으로 알려져 있으며, 밝은 색조와 서정성이 프리드리히 작품 중에서도 이례적이다."},
  {"artistEn":"Caspar David Friedrich","artistKo":"카스파르 다비트 프리드리히","artistKeys":["friedrich","caspar david friedrich"],"titleEn":"Monk by the Sea","titleKo":"바닷가의 수도사","titleKeys":["monk","sea"],"year":"c. 1810","desc":"광활한 하늘과 어두운 바다 앞에 홀로 선 수도사를 그린 작품이다. 화면 대부분을 비워낸 파격적 구성이 무한 앞의 인간 존재를 사유하게 하며, 낭만주의 풍경화의 극단적 실험으로 꼽힌다."},
  {"artistEn":"Caspar David Friedrich","artistKo":"카스파르 다비트 프리드리히","artistKeys":["friedrich","caspar david friedrich"],"titleEn":"The Abbey in the Oakwood","titleKo":"떡갈나무 숲의 수도원","titleKeys":["abbey","oakwood","oak"],"year":"c. 1810","desc":"겨울 안개 속 폐허가 된 수도원과 앙상한 떡갈나무들 사이로 장례 행렬이 지나는 장면을 그린 작품이다. 죽음과 소멸, 신앙의 덧없음을 사색하는 프리드리히 특유의 종교적 풍경화다."},
  {"artistEn":"Caspar David Friedrich","artistKo":"카스파르 다비트 프리드리히","artistKeys":["friedrich","caspar david friedrich"],"titleEn":"The Sea of Ice","titleKo":"얼음 바다","titleKeys":["sea","ice"],"year":"c. 1824","desc":"극지의 얼음 덩어리들이 난파선을 짓누르며 솟아오른 광경을 그린 작품이다. 인간의 흔적을 압도하는 자연의 냉혹한 힘을 표현했으며, 당대에는 외면받았으나 오늘날 걸작으로 재평가된다."},
  {"artistEn":"Caspar David Friedrich","artistKo":"카스파르 다비트 프리드리히","artistKeys":["friedrich","caspar david friedrich"],"titleEn":"Wanderer above the Sea of Fog","titleKo":"안개 바다 위의 방랑자","titleKeys":["wanderer","sea","fog"],"year":"c. 1818","desc":"바위 정상에 올라 안개 낀 산맥을 내려다보는 남자의 뒷모습을 그린 작품이다. 자연 앞에 선 인간의 고독과 숭고를 형상화한 독일 낭만주의의 대표적 이미지로, 무수히 인용되고 패러디되었다."},
  {"artistEn":"Claude Lorrain","artistKo":"클로드 로랭","artistKeys":["lorrain","claude lorrain","claude"],"titleEn":"Landscape with the Marriage of Isaac and Rebecca","titleKo":"이삭과 레베카의 결혼이 있는 풍경","titleKeys":["marriage","isaac","rebecca"],"year":"1648","desc":"성서 속 이삭과 레베카의 혼인 축제를 나무와 물레방아가 어우러진 목가적 풍경 속에 그려 넣었다. 황금빛 대기와 균형 잡힌 구도로 이상적 풍경화의 모범이 되었으며, 런던 내셔널 갤러리에 소장되어 있다."},
  {"artistEn":"Claude Lorrain","artistKo":"클로드 로랭","artistKeys":["lorrain","claude lorrain","claude"],"titleEn":"Seaport with the Embarkation of the Queen of Sheba","titleKo":"시바 여왕의 승선","titleKeys":["seaport","embarkation","sheba"],"year":"1648","desc":"시바 여왕이 솔로몬 왕을 만나러 배에 오르는 장면을 웅장한 항구 풍경에 담았다. 해 뜨는 바다를 정면으로 마주한 역광 표현이 압권으로, 이상화된 항구 풍경화의 전형을 완성했으며 터너에게 큰 영향을 주었다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Boulevard des Capucines","titleKo":"카퓌신 대로","titleKeys":["boulevard","capucines"],"year":"1873","desc":"파리 카퓌신 대로를 높은 창가에서 내려다보며 그린 도시 풍경으로, 행인들을 점과 획으로 처리해 군중의 움직임을 표현했다. 1874년 첫 인상파 전시에 출품되어 미완성 같다는 조롱과 화제를 동시에 불러일으켰다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Haystacks","titleKo":"건초더미","titleKeys":["haystacks","wheatstacks","grainstack"],"year":"1890-1891","desc":"지베르니 들판의 건초더미를 계절과 시간대를 바꿔 가며 25점 넘게 그린 연작이다. 단순한 소재가 아침 햇살, 눈, 노을에 따라 전혀 다른 색으로 변모하며, 모네 연작 회화의 출발점이 된 대표작이다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Houses of Parliament, Sunset","titleKo":"국회의사당, 석양","titleKeys":["parliament","sunset","london"],"year":"1903","desc":"런던 템스 강 너머 안개에 잠긴 국회의사당의 실루엣을 석양빛으로 물들여 그린 연작 중 하나다. 모네는 런던의 안개가 만드는 신비로운 빛의 효과에 매료되어 같은 구도를 날씨와 시간대별로 반복해 그렸다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Impression, Sunrise","titleKo":"인상, 해돋이","titleKeys":["impression","sunrise","soleil"],"year":"1872","desc":"르아브르 항구의 아침 안개 속에 떠오르는 붉은 해를 빠른 붓질로 포착한 작품이다. 1874년 첫 인상파 전시에 출품되었고, 비평가가 조롱조로 쓴 인상주의라는 말이 그대로 유파의 이름이 되었다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"La Grenouillère","titleKo":"라 그르누예르","titleKeys":["grenouillere"],"year":"1869","desc":"센 강변의 물놀이 유원지 라 그르누예르를 그린 작품으로, 같은 시기 르누아르도 나란히 같은 장소를 그렸다. 물결에 부서지는 빛을 짧은 붓 터치로 표현해 인상주의 기법이 태동하는 순간을 보여준다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Poplars on the Epte","titleKo":"엡트 강변의 포플러","titleKeys":["poplars","epte"],"year":"1891","desc":"지베르니 근처 엡트 강변에 줄지어 선 포플러 나무들을 그린 연작이다. 벌목 예정이던 나무들을 모네가 돈을 지불하고 지켜가며 그렸다는 일화가 유명하며, 수직의 나무와 리듬감 있는 곡선 구도가 돋보인다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Poppy Field","titleKo":"양귀비 들판","titleKeys":["poppy","field","poppies"],"year":"1873","desc":"아르장퇴유 근교의 붉은 양귀비가 흐드러진 들판을 걷는 여인과 아이를 그린 작품이다. 모델은 아내 카미유와 아들 장으로 추정되며, 초록 들판 위에 점점이 흩어진 붉은 꽃의 색채 대비가 강렬한 인상을 남긴다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Rouen Cathedral Series","titleKo":"루앙 대성당 연작","titleKeys":["rouen","cathedral"],"year":"1892-1894","desc":"루앙 대성당의 서쪽 파사드를 새벽부터 해질녘까지 시시각각 달라지는 빛 아래 반복해 그린 30여 점의 연작이다. 같은 대상이 빛에 따라 전혀 다른 색채로 변하는 모습을 통해 인상주의의 핵심 문제의식을 집약했다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Terrace at Sainte-Adresse","titleKo":"생타드레스의 테라스","titleKeys":["terrace","sainte-adresse","adresse"],"year":"1867","desc":"노르망디 해안 휴양지의 꽃이 만발한 테라스에서 바다를 바라보는 가족을 그린 초기작이다. 펄럭이는 깃발과 선명한 색채, 일본 판화풍의 높은 시점이 어우러져 젊은 모네의 대담한 감각을 보여준다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"The Artist's Garden at Giverny","titleKo":"지베르니의 화가의 정원","titleKeys":["garden","giverny"],"year":"1900","desc":"지베르니 자택 정원에 보랏빛 붓꽃이 줄지어 만발한 봄 풍경을 그린 작품이다. 모네는 정원 가꾸기를 그림만큼 사랑해 직접 설계한 정원을 평생의 모티프로 삼았으며, 화면 가득 꽃과 빛의 향연이 펼쳐진다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"The Cliff Walk at Pourville","titleKo":"푸르빌의 절벽 산책","titleKeys":["cliff","walk","pourville"],"year":"1882","desc":"노르망디 푸르빌 해안 절벽 위를 산책하는 두 여인과 돛단배가 떠 있는 바다를 그린 작품이다. 바람에 흔들리는 풀과 반짝이는 바다가 경쾌한 붓질로 표현되어 여름 해변의 상쾌한 공기가 전해진다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"The Gare Saint-Lazare","titleKo":"생라자르 역","titleKeys":["gare","lazare","saint lazare"],"year":"1877","desc":"파리 생라자르 역의 유리 지붕 아래 증기기관차가 뿜어내는 수증기와 빛의 어울림을 그린 연작이다. 산업화 시대의 기차역을 근대적 풍경으로 끌어올렸으며, 증기와 빛이 뒤섞이는 순간의 인상을 포착했다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"The Magpie","titleKo":"까치","titleKeys":["magpie"],"year":"1868-1869","desc":"눈 덮인 시골 울타리 위에 앉은 까치 한 마리를 그린 겨울 풍경이다. 흰 눈 위에 떨어지는 햇빛과 푸른 그림자를 섬세하게 관찰해 그렸으며, 모네의 설경 중 가장 사랑받는 작품으로 꼽힌다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"The Water Lily Pond (Japanese Bridge)","titleKo":"수련 연못 (일본식 다리)","titleKeys":["water","lily","pond","japanese"],"year":"1899","desc":"지베르니 정원의 일본식 아치형 다리와 그 아래 수련이 가득한 연못을 그린 연작이다. 일본 판화에 심취했던 모네가 직접 꾸민 정원을 소재로 했으며, 초록빛 화면 가득 무성한 여름 정원의 생명력이 넘친다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Water Lilies","titleKo":"수련","titleKeys":["water","lilies","nympheas"],"year":"1906","desc":"지베르니 자택 연못의 수련을 그린 연작으로, 모네는 말년 30여 년간 250여 점의 수련을 남겼다. 수면에 비친 하늘과 구름, 떠 있는 꽃이 어우러져 추상에 가까운 빛과 색의 세계를 이룬다."},
  {"artistEn":"Claude Monet","artistKo":"클로드 모네","artistKeys":["monet","claude monet"],"titleEn":"Woman with a Parasol - Madame Monet and Her Son","titleKo":"파라솔을 든 여인","titleKeys":["woman","parasol"],"year":"1875","desc":"언덕 위에서 파라솔을 들고 선 아내 카미유와 아들 장을 아래에서 올려다본 구도로 그린 작품이다. 바람에 날리는 베일과 풀잎, 흘러가는 구름이 빠른 붓질로 표현되어 야외의 싱그러운 순간이 생생하게 살아 있다."},
  {"artistEn":"Dante Gabriel Rossetti","artistKo":"단테 가브리엘 로세티","artistKeys":["rossetti","dante gabriel rossetti"],"titleEn":"Beata Beatrix","titleKo":"베아타 베아트릭스","titleKeys":["beata","beatrix"],"year":"c. 1870","desc":"단테의 연인 베아트리체의 죽음을 황홀경에 잠긴 여인의 모습으로 그린 작품이다. 요절한 아내 엘리자베스 시달을 기리는 추모화로, 붉은 비둘기와 양귀비가 죽음의 상징으로 등장한다."},
  {"artistEn":"Dante Gabriel Rossetti","artistKo":"단테 가브리엘 로세티","artistKeys":["rossetti","dante gabriel rossetti"],"titleEn":"Proserpine","titleKo":"프로세르피나","titleKeys":["proserpine","proserpina"],"year":"1874","desc":"석류를 든 명계의 여왕 프로세르피나를 그린 작품으로, 모델은 로세티가 사랑한 제인 모리스다. 우수에 찬 표정과 관능적인 붉은 입술이 라파엘전파 후기 미학의 이상적 여인상을 보여준다."},
  {"artistEn":"Diego Rivera","artistKo":"디에고 리베라","artistKeys":["rivera","diego rivera","diegorivera"],"titleEn":"The Flower Carrier","titleKo":"꽃을 나르는 사람","titleKeys":["flower","carrier"],"year":"1935","desc":"거대한 꽃바구니를 등에 진 남자가 무릎을 꿇은 채 일어서려 애쓰고 아내가 뒤에서 돕고 있다. 아름다움 뒤에 숨은 노동의 무게를 그린 멕시코 벽화운동 거장의 대표적 이젤화다."},
  {"artistEn":"Diego Velázquez","artistKo":"디에고 벨라스케스","artistKeys":["velazquez","velasquez"],"titleEn":"Las Hilanderas","titleKo":"실 잣는 여인들","titleKeys":["hilanderas","spinners"],"year":"c. 1657","desc":"왕립 태피스트리 공방에서 실을 잣는 여인들과 뒤편 벽걸이 앞의 신화 장면을 함께 그린 작품이다. 아라크네 신화를 현실의 노동 장면과 겹쳐 놓은 중층적 구성이 돋보이며, 프라도 미술관에 있다."},
  {"artistEn":"Diego Velázquez","artistKo":"디에고 벨라스케스","artistKeys":["velazquez","velasquez"],"titleEn":"Las Meninas","titleKo":"시녀들","titleKeys":["meninas"],"year":"1656","desc":"어린 마르가리타 공주와 시녀들, 그리고 캔버스 앞에 선 화가 자신까지 등장하는 스페인 회화의 최고 걸작이다. 거울에 비친 국왕 부부 등 복잡한 시선의 구조로 끝없는 해석을 낳으며, 프라도 미술관에 있다."},
  {"artistEn":"Diego Velázquez","artistKo":"디에고 벨라스케스","artistKeys":["velazquez","velasquez"],"titleEn":"Old Woman Frying Eggs","titleKo":"달걀을 부치는 노파","titleKeys":["old","woman","frying","eggs"],"year":"1618","desc":"달걀을 부치는 노파와 곁에 선 소년을 그린 젊은 시절의 부엌 정물 그림이다. 도기 그릇과 익어가는 달걀, 놋그릇의 질감을 살린 사실적 묘사에서 십대 후반 벨라스케스의 천재성이 드러난다."},
  {"artistEn":"Diego Velázquez","artistKo":"디에고 벨라스케스","artistKeys":["velazquez","velasquez"],"titleEn":"Portrait of Innocent X","titleKo":"교황 인노첸시오 10세의 초상","titleKeys":["innocent","pope"],"year":"1650","desc":"교황 인노첸시오 10세의 날카로운 눈빛과 위엄을 가감 없이 담아낸 초상화다. 너무나 사실적이라는 교황의 반응이 전해질 만큼 강렬하며, 20세기 화가 프랜시스 베이컨이 여러 차례 변주한 것으로도 유명하다."},
  {"artistEn":"Diego Velázquez","artistKo":"디에고 벨라스케스","artistKeys":["velazquez","velasquez"],"titleEn":"The Rokeby Venus","titleKo":"거울을 보는 비너스","titleKeys":["rokeby","venus","mirror"],"year":"1647–1651","desc":"거울을 보며 비스듬히 누워 있는 비너스의 뒷모습을 그린 벨라스케스의 유일한 누드화다. 큐피드가 든 거울 속에 흐릿하게 비친 얼굴이 신비감을 더하며, 런던 내셔널 갤러리에 소장되어 있다."},
  {"artistEn":"Diego Velázquez","artistKo":"디에고 벨라스케스","artistKeys":["velazquez","velasquez"],"titleEn":"The Surrender of Breda","titleKo":"브레다의 항복","titleKeys":["surrender","breda"],"year":"1634–1635","desc":"네덜란드 브레다 요새의 항복 장면에서 승자가 패자의 어깨에 손을 얹어 예우하는 순간을 그렸다. 하늘을 향해 늘어선 창들 때문에 창들이라는 별칭으로도 불리는 역사화의 걸작이다."},
  {"artistEn":"Edgar Degas","artistKo":"에드가 드가","artistKeys":["degas","edgar degas"],"titleEn":"Blue Dancers","titleKo":"푸른 옷의 무희들","titleKeys":["blue","dancers"],"year":"1897","desc":"무대에 오르기 전 푸른 튀튀를 매만지는 네 명의 무용수를 그린 파스텔화이다. 시력이 나빠진 만년의 드가가 색채와 형태를 더욱 대담하게 밀어붙인 시기의 작품으로, 강렬한 청색의 진동이 화면을 가득 채운다."},
  {"artistEn":"Edgar Degas","artistKo":"에드가 드가","artistKeys":["degas","edgar degas"],"titleEn":"L'Absinthe","titleKo":"압생트","titleKeys":["absinthe"],"year":"1876","desc":"파리 카페에 나란히 앉아 있지만 서로 무관심한 남녀를 그린 작품으로, 여인 앞에는 독한 술 압생트 한 잔이 놓여 있다. 대도시의 소외와 권태를 냉정하게 포착했으며, 발표 당시 퇴폐적이라는 비난을 받았다."},
  {"artistEn":"Edgar Degas","artistKo":"에드가 드가","artistKeys":["degas","edgar degas"],"titleEn":"Little Dancer Aged Fourteen","titleKo":"14세의 어린 무용수","titleKeys":["little","dancer","fourteen"],"year":"1881","desc":"발레 연습생 마리 판 후텀을 모델로 한 조각으로, 밀랍 원작에 실제 튀튀와 머리 리본을 입혀 발표해 큰 충격을 주었다. 드가 생전에 공개된 유일한 조각 작품이며, 사후 청동으로 주조되어 세계 여러 미술관에 소장되어 있다."},
  {"artistEn":"Edgar Degas","artistKo":"에드가 드가","artistKeys":["degas","edgar degas"],"titleEn":"The Ballet Class","titleKo":"발레 수업","titleKeys":["ballet","class"],"year":"1874","desc":"파리 오페라 발레단의 연습실에서 노(老) 발레 교사 쥘 페로의 지도를 받는 어린 무용수들을 그린 작품이다. 수업의 긴장과 지루함이 공존하는 순간을 비스듬한 구도로 포착해 드가 발레 그림의 정수를 보여준다."},
  {"artistEn":"Edgar Degas","artistKo":"에드가 드가","artistKeys":["degas","edgar degas"],"titleEn":"The Bellelli Family","titleKo":"벨렐리 가족","titleKeys":["bellelli","family"],"year":"1858-1867","desc":"이탈리아에 사는 고모 가족을 그린 대형 초상화로, 드가 초기의 대표작이다. 검은 옷의 고모와 두 딸, 등을 돌린 고모부의 배치를 통해 냉랭한 가족 관계의 심리를 치밀하게 드러냈다."},
  {"artistEn":"Edgar Degas","artistKo":"에드가 드가","artistKeys":["degas","edgar degas"],"titleEn":"The Star (Dancer on Stage)","titleKo":"무대 위의 무희 (별)","titleKeys":["star","etoile","dancer"],"year":"1878","desc":"무대 조명을 받으며 홀로 피루엣을 도는 프리마 발레리나를 위에서 내려다본 시점으로 그린 파스텔화이다. 무대 뒤에는 검은 정장의 후원자가 어렴풋이 서 있어 화려함 뒤의 현실을 암시한다."},
  {"artistEn":"Edgar Degas","artistKo":"에드가 드가","artistKeys":["degas","edgar degas"],"titleEn":"The Tub","titleKo":"목욕통","titleKeys":["tub"],"year":"1886","desc":"둥근 대야 안에 웅크린 채 몸을 씻는 여인을 위에서 내려다본 구도로 그린 파스텔화이다. 훔쳐보듯 자연스러운 자세를 포착한 드가 후기 누드 연작의 대표작으로, 일본 판화의 영향을 받은 과감한 시점이 특징이다."},
  {"artistEn":"Édouard Manet","artistKo":"에두아르 마네","artistKeys":["manet","edouard manet"],"titleEn":"A Bar at the Folies-Bergère","titleKo":"폴리베르제르의 술집","titleKeys":["bar","folies","bergere"],"year":"1882","desc":"파리의 화려한 카바레에서 일하는 여종업원이 공허한 표정으로 서 있는 모습을 그린 마네의 마지막 대작이다. 뒤편 거울에 비친 군중과 어긋난 반사상이 독특한 공간감을 만들며 근대 도시의 고독을 담아냈다."},
  {"artistEn":"Édouard Manet","artistKo":"에두아르 마네","artistKeys":["manet","edouard manet"],"titleEn":"Olympia","titleKo":"올랭피아","titleKeys":["olympia"],"year":"1863","desc":"티치아노의 우르비노의 비너스를 현대적으로 재해석해, 신화의 여신 대신 당당한 시선의 매춘부를 그린 작품이다. 1865년 살롱에 전시되자 관객의 시선을 정면으로 응시하는 누드로 거센 논란을 일으키며 근대 회화의 문을 열었다."},
  {"artistEn":"Édouard Manet","artistKo":"에두아르 마네","artistKeys":["manet","edouard manet"],"titleEn":"The Balcony","titleKo":"발코니","titleKeys":["balcony"],"year":"1868","desc":"초록색 난간의 발코니에 선 세 인물을 그린 작품으로, 앉아 있는 여인은 화가 베르트 모리조이다. 고야의 발코니의 마하들에서 영감을 받았으며, 각기 다른 곳을 바라보는 인물들의 심리적 단절이 인상적이다."},
  {"artistEn":"Édouard Manet","artistKo":"에두아르 마네","artistKeys":["manet","edouard manet"],"titleEn":"The Fifer","titleKo":"피리 부는 소년","titleKeys":["fifer","fife"],"year":"1866","desc":"군악대 소년이 피리를 부는 모습을 배경 없는 단색 화면 위에 그린 작품이다. 스페인 화가 벨라스케스의 영향이 엿보이는 평면적 구성과 대담한 색면 처리로, 당시 살롱에서는 낙선했으나 이후 근대 회화의 선구로 재평가되었다."},
  {"artistEn":"Édouard Manet","artistKo":"에두아르 마네","artistKeys":["manet","edouard manet"],"titleEn":"The Luncheon on the Grass","titleKo":"풀밭 위의 점심 식사","titleKeys":["luncheon","grass","dejeuner"],"year":"1863","desc":"정장 차림의 두 남자 사이에 나체의 여인이 앉아 관객을 바라보는 야외 소풍 장면이다. 1863년 낙선전에 전시되어 큰 스캔들을 일으켰으며, 전통 회화의 규범을 깨뜨린 근대 미술의 출발점으로 평가된다."},
  {"artistEn":"Édouard Manet","artistKo":"에두아르 마네","artistKeys":["manet","edouard manet"],"titleEn":"The Railway","titleKo":"철도","titleKeys":["railway"],"year":"1873","desc":"생라자르 역 철책 앞에 앉은 여인과 증기를 바라보는 소녀를 그린 작품이다. 기차 대신 피어오르는 수증기로 철도 시대를 암시하며, 근대 파리의 일상을 참신한 구도로 포착했다. 모델은 마네가 즐겨 그린 빅토린 뫼랑이다."},
  {"artistEn":"Edvard Munch","artistKo":"에드바르 뭉크","artistKeys":["munch","edvard munch","edvardmunch"],"titleEn":"Anxiety","titleKo":"불안","titleKeys":["anxiety"],"year":"1894","desc":"절규와 같은 오슬로 피오르의 핏빛 하늘을 배경으로 창백한 얼굴의 군중을 배치한 작품이다. 개인의 절규를 넘어 집단적인 불안과 소외의 정서를 짙은 색채로 표현한 '생의 프리즈' 연작의 하나다."},
  {"artistEn":"Edvard Munch","artistKo":"에드바르 뭉크","artistKeys":["munch","edvard munch","edvardmunch"],"titleEn":"Madonna","titleKo":"마돈나","titleKeys":["madonna"],"year":"1894-1895","desc":"어두운 배경 속 여인이 붉은 후광을 두른 채 몸을 뒤트는 모습을 그려 관능과 죽음이 공존하는 여인상을 표현했다. 뭉크의 '생의 프리즈' 연작에 속하며 석판화 버전도 널리 알려져 있다."},
  {"artistEn":"Edvard Munch","artistKo":"에드바르 뭉크","artistKeys":["munch","edvard munch","edvardmunch"],"titleEn":"Puberty","titleKo":"사춘기","titleKeys":["puberty"],"year":"1894-1895","desc":"침대에 걸터앉은 소녀가 벽에 드리운 커다란 그림자와 함께 그려져 있다. 사춘기의 불안과 두려움을 정면으로 다룬 작품으로, 당시로서는 파격적인 주제로 주목을 받았다."},
  {"artistEn":"Edvard Munch","artistKo":"에드바르 뭉크","artistKeys":["munch","edvard munch","edvardmunch"],"titleEn":"The Dance of Life","titleKo":"생의 춤","titleKeys":["dance","life"],"year":"1899-1900","desc":"여름밤 해변에서 춤추는 남녀를 통해 순수와 관능, 상실이라는 사랑의 세 단계를 그렸다. 흰옷과 붉은 옷, 검은 옷을 입은 세 여인이 인생의 흐름을 상징하는 '생의 프리즈' 연작의 중심작이다."},
  {"artistEn":"Edvard Munch","artistKo":"에드바르 뭉크","artistKeys":["munch","edvard munch","edvardmunch"],"titleEn":"The Scream","titleKo":"절규","titleKeys":["scream"],"year":"1893","desc":"핏빛 하늘 아래 다리 위에서 두 손으로 얼굴을 감싸고 절규하는 인물을 그렸다. 현대인의 실존적 불안을 상징하는 표현주의의 아이콘으로, 유화와 파스텔 등 여러 버전이 존재한다."},
  {"artistEn":"Edvard Munch","artistKo":"에드바르 뭉크","artistKeys":["munch","edvard munch","edvardmunch"],"titleEn":"The Sick Child","titleKo":"아픈 아이","titleKeys":["sick","child"],"year":"1885-1886","desc":"결핵으로 세상을 떠난 누이 소피에 대한 기억을 담은 작품이다. 병상의 창백한 소녀와 고개 숙인 어머니를 거친 붓질로 그려 발표 당시 미완성이라는 혹평과 함께 큰 논란을 일으켰다."},
  {"artistEn":"Edward Hopper","artistKo":"에드워드 호퍼","artistKeys":["hopper","edward hopper","edwardhopper"],"titleEn":"Automat","titleKo":"오토맷","titleKeys":["automat"],"year":"1927","desc":"무인 식당에 홀로 앉아 커피잔을 내려다보는 여인을 그렸다. 창밖의 어둠에 반사된 실내 조명이 밤의 적막을 키우며, 대도시를 살아가는 현대 여성의 고독을 조용히 강조한다."},
  {"artistEn":"Edward Hopper","artistKo":"에드워드 호퍼","artistKeys":["hopper","edward hopper","edwardhopper"],"titleEn":"Early Sunday Morning","titleKo":"이른 일요일 아침","titleKeys":["early","sunday","morning"],"year":"1930","desc":"이른 아침 인적 없는 상점가 건물을 수평 구도로 담담하게 그렸다. 긴 그림자와 텅 빈 거리, 굳게 닫힌 상점들이 대공황기 미국 도시의 적막한 정서를 전한다."},
  {"artistEn":"Edward Hopper","artistKo":"에드워드 호퍼","artistKeys":["hopper","edward hopper","edwardhopper"],"titleEn":"Gas","titleKo":"주유소","titleKeys":["gas","station"],"year":"1940","desc":"해 질 무렵 시골 도로변 주유소에서 홀로 펌프를 살피는 남자를 그렸다. 환한 인공조명과 어두워지는 숲의 경계가 문명과 자연 사이의 쓸쓸한 긴장을 자아내는 호퍼의 대표작이다."},
  {"artistEn":"Edward Hopper","artistKo":"에드워드 호퍼","artistKeys":["hopper","edward hopper","edwardhopper"],"titleEn":"Nighthawks","titleKo":"밤을 지새우는 사람들","titleKeys":["nighthawks"],"year":"1942","desc":"늦은 밤 도시의 다이너에 앉아 있는 손님들과 종업원을 커다란 유리창 너머로 바라본 구도다. 도시적 고독의 정서를 응축한 20세기 미국 미술의 아이콘으로, 수많은 패러디를 낳았다."},
  {"artistEn":"Egon Schiele","artistKo":"에곤 실레","artistKeys":["schiele","egon schiele","egonschiele"],"titleEn":"Death and the Maiden","titleKo":"죽음과 소녀","titleKeys":["death","maiden"],"year":"1915","desc":"연인 발리와의 이별을 앞두고 그린 작품으로, 죽음의 형상을 한 남자와 그에게 매달린 여인이 황량한 대지 위에 엉켜 있다. 상실과 불안의 감정이 짙게 배어 있는 실레의 대표작이다."},
  {"artistEn":"Egon Schiele","artistKo":"에곤 실레","artistKeys":["schiele","egon schiele","egonschiele"],"titleEn":"Portrait of Wally Neuzil","titleKo":"발리의 초상","titleKeys":["wally","neuzil"],"year":"1912","desc":"실레의 연인이자 모델이었던 발리 노이칠을 그린 초상으로, 커다란 푸른 눈이 인상적이다. 나치에 몰수된 뒤 소유권 분쟁을 겪으며 20세기 미술품 반환 논쟁의 상징이 된 작품이기도 하다."},
  {"artistEn":"Egon Schiele","artistKo":"에곤 실레","artistKeys":["schiele","egon schiele","egonschiele"],"titleEn":"Self-Portrait with Physalis","titleKo":"꽈리 열매가 있는 자화상","titleKeys":["self-portrait","physalis","self"],"year":"1912","desc":"고개를 기울인 화가 자신과 주황빛 꽈리 열매 가지를 나란히 배치한 자화상이다. 날카로운 윤곽선과 정면을 응시하는 불안한 시선이 실레 특유의 표현주의적 긴장감을 보여주는 대표작이다."},
  {"artistEn":"Egon Schiele","artistKo":"에곤 실레","artistKeys":["schiele","egon schiele","egonschiele"],"titleEn":"The Embrace","titleKo":"포옹","titleKeys":["embrace","lovers"],"year":"1917","desc":"구겨진 흰 시트 위에서 서로를 끌어안은 남녀를 그린 후기작이다. 이전의 날 선 불안 대신 부드러운 애정이 느껴지며, 아내 에디트와의 안정된 삶이 반영된 작품으로 해석된다."},
  {"artistEn":"El Greco","artistKo":"엘 그레코","artistKeys":["el greco","greco","elgreco"],"titleEn":"Laocoön","titleKo":"라오콘","titleKeys":["laocoon"],"year":"c. 1610–1614","desc":"뱀에게 공격당하는 트로이의 사제 라오콘과 그의 아들들을 그린 신화화다. 길게 왜곡된 인체와 어두운 하늘, 배경의 톨레도 풍경이 엘 그레코 특유의 불안하고 환상적인 분위기를 자아낸다."},
  {"artistEn":"El Greco","artistKo":"엘 그레코","artistKeys":["el greco","greco","elgreco"],"titleEn":"The Burial of the Count of Orgaz","titleKo":"오르가스 백작의 매장","titleKeys":["burial","count","orgaz"],"year":"1586–1588","desc":"오르가스 백작의 장례에 성인들이 하늘에서 내려와 시신을 직접 묻었다는 전설을 그린 대형 제단화다. 지상의 장례식과 천상의 영접을 위아래로 나눈 구성이 장엄하며, 톨레도의 산토 토메 성당에 소장되어 있다."},
  {"artistEn":"El Greco","artistKo":"엘 그레코","artistKeys":["el greco","greco","elgreco"],"titleEn":"The Disrobing of Christ","titleKo":"그리스도의 옷을 벗김","titleKeys":["disrobing","espolio","christ"],"year":"1577–1579","desc":"십자가형을 앞두고 그리스도의 옷이 벗겨지는 순간을 그린 제단화다. 선명한 붉은 옷의 그리스도를 군중이 빽빽이 에워싼 수직 구도가 강렬하며, 톨레도 대성당 성구실을 위해 제작되었다."},
  {"artistEn":"El Greco","artistKo":"엘 그레코","artistKeys":["el greco","greco","elgreco"],"titleEn":"View of Toledo","titleKo":"톨레도 풍경","titleKeys":["view","toledo"],"year":"c. 1596–1600","desc":"폭풍우가 몰아칠 듯한 하늘 아래 톨레도 시가지를 그린 풍경화다. 실제 지형을 재배치한 극적인 화면과 음산한 초록빛 색조로 서양 풍경화 역사에서 손꼽히는 걸작이 되었으며, 뉴욕 메트로폴리탄 미술관에 있다."},
  {"artistEn":"Élisabeth Vigée Le Brun","artistKo":"엘리자베트 비제 르브룅","artistKeys":["vigee le brun","vigee lebrun","le brun","vigee"],"titleEn":"Marie Antoinette with a Rose","titleKo":"장미를 든 마리 앙투아네트","titleKeys":["marie","antoinette","rose"],"year":"1783","desc":"프랑스 왕비 마리 앙투아네트가 장미를 들고 있는 모습을 그린 공식 초상이다. 왕비의 전속 화가였던 비제 르브룅의 대표작으로, 우아한 드레스와 부드러운 표정으로 왕비의 품위를 강조했다."},
  {"artistEn":"Élisabeth Vigée Le Brun","artistKo":"엘리자베트 비제 르브룅","artistKeys":["vigee le brun","vigee lebrun","le brun","vigee"],"titleEn":"Self-Portrait in a Straw Hat","titleKo":"밀짚모자를 쓴 자화상","titleKeys":["self","portrait","straw","hat"],"year":"1782","desc":"화가 자신이 밀짚모자를 쓰고 팔레트를 든 채 관람자를 바라보는 자화상이다. 루벤스의 초상에서 영감을 받아 야외의 자연광을 표현했으며, 여성 화가로서의 자신감이 화면에 넘친다."},
  {"artistEn":"Élisabeth Vigée Le Brun","artistKo":"엘리자베트 비제 르브룅","artistKeys":["vigee le brun","vigee lebrun","le brun","vigee"],"titleEn":"Self-Portrait with Her Daughter Julie","titleKo":"딸 쥘리와 함께한 자화상","titleKeys":["self","portrait","daughter","julie"],"year":"1786","desc":"화가가 어린 딸 쥘리를 품에 안고 있는 모습을 그린 자화상이다. 모성애를 주제로 한 친밀한 구도가 당시 큰 반향을 일으켰으며, 신고전주의풍의 단정한 옷차림이 특징이다."},
  {"artistEn":"Eugène Delacroix","artistKo":"외젠 들라크루아","artistKeys":["delacroix","eugene delacroix"],"titleEn":"Liberty Leading the People","titleKo":"민중을 이끄는 자유의 여신","titleKeys":["liberty","leading","people"],"year":"1830","desc":"1830년 7월 혁명을 기념해 삼색기를 든 자유의 여신이 민중을 이끄는 모습을 그린 작품이다. 알레고리와 현실의 시가전을 결합한 혁명의 아이콘으로, 프랑스 낭만주의 회화의 상징이 되었다."},
  {"artistEn":"Eugène Delacroix","artistKo":"외젠 들라크루아","artistKeys":["delacroix","eugene delacroix"],"titleEn":"The Barque of Dante","titleKo":"단테의 배","titleKeys":["barque","dante"],"year":"1822","desc":"단테와 베르길리우스가 지옥의 늪을 배로 건너는 신곡의 한 장면을 그린 작품이다. 들라크루아의 살롱 데뷔작으로, 미켈란젤로풍의 인체와 격렬한 명암이 낭만주의의 등장을 예고했다."},
  {"artistEn":"Eugène Delacroix","artistKo":"외젠 들라크루아","artistKeys":["delacroix","eugene delacroix"],"titleEn":"The Death of Sardanapalus","titleKo":"사르다나팔루스의 죽음","titleKeys":["death","sardanapalus"],"year":"1827","desc":"멸망을 앞둔 아시리아 왕이 애첩과 재물을 함께 파괴하도록 명하는 장면을 그린 작품이다. 붉은 색채와 소용돌이치는 구도가 폭력과 관능을 극대화하며, 낭만주의의 과잉미를 대표한다."},
  {"artistEn":"Eugène Delacroix","artistKo":"외젠 들라크루아","artistKeys":["delacroix","eugene delacroix"],"titleEn":"The Massacre at Chios","titleKo":"키오스 섬의 학살","titleKeys":["massacre","chios"],"year":"1824","desc":"그리스 독립전쟁 중 오스만 군이 키오스 섬 주민을 학살한 사건을 그린 작품이다. 죽음을 기다리는 사람들의 무기력한 모습을 전면에 내세워, 동시대의 비극을 회화의 주제로 끌어올렸다."},
  {"artistEn":"Eugène Delacroix","artistKo":"외젠 들라크루아","artistKeys":["delacroix","eugene delacroix"],"titleEn":"Women of Algiers","titleKo":"알제의 여인들","titleKeys":["women","algiers"],"year":"1834","desc":"알제리 여행에서 목격한 하렘의 여인들을 그린 오리엔탈리즘 회화다. 풍부한 색채와 나른한 실내 분위기가 특징이며, 훗날 피카소가 연작으로 변주할 만큼 후대 화가들에게 큰 영향을 주었다."},
  {"artistEn":"Francisco Goya","artistKo":"프란시스코 고야","artistKeys":["goya","francisco goya","francisco de goya"],"titleEn":"Charles IV of Spain and His Family","titleKo":"카를로스 4세의 가족","titleKeys":["charles","carlos","family"],"year":"1800","desc":"스페인 왕 카를로스 4세의 가족을 그린 공식 단체 초상이다. 화려한 의상 속 인물들의 범속한 표정을 숨기지 않아 왕가에 대한 미묘한 풍자로 읽히며, 화면 왼쪽에는 고야 자신이 등장한다."},
  {"artistEn":"Francisco Goya","artistKo":"프란시스코 고야","artistKeys":["goya","francisco goya","francisco de goya"],"titleEn":"Saturn Devouring His Son","titleKo":"아들을 잡아먹는 사투르누스","titleKeys":["saturn","devouring","son"],"year":"c. 1823","desc":"자식에게 왕좌를 빼앗길까 두려워 아들을 삼키는 사투르누스를 그린 작품이다. 고야가 말년에 자택 벽에 그린 '검은 그림' 연작의 하나로, 인간 내면의 광기와 공포를 극한까지 밀어붙였다."},
  {"artistEn":"Francisco Goya","artistKo":"프란시스코 고야","artistKeys":["goya","francisco goya","francisco de goya"],"titleEn":"The Clothed Maja","titleKo":"옷을 입은 마하","titleKeys":["clothed","maja","vestida"],"year":"c. 1805","desc":"옷을 벗은 마하와 같은 자세의 여인을 옷을 입은 모습으로 다시 그린 작품이다. 두 그림은 한 쌍으로 제작되어 나란히 걸렸다고 전해지며, 현재 프라도 미술관에 함께 소장되어 있다."},
  {"artistEn":"Francisco Goya","artistKo":"프란시스코 고야","artistKeys":["goya","francisco goya","francisco de goya"],"titleEn":"The Dog","titleKo":"개","titleKeys":["dog","perro"],"year":"c. 1823","desc":"황량한 화면 아래쪽에 개의 머리만이 모래 언덕 너머로 보이는 수수께끼 같은 그림이다. '검은 그림' 연작 중 하나로, 극도로 비워낸 화면이 고독과 심연의 감정을 자아내 현대 회화의 예언으로 불린다."},
  {"artistEn":"Francisco Goya","artistKo":"프란시스코 고야","artistKeys":["goya","francisco goya","francisco de goya"],"titleEn":"The Nude Maja","titleKo":"옷을 벗은 마하","titleKeys":["nude","maja","desnuda"],"year":"c. 1800","desc":"실존 여성을 신화의 옷을 빌리지 않고 당당한 누드로 그린 파격적인 작품이다. 정면을 응시하는 시선 때문에 종교재판에 회부되는 논란을 겪었으며, 근대 누드화의 선구로 평가된다."},
  {"artistEn":"Francisco Goya","artistKo":"프란시스코 고야","artistKeys":["goya","francisco goya","francisco de goya"],"titleEn":"The Second of May 1808","titleKo":"1808년 5월 2일","titleKeys":["second","may","1808"],"year":"1814","desc":"마드리드 시민들이 나폴레옹 군의 맘루크 기병대에 맞서 봉기한 순간을 그린 작품이다. 뒤엉킨 인마의 혼란스러운 구도가 시가전의 격렬함을 생생히 전하며, 5월 3일과 짝을 이루는 그림이다."},
  {"artistEn":"Francisco Goya","artistKo":"프란시스코 고야","artistKeys":["goya","francisco goya","francisco de goya"],"titleEn":"The Sleep of Reason Produces Monsters","titleKo":"이성이 잠들면 괴물이 깨어난다","titleKeys":["sleep","reason","monsters"],"year":"1799","desc":"책상에 엎드려 잠든 인물 뒤로 박쥐와 올빼미 떼가 몰려드는 판화다. 판화집 '카프리초스'의 대표 도판으로, 이성이 마비된 사회에 대한 계몽주의적 경고를 담은 이미지로 널리 인용된다."},
  {"artistEn":"Francisco Goya","artistKo":"프란시스코 고야","artistKeys":["goya","francisco goya","francisco de goya"],"titleEn":"The Third of May 1808","titleKo":"1808년 5월 3일","titleKeys":["third","may","1808"],"year":"1814","desc":"나폴레옹 군의 마드리드 시민 처형을 그린 작품으로, 흰 셔츠를 입고 두 팔을 벌린 남자가 화면의 중심을 이룬다. 전쟁의 폭력을 고발하는 근대 회화의 이정표로 꼽힌다."},
  {"artistEn":"Francisco Goya","artistKo":"프란시스코 고야","artistKeys":["goya","francisco goya","francisco de goya"],"titleEn":"Witches' Sabbath (The Great He-Goat)","titleKo":"마녀들의 안식일","titleKeys":["witches","sabbath","goat"],"year":"c. 1823","desc":"염소 형상의 악마를 둘러싸고 모여 앉은 군중을 어둡게 그린 '검은 그림' 연작의 하나다. 일그러진 얼굴들의 집단적 광기를 통해 미신과 군중심리에 대한 고야의 비관적 시선을 드러낸다."},
  {"artistEn":"François Boucher","artistKo":"프랑수아 부셰","artistKeys":["boucher","francois boucher"],"titleEn":"Diana Leaving the Bath","titleKo":"목욕을 마친 디아나","titleKeys":["diana","bath"],"year":"1742","desc":"사냥의 여신 디아나가 님프와 함께 목욕을 마친 순간을 그린 작품이다. 진주빛 피부와 부드러운 색채가 돋보이며, 신화를 빌려 관능적 아름다움을 표현한 로코코 회화의 전형을 보여준다."},
  {"artistEn":"François Boucher","artistKo":"프랑수아 부셰","artistKeys":["boucher","francois boucher"],"titleEn":"Madame de Pompadour","titleKo":"퐁파두르 부인의 초상","titleKeys":["madame","pompadour"],"year":"1756","desc":"루이 15세의 애첩이자 예술 후원자였던 퐁파두르 부인을 화려한 드레스 차림으로 그린 초상이다. 책과 장식품에 둘러싸인 모습으로 그녀의 교양과 취향을 강조했으며, 로코코 초상화의 정수로 꼽힌다."},
  {"artistEn":"Frans Hals","artistKo":"프란스 할스","artistKeys":["hals","frans hals","franshals"],"titleEn":"Gypsy Girl","titleKo":"집시 소녀","titleKeys":["gypsy","girl"],"year":"c. 1628–1630","desc":"헝클어진 머리의 젊은 여인이 장난기 어린 미소를 짓는 순간을 포착한 작품이다. 빠르고 자유로운 붓질로 살아 있는 듯한 인상을 만들어내는 할스 초상화의 매력이 잘 드러나며, 루브르 박물관에 소장되어 있다."},
  {"artistEn":"Frans Hals","artistKo":"프란스 할스","artistKeys":["hals","frans hals","franshals"],"titleEn":"Malle Babbe","titleKo":"말레 바베","titleKeys":["malle","babbe"],"year":"c. 1633–1635","desc":"올빼미를 어깨에 얹고 맥주잔을 쥔 채 웃음을 터뜨리는 노파를 그린 작품으로, 하를럼의 실존 인물을 모델로 한 것으로 전해진다. 순간의 표정을 낚아채는 거친 붓놀림이 인상파를 앞서 보여주는 듯하다."},
  {"artistEn":"Frans Hals","artistKo":"프란스 할스","artistKeys":["hals","frans hals","franshals"],"titleEn":"The Laughing Cavalier","titleKo":"웃는 기사","titleKeys":["laughing","cavalier"],"year":"1624","desc":"콧수염을 치켜올린 남자가 자신만만한 표정을 짓고 있는 초상화로, 실제로 웃고 있지는 않지만 생기 넘치는 인상 덕에 이 별명이 붙었다. 소매의 화려한 자수 묘사와 활달한 붓질이 돋보이는 할스의 대표작이다."},
  {"artistEn":"Frederic Leighton","artistKo":"프레더릭 레이턴","artistKeys":["leighton","frederic leighton","lord leighton"],"titleEn":"Flaming June","titleKo":"타오르는 6월","titleKeys":["flaming","june"],"year":"1895","desc":"주황빛 드레스를 입은 여인이 잠든 모습을 그린 작품으로, 빅토리아 시대 회화의 아이콘이다. 지중해의 빛나는 바다를 배경으로 한 관능적이면서도 고전적인 구성이 강렬한 색채와 어우러진다."},
  {"artistEn":"Frederic Leighton","artistKo":"프레더릭 레이턴","artistKeys":["leighton","frederic leighton","lord leighton"],"titleEn":"The Bath of Psyche","titleKo":"프시케의 목욕","titleKeys":["bath","psyche"],"year":"c. 1890","desc":"에로스를 기다리며 목욕하는 프시케가 물에 비친 제 모습을 바라보는 장면을 그린 작품이다. 고대 조각을 연상시키는 유려한 인체와 대리석 기둥의 수직 구도가 고전주의적 우아함을 자아낸다."},
  {"artistEn":"Frida Kahlo","artistKo":"프리다 칼로","artistKeys":["kahlo","frida kahlo","fridakahlo","frida"],"titleEn":"Self-Portrait with Thorn Necklace and Hummingbird","titleKo":"가시 목걸이와 벌새가 있는 자화상","titleKeys":["thorn","necklace","hummingbird"],"year":"1940","desc":"가시 목걸이가 목을 파고드는 자화상으로, 목걸이에는 검은 벌새가 매달려 있다. 어깨 위의 원숭이와 검은 고양이를 대동한 채 고통을 정면으로 응시하는 담담한 시선이 강렬하다."},
  {"artistEn":"Frida Kahlo","artistKo":"프리다 칼로","artistKeys":["kahlo","frida kahlo","fridakahlo","frida"],"titleEn":"The Broken Column","titleKo":"부러진 기둥","titleKeys":["broken","column"],"year":"1944","desc":"척추 수술 이후의 고통을 그린 자화상으로, 갈라진 몸속에 부서진 이오니아식 기둥이 척추를 대신하고 있다. 온몸에 박힌 못과 흐르는 눈물이 평생 이어진 육체적 고통을 증언한다."},
  {"artistEn":"Frida Kahlo","artistKo":"프리다 칼로","artistKeys":["kahlo","frida kahlo","fridakahlo","frida"],"titleEn":"The Two Fridas","titleKo":"두 명의 프리다","titleKeys":["two","fridas"],"year":"1939","desc":"유럽식 드레스와 멕시코 전통 의상을 입은 두 명의 프리다가 손을 잡고 앉아 있으며, 두 심장이 혈관으로 연결되어 있다. 디에고 리베라와의 이혼 직후 그린 분열된 정체성의 자화상이다."},
  {"artistEn":"Georges Seurat","artistKo":"조르주 쇠라","artistKeys":["seurat","georges seurat"],"titleEn":"A Sunday Afternoon on the Island of La Grande Jatte","titleKo":"그랑드자트 섬의 일요일 오후","titleKeys":["grande","jatte","sunday"],"year":"1884-1886","desc":"센 강의 그랑드자트 섬에서 휴일을 보내는 파리 시민들을 무수한 색점으로 그린 점묘법의 기념비적 대작이다. 쇠라는 2년에 걸쳐 수십 점의 습작을 그리며 화면을 과학적으로 구축했고, 신인상주의의 출발점이 되었다."},
  {"artistEn":"Georges Seurat","artistKo":"조르주 쇠라","artistKeys":["seurat","georges seurat"],"titleEn":"Bathers at Asnières","titleKo":"아니에르에서의 물놀이","titleKeys":["bathers","asnieres"],"year":"1884","desc":"파리 교외 아니에르의 센 강변에서 더위를 식히는 노동자 계층 젊은이들을 그린 쇠라의 첫 대작이다. 고전적 정지감과 여름 빛의 표현이 어우러지며, 멀리 공장 굴뚝이 산업화 시대의 배경을 이룬다."},
  {"artistEn":"Georges Seurat","artistKo":"조르주 쇠라","artistKeys":["seurat","georges seurat"],"titleEn":"Le Chahut","titleKo":"샤위 춤","titleKeys":["chahut"],"year":"1889-1890","desc":"카바레 무대에서 다리를 높이 차올리며 샤위 춤을 추는 무용수들을 그린 작품이다. 위로 뻗는 사선과 반복되는 곡선을 통해 흥겨움을 조형적으로 표현하려 한 쇠라 후기의 이론적 실험이 집약되어 있다."},
  {"artistEn":"Georges Seurat","artistKo":"조르주 쇠라","artistKeys":["seurat","georges seurat"],"titleEn":"The Circus","titleKo":"서커스","titleKeys":["circus","cirque"],"year":"1891","desc":"서커스장에서 백마 위에 선 곡예사와 광대, 객석의 관중을 그린 쇠라의 마지막 작품이다. 노랑, 빨강, 파랑의 삼원색을 중심으로 한 점묘와 상승하는 곡선의 율동이 특징이며, 31세로 요절해 미완성으로 남았다."},
  {"artistEn":"Georgia O'Keeffe","artistKo":"조지아 오키프","artistKeys":["okeeffe","o'keeffe","georgia okeeffe","georgia o'keeffe"],"titleEn":"Cow's Skull: Red, White, and Blue","titleKo":"소의 두개골: 빨강, 하양, 파랑","titleKeys":["cow","skull","red","white","blue"],"year":"1931","desc":"붉고 푸른 띠를 배경으로 소의 두개골을 정면에 배치한 작품이다. 뉴멕시코 사막에서 주운 뼈를 성조기의 색과 결합해 유럽과 구별되는 미국적 정체성을 상징적으로 표현했다."},
  {"artistEn":"Georgia O'Keeffe","artistKo":"조지아 오키프","artistKeys":["okeeffe","o'keeffe","georgia okeeffe","georgia o'keeffe"],"titleEn":"Jimson Weed/White Flower No. 1","titleKo":"흰독말풀/흰 꽃 1번","titleKeys":["jimson","weed","white","flower"],"year":"1932","desc":"흰독말풀 꽃 한 송이를 화면 가득 확대해 그린 작품이다. 꽃의 내부를 추상에 가깝게 담아낸 오키프 꽃 연작의 대표작으로, 2014년 여성 화가 작품 경매 최고가 기록을 세운 바 있다."},
  {"artistEn":"Georgia O'Keeffe","artistKo":"조지아 오키프","artistKeys":["okeeffe","o'keeffe","georgia okeeffe","georgia o'keeffe"],"titleEn":"Oriental Poppies","titleKo":"동양 양귀비","titleKeys":["oriental","poppies","poppy"],"year":"1927","desc":"선명한 주홍빛 양귀비 두 송이를 화면 가득 클로즈업한 작품이다. 바쁜 현대인들이 꽃을 제대로 들여다보게 하려고 일부러 크게 그린다는 오키프의 의도가 잘 드러나 있다."},
  {"artistEn":"Giorgione","artistKo":"조르조네","artistKeys":["giorgione"],"titleEn":"Sleeping Venus","titleKo":"잠자는 비너스","titleKeys":["sleeping","venus"],"year":"c. 1508–1510","desc":"전원 풍경 속에 잠든 비너스의 누드를 그린 작품으로, 비스듬히 누운 비너스 도상의 원형이 되었다. 조르조네가 완성하지 못하고 요절하자 티치아노가 풍경 부분을 마무리한 것으로 전해진다."},
  {"artistEn":"Giorgione","artistKo":"조르조네","artistKeys":["giorgione"],"titleEn":"The Tempest","titleKo":"폭풍우","titleKeys":["tempest","storm"],"year":"c. 1508","desc":"번개가 치는 하늘 아래 병사와 아기에게 젖을 먹이는 여인이 있는 수수께끼 같은 풍경화다. 명확한 주제가 지금까지 밝혀지지 않아 서양 미술사에서 가장 신비로운 그림 중 하나로 꼽히며, 베네치아 아카데미아 미술관에 있다."},
  {"artistEn":"Giovanni Battista Tiepolo","artistKo":"조반니 바티스타 티에폴로","artistKeys":["tiepolo","giovanni battista tiepolo","giambattista tiepolo"],"titleEn":"The Banquet of Cleopatra","titleKo":"클레오파트라의 연회","titleKeys":["banquet","cleopatra"],"year":"c. 1744","desc":"클레오파트라가 안토니우스와의 내기에서 진주를 식초에 녹여 마시려는 순간을 그린 작품이다. 웅장한 건축 배경과 화려한 색채가 어우러져, 베네치아 후기 바로크·로코코 회화의 장대함을 보여준다."},
  {"artistEn":"Giuseppe Arcimboldo","artistKo":"주세페 아르침볼도","artistKeys":["arcimboldo","giuseppe"],"titleEn":"Summer","titleKo":"여름","titleKeys":["summer","seasons"],"year":"1563","desc":"여름 과일과 채소를 짜맞춰 사람의 옆얼굴을 만든 사계절 연작 중 하나다. 가까이 보면 정물이고 멀리서 보면 초상이 되는 이중 이미지의 재치가 돋보이며, 복숭아 뺨과 오이 코 등 세부를 찾아보는 재미가 있다."},
  {"artistEn":"Giuseppe Arcimboldo","artistKo":"주세페 아르침볼도","artistKeys":["arcimboldo","giuseppe"],"titleEn":"The Librarian","titleKo":"사서","titleKeys":["librarian","books"],"year":"c. 1566","desc":"책을 쌓아 올려 사람의 형상을 만든 초상화로, 책에 파묻힌 학자를 유머러스하게 표현했다. 사물을 조합해 인물을 만드는 아르침볼도 특유의 발상이 잘 드러난 작품으로, 초현실주의자들에게도 영감을 주었다."},
  {"artistEn":"Giuseppe Arcimboldo","artistKo":"주세페 아르침볼도","artistKeys":["arcimboldo","giuseppe"],"titleEn":"Vertumnus","titleKo":"베르툼누스","titleKeys":["vertumnus"],"year":"c. 1590–1591","desc":"과일과 채소, 꽃을 조합해 신성로마제국 황제 루돌프 2세의 얼굴을 만든 초상화다. 계절의 신 베르툼누스에 황제를 빗대어 풍요로운 치세를 찬양한 작품으로, 아르침볼도 특유의 기발한 상상력이 정점에 달했다."},
  {"artistEn":"Grant Wood","artistKo":"그랜트 우드","artistKeys":["grant wood","grantwood","wood"],"titleEn":"American Gothic","titleKo":"아메리칸 고딕","titleKeys":["american","gothic"],"year":"1930","desc":"쇠스랑을 든 농부와 딸이 고딕풍 창문이 있는 집 앞에 나란히 선 모습을 그렸다. 미국 중서부인의 근면과 완고함을 담은 초상으로, 미국 미술에서 가장 많이 패러디된 작품이다."},
  {"artistEn":"Gustav Klimt","artistKo":"구스타프 클림트","artistKeys":["klimt","gustav klimt","gustavklimt"],"titleEn":"Danae","titleKo":"다나에","titleKeys":["danae"],"year":"1907","desc":"그리스 신화에서 황금 비로 변한 제우스가 갇혀 있는 다나에를 찾아오는 장면을 그렸다. 웅크린 여인의 몸과 쏟아지는 금빛 물줄기가 어우러져 관능적 아름다움을 극대화한 클림트 황금시대의 대표작이다."},
  {"artistEn":"Gustav Klimt","artistKo":"구스타프 클림트","artistKeys":["klimt","gustav klimt","gustavklimt"],"titleEn":"Death and Life","titleKo":"죽음과 삶","titleKeys":["death","life"],"year":"1910-1915","desc":"해골 형상의 죽음이 화려한 색으로 뒤엉킨 인간 군상을 건너다보는 구도의 작품이다. 삶의 순환과 죽음의 공존이라는 주제를 장식적 색채로 풀어냈으며, 클림트 스스로 자신의 대표작으로 꼽았다."},
  {"artistEn":"Gustav Klimt","artistKo":"구스타프 클림트","artistKeys":["klimt","gustav klimt","gustavklimt"],"titleEn":"Judith and the Head of Holofernes (Judith I)","titleKo":"유디트 I","titleKeys":["judith","holofernes"],"year":"1901","desc":"구약의 여인 유디트가 적장 홀로페르네스의 머리를 든 모습을 관능적으로 재해석했다. 황금 장식과 몽환적인 표정이 결합되어 발표 당시 큰 논란을 불렀으며, 클림트 황금시대의 시작을 알린 작품으로 꼽힌다."},
  {"artistEn":"Gustav Klimt","artistKo":"구스타프 클림트","artistKeys":["klimt","gustav klimt","gustavklimt"],"titleEn":"Portrait of Adele Bloch-Bauer I","titleKo":"아델레 블로흐바우어의 초상 I","titleKeys":["adele","bloch","bauer"],"year":"1907","desc":"빈 사교계 여성 아델레 블로흐바우어를 금박과 장식 문양으로 감싼 초상화다. '오스트리아의 모나리자'로 불리며, 나치 몰수와 반환 소송을 거쳐 2006년 당시 회화 최고가로 거래되어 세계적 화제가 되었다."},
  {"artistEn":"Gustav Klimt","artistKo":"구스타프 클림트","artistKeys":["klimt","gustav klimt","gustavklimt"],"titleEn":"The Kiss","titleKo":"키스","titleKeys":["kiss"],"year":"1907-1908","desc":"황금빛 옷을 두른 연인이 꽃밭 위에서 입을 맞추는 장면을 담은 클림트 황금시대의 대표작이다. 금박과 장식 문양이 화면을 가득 채우며 사랑의 절정을 표현한다. 빈 벨베데레 미술관이 소장한 오스트리아의 국민적 작품이다."},
  {"artistEn":"Gustav Klimt","artistKo":"구스타프 클림트","artistKeys":["klimt","gustav klimt","gustavklimt"],"titleEn":"The Tree of Life (Stoclet Frieze)","titleKo":"생명의 나무","titleKeys":["tree","life","stoclet"],"year":"c. 1909","desc":"브뤼셀 스토클레 저택의 벽면 장식을 위해 그린 밑그림으로, 소용돌이치며 뻗어 나가는 생명의 나무를 담았다. 좌우에 기다림과 포옹을 상징하는 인물이 배치되어 있으며 클림트 장식미술의 정수로 꼽힌다."},
  {"artistEn":"Gustave Caillebotte","artistKo":"귀스타브 카유보트","artistKeys":["caillebotte","gustave caillebotte"],"titleEn":"Le Pont de l'Europe","titleKo":"유럽교","titleKeys":["pont","europe","bridge"],"year":"1876","desc":"생라자르 역 위를 가로지르는 철교 유럽교 위의 산책자와 노동자를 그린 작품이다. 강철 트러스 구조가 화면을 대담하게 사선으로 가르며, 산업 시대 파리의 새로운 풍경을 정밀한 원근법으로 포착했다."},
  {"artistEn":"Gustave Caillebotte","artistKo":"귀스타브 카유보트","artistKeys":["caillebotte","gustave caillebotte"],"titleEn":"Paris Street; Rainy Day","titleKo":"파리의 거리, 비 오는 날","titleKeys":["paris","street","rainy","day"],"year":"1877","desc":"비 내리는 파리의 교차로를 우산 쓴 행인들과 함께 그린 대작이다. 오스만 남작의 도시 개조로 탄생한 신식 거리의 정경을 사진 같은 원근법과 치밀한 구도로 담아, 근대 도시 회화의 기념비로 평가된다."},
  {"artistEn":"Gustave Caillebotte","artistKo":"귀스타브 카유보트","artistKeys":["caillebotte","gustave caillebotte"],"titleEn":"The Floor Scrapers","titleKo":"마루를 깎는 사람들","titleKeys":["floor","scrapers","planers"],"year":"1875","desc":"웃옷을 벗은 세 노동자가 아파트 마루 바닥을 대패로 깎는 모습을 그린 작품이다. 도시 노동자를 정면으로 다룬 드문 소재와 역광의 사실적 묘사가 돋보이며, 살롱 낙선 후 인상파 전시에서 호평을 받았다."},
  {"artistEn":"Gustave Caillebotte","artistKo":"귀스타브 카유보트","artistKeys":["caillebotte","gustave caillebotte"],"titleEn":"Young Man at His Window","titleKo":"창가의 젊은 남자","titleKeys":["young","man","window"],"year":"1876","desc":"발코니 창가에 서서 파리 거리를 내려다보는 남자의 뒷모습을 그린 작품으로, 모델은 화가의 동생 르네이다. 실내의 어둠과 바깥의 밝은 도시가 대비되며, 근대 도시를 바라보는 시선 자체를 주제로 삼았다."},
  {"artistEn":"Gustave Courbet","artistKo":"귀스타브 쿠르베","artistKeys":["courbet","gustave courbet"],"titleEn":"A Burial at Ornans","titleKo":"오르낭의 매장","titleKeys":["burial","ornans"],"year":"1850","desc":"고향 오르낭의 평범한 장례식을 역사화 규모의 대화면에 그린 작품이다. 영웅이 아닌 시골 사람들을 기념비적으로 담아 아카데미 전통에 도전했으며, 사실주의 선언과 같은 그림으로 평가된다."},
  {"artistEn":"Gustave Courbet","artistKo":"귀스타브 쿠르베","artistKeys":["courbet","gustave courbet"],"titleEn":"The Artist's Studio","titleKo":"화가의 아틀리에","titleKeys":["artist","studio","atelier"],"year":"1855","desc":"화가 자신을 중심으로 당대 사회의 인물 군상을 좌우에 배치한 대작이다. '나의 7년간의 예술적 삶을 요약한 현실적 알레고리'라는 부제처럼, 예술가의 사회적 위치에 대한 선언을 담았다."},
  {"artistEn":"Gustave Courbet","artistKo":"귀스타브 쿠르베","artistKeys":["courbet","gustave courbet"],"titleEn":"The Desperate Man","titleKo":"절망하는 남자","titleKeys":["desperate","man"],"year":"c. 1845","desc":"두 손으로 머리카락을 움켜쥔 채 눈을 부릅뜬 젊은 쿠르베 자신을 그린 자화상이다. 극단적인 표정과 클로즈업 구도가 강렬한 인상을 남기며, 오늘날 인터넷에서도 널리 회자되는 이미지다."},
  {"artistEn":"Gustave Courbet","artistKo":"귀스타브 쿠르베","artistKeys":["courbet","gustave courbet"],"titleEn":"The Stone Breakers","titleKo":"돌 깨는 사람들","titleKeys":["stone","breakers"],"year":"1849","desc":"길가에서 돌을 깨는 노인과 소년의 고된 노동을 실물 크기로 그린 작품이다. 이상화 없는 노동 묘사로 사실주의의 강령이 된 그림이며, 2차 대전 중 드레스덴에서 소실되어 사진으로만 전한다."},
  {"artistEn":"Hans Holbein the Younger","artistKo":"소 한스 홀바인","artistKeys":["holbein","hans holbein"],"titleEn":"Portrait of Erasmus of Rotterdam","titleKo":"에라스뮈스의 초상","titleKeys":["erasmus","rotterdam"],"year":"1523","desc":"인문학자 에라스뮈스가 책상에 앉아 글을 쓰는 옆모습을 그린 초상화다. 학자의 집중된 표정과 절제된 화면 구성으로 르네상스 지식인 초상의 전형을 확립한 작품으로 평가된다."},
  {"artistEn":"Hans Holbein the Younger","artistKo":"소 한스 홀바인","artistKeys":["holbein","hans holbein"],"titleEn":"Portrait of Henry VIII","titleKo":"헨리 8세의 초상","titleKeys":["henry","viii","king"],"year":"c. 1537","desc":"잉글랜드 국왕 헨리 8세를 정면에 가깝게 배치해 위엄과 권력을 과시하는 초상이다. 화려한 의상과 보석의 정밀한 묘사가 궁정화가 홀바인의 기량을 보여주며, 이후 왕의 공식 이미지의 원형이 되었다."},
  {"artistEn":"Hans Holbein the Younger","artistKo":"소 한스 홀바인","artistKeys":["holbein","hans holbein"],"titleEn":"The Ambassadors","titleKo":"대사들","titleKeys":["ambassadors"],"year":"1533","desc":"두 명의 프랑스 외교관과 지식을 상징하는 도구들을 정교하게 그린 초상화다. 화면 아래쪽에 비스듬히 왜곡된 해골이 숨어 있어 죽음을 기억하라는 메시지를 담은 작품으로 유명하며, 런던 내셔널 갤러리에 있다."},
  {"artistEn":"Henri de Toulouse-Lautrec","artistKo":"앙리 드 툴루즈 로트레크","artistKeys":["toulouse lautrec","lautrec","toulouse-lautrec"],"titleEn":"At the Moulin Rouge","titleKo":"물랭 루주에서","titleKeys":["moulin","rouge"],"year":"1892-1895","desc":"물랭 루주의 테이블에 둘러앉은 친구들과 뒤편의 무희 라 굴뤼, 오른쪽의 초록빛 얼굴 여인을 그린 작품이다. 화가 자신도 배경에 작게 그려 넣었으며, 파리 밤 문화의 화려함과 쓸쓸함을 동시에 포착했다."},
  {"artistEn":"Henri de Toulouse-Lautrec","artistKo":"앙리 드 툴루즈 로트레크","artistKeys":["toulouse lautrec","lautrec","toulouse-lautrec"],"titleEn":"Jane Avril","titleKo":"잔 아브릴","titleKeys":["jane","avril"],"year":"1893","desc":"카바레 무희 잔 아브릴이 다리를 차올리며 춤추는 모습을 담은 석판화 포스터이다. 오케스트라의 콘트라베이스 목이 화면 틀을 이루는 기발한 구성이 특징이며, 로트레크와 아브릴의 우정은 여러 작품으로 이어졌다."},
  {"artistEn":"Henri de Toulouse-Lautrec","artistKo":"앙리 드 툴루즈 로트레크","artistKeys":["toulouse lautrec","lautrec","toulouse-lautrec"],"titleEn":"Moulin Rouge: La Goulue","titleKo":"물랭 루주: 라 굴뤼","titleKeys":["moulin","rouge","goulue"],"year":"1891","desc":"물랭 루주의 간판 무희 라 굴뤼를 홍보하기 위해 제작한 석판화 포스터로, 로트레크의 첫 포스터 작품이다. 대담한 실루엣과 평면적 색면, 과감한 생략이 파리 거리를 뒤흔들며 포스터를 예술의 반열에 올렸다."},
  {"artistEn":"Henri de Toulouse-Lautrec","artistKo":"앙리 드 툴루즈 로트레크","artistKeys":["toulouse lautrec","lautrec","toulouse-lautrec"],"titleEn":"The Salon at the Rue des Moulins","titleKo":"물랭 가의 살롱","titleKeys":["salon","rue","moulins"],"year":"1894","desc":"파리 물랭 가 사창가의 응접실에서 손님을 기다리는 여인들을 그린 작품이다. 로트레크는 이곳에 머물며 여인들의 일상을 편견 없는 시선으로 관찰했고, 붉은 소파와 나른한 표정들 속에 연민 어린 사실성을 담았다."},
  {"artistEn":"Henri Fantin-Latour","artistKo":"앙리 팡탱라투르","artistKeys":["fantin-latour","fantin latour","henri fantin-latour","fantinlatour"],"titleEn":"A Basket of Roses","titleKo":"장미 바구니","titleKeys":["basket","roses"],"year":"1890","desc":"탁자 위 바구니에 소담하게 담긴 장미를 섬세한 필치로 그린 정물화다. 팡탱라투르는 사실적이면서도 시적인 꽃 정물로 19세기 후반 영국과 프랑스에서 큰 사랑을 받았다."},
  {"artistEn":"Henri Matisse","artistKo":"앙리 마티스","artistKeys":["matisse","henri matisse","henrimatisse"],"titleEn":"Blue Nude II","titleKo":"푸른 누드 II","titleKeys":["blue","nude"],"year":"1952","desc":"말년의 마티스가 붓 대신 가위로 색종이를 오려 만든 '컷아웃' 기법의 대표작이다. 파란 종이 조각만으로 웅크린 여인의 신체를 간결하게 구성해 조각과 회화의 경계를 허물었다는 평가를 받는다."},
  {"artistEn":"Henri Matisse","artistKo":"앙리 마티스","artistKeys":["matisse","henri matisse","henrimatisse"],"titleEn":"Goldfish","titleKo":"금붕어","titleKeys":["goldfish"],"year":"1912","desc":"유리 어항 속 주홍빛 금붕어 네 마리를 화면 중심에 둔 정물화다. 모로코 여행 이후 한층 밝아진 색채와 명상적인 분위기가 어우러진 금붕어 연작 가운데 가장 유명한 작품이다."},
  {"artistEn":"Henri Matisse","artistKo":"앙리 마티스","artistKeys":["matisse","henri matisse","henrimatisse"],"titleEn":"The Dance","titleKo":"춤","titleKeys":["dance","danse"],"year":"1910","desc":"붉은 몸의 다섯 인물이 손을 잡고 원을 그리며 춤추는 장면을 그렸다. 파랑, 초록, 빨강 세 가지 색만으로 원초적 생명력을 표현했으며, 러시아 수집가 슈킨의 주문으로 제작된 마티스의 대표작이다."},
  {"artistEn":"Henri Matisse","artistKo":"앙리 마티스","artistKeys":["matisse","henri matisse","henrimatisse"],"titleEn":"The Dessert: Harmony in Red","titleKo":"붉은 방(붉은색의 조화)","titleKeys":["harmony","red","dessert","red room"],"year":"1908","desc":"붉은 벽지와 식탁보가 하나로 이어진 실내에서 과일을 정리하는 여인을 그렸다. 원근법 대신 평면적 장식성을 택해 회화의 새로운 방향을 제시한 마티스 혁신의 이정표로 꼽힌다."},
  {"artistEn":"Henri Matisse","artistKo":"앙리 마티스","artistKeys":["matisse","henri matisse","henrimatisse"],"titleEn":"Woman with a Hat","titleKo":"모자를 쓴 여인","titleKeys":["woman","hat"],"year":"1905","desc":"아내 아멜리를 그린 초상으로, 얼굴과 모자에 실제 색을 무시한 강렬한 원색을 사용했다. 1905년 살롱 도톤에 전시되어 '야수파'라는 이름이 생겨나는 계기가 된 미술사적 작품이다."},
  {"artistEn":"Henri Rousseau","artistKo":"앙리 루소","artistKeys":["rousseau","henri rousseau"],"titleEn":"A Carnival Evening","titleKo":"카니발 저녁","titleKeys":["carnival","evening"],"year":"1886","desc":"겨울 밤 앙상한 숲 앞에 카니발 의상을 입은 남녀가 달빛을 받으며 서 있는 초기 대표작이다. 어두운 숲과 환하게 빛나는 두 인물의 대비가 몽환적이며, 독학 화가 루소 특유의 시적 정취가 일찍부터 드러난다."},
  {"artistEn":"Henri Rousseau","artistKo":"앙리 루소","artistKeys":["rousseau","henri rousseau"],"titleEn":"The Dream","titleKo":"꿈","titleKeys":["dream"],"year":"1910","desc":"울창한 정글 한가운데 붉은 소파에 누운 나체의 여인과 피리 부는 검은 형상, 숨어 있는 동물들을 그린 루소 최후의 대작이다. 세관원 출신 독학 화가의 상상력이 절정에 달한 작품으로, 발표 직후 그는 세상을 떠났다."},
  {"artistEn":"Henri Rousseau","artistKo":"앙리 루소","artistKeys":["rousseau","henri rousseau"],"titleEn":"The Sleeping Gypsy","titleKo":"잠자는 집시","titleKeys":["sleeping","gypsy"],"year":"1897","desc":"달빛 아래 사막에서 잠든 집시 여인 곁에 사자가 다가와 냄새를 맡는 환상적 장면을 그린 작품이다. 만돌린과 물병이 놓인 고요한 화면은 꿈과 현실의 경계를 넘나들며, 초현실주의자들에게 큰 영감을 주었다."},
  {"artistEn":"Henri Rousseau","artistKo":"앙리 루소","artistKeys":["rousseau","henri rousseau"],"titleEn":"The Snake Charmer","titleKo":"뱀을 부리는 여인","titleKeys":["snake","charmer"],"year":"1907","desc":"달빛이 비치는 강가에서 피리를 불어 뱀들을 불러 모으는 검은 실루엣의 여인을 그린 작품이다. 화가 들로네의 어머니가 들려준 인도 여행담에서 영감을 얻었으며, 신비롭고 원초적인 분위기가 화면을 지배한다."},
  {"artistEn":"Henri Rousseau","artistKo":"앙리 루소","artistKeys":["rousseau","henri rousseau"],"titleEn":"Tiger in a Tropical Storm (Surprised!)","titleKo":"열대 폭풍 속의 호랑이 (놀람!)","titleKeys":["tiger","tropical","storm","surprised"],"year":"1891","desc":"폭풍우 치는 정글 속에서 몸을 낮춘 호랑이가 먹잇감을 덮치려는 순간을 그린 루소의 첫 정글 그림이다. 프랑스를 떠난 적 없는 루소는 파리 식물원과 그림책에서 본 이미지로 환상의 열대를 창조해냈다."},
  {"artistEn":"Hieronymus Bosch","artistKo":"히에로니무스 보스","artistKeys":["bosch","hieronymus"],"titleEn":"The Garden of Earthly Delights","titleKo":"쾌락의 정원","titleKeys":["garden","earthly","delights"],"year":"c. 1490–1510","desc":"에덴동산, 쾌락에 빠진 인간 세상, 지옥을 차례로 그린 세 폭 제단화다. 기괴한 상상 속 생물과 상징으로 가득한 화면은 인간의 욕망과 타락에 대한 경고로 해석되며, 프라도 미술관의 대표 소장품 중 하나다."},
  {"artistEn":"Hieronymus Bosch","artistKo":"히에로니무스 보스","artistKeys":["bosch","hieronymus"],"titleEn":"The Haywain Triptych","titleKo":"건초 수레","titleKeys":["haywain","hay","wain"],"year":"c. 1516","desc":"거대한 건초 수레를 둘러싸고 재물을 좇아 아우성치는 인간 군상을 그린 세 폭 제단화다. 덧없는 세속의 욕심을 풍자하는 우화적 장면들이 화면 곳곳에 배치되어 있으며, 수레는 지옥을 향해 나아간다."},
  {"artistEn":"Hieronymus Bosch","artistKo":"히에로니무스 보스","artistKeys":["bosch","hieronymus"],"titleEn":"The Ship of Fools","titleKo":"바보들의 배","titleKeys":["ship","fools"],"year":"c. 1490–1500","desc":"작은 배 위에서 수도사와 수녀까지 어울려 먹고 마시며 흥청거리는 사람들을 그린 풍자화다. 방향타 없이 떠도는 배는 어리석음에 빠진 인간 사회에 대한 은유로 해석되며, 루브르 박물관에 소장되어 있다."},
  {"artistEn":"Honoré Daumier","artistKo":"오노레 도미에","artistKeys":["daumier","honore daumier"],"titleEn":"The Laundress","titleKo":"세탁부","titleKeys":["laundress"],"year":"c. 1863","desc":"빨래 꾸러미를 들고 아이의 손을 잡은 채 계단을 오르는 세탁부를 그린 작품이다. 역광 속 단순화된 형태가 조각적인 무게감을 자아내며, 노동하는 여성에 대한 존중의 시선이 담겨 있다."},
  {"artistEn":"Honoré Daumier","artistKo":"오노레 도미에","artistKeys":["daumier","honore daumier"],"titleEn":"The Third-Class Carriage","titleKo":"삼등 열차","titleKeys":["third","class","carriage"],"year":"c. 1864","desc":"삼등 열차 객실에 앉은 서민 가족의 지친 모습을 그린 작품이다. 아기를 안은 여인과 노파, 잠든 소년을 통해 도시 서민의 삶을 따뜻하고도 사실적으로 포착한 도미에의 대표작이다."},
  {"artistEn":"Ilya Repin","artistKo":"일리야 레핀","artistKeys":["repin","ilya repin"],"titleEn":"Barge Haulers on the Volga","titleKo":"볼가 강의 배 끄는 인부들","titleKeys":["barge","haulers","volga"],"year":"1873","desc":"밧줄로 배를 끌며 강변을 걷는 인부들의 고통스러운 행렬을 그린 작품이다. 열한 명 각각의 개성을 살린 사실적 묘사로 제정 러시아 민중의 삶을 고발하며, 러시아 사실주의의 기념비가 되었다."},
  {"artistEn":"Ilya Repin","artistKo":"일리야 레핀","artistKeys":["repin","ilya repin"],"titleEn":"Ivan the Terrible and His Son Ivan","titleKo":"이반 뇌제와 그의 아들 이반","titleKeys":["ivan","terrible","son"],"year":"1885","desc":"분노로 아들을 내리친 직후 공포에 질려 그를 끌어안은 이반 뇌제를 그린 작품이다. 광기와 회한이 교차하는 황제의 눈빛이 압도적이며, 러시아 역사화 가운데 가장 충격적인 그림으로 꼽힌다."},
  {"artistEn":"Ilya Repin","artistKo":"일리야 레핀","artistKeys":["repin","ilya repin"],"titleEn":"Reply of the Zaporozhian Cossacks","titleKo":"터키 술탄에게 답장을 쓰는 자포로지예 카자크들","titleKeys":["zaporozhian","cossacks","reply"],"year":"1891","desc":"오스만 술탄의 항복 요구에 조롱 가득한 답장을 쓰며 폭소하는 카자크들을 그린 작품이다. 십여 년의 제작 기간을 들여 완성했으며, 각 인물의 웃음 표정 묘사가 생동감의 절정을 이룬다."},
  {"artistEn":"Ivan Aivazovsky","artistKo":"이반 아이바좁스키","artistKeys":["aivazovsky","ivan aivazovsky","aivazovskiy","ajvazovskij"],"titleEn":"Among the Waves","titleKo":"파도 사이에서","titleKeys":["among","waves"],"year":"1898","desc":"배도 사람도 없이 오직 폭풍우 치는 바다만을 그린 아이바좁스키 만년의 대작이다. 여든의 나이에 완성한 순수한 바다 그림으로, 평생 바다를 그려온 화가의 기량이 집약되어 있다."},
  {"artistEn":"Ivan Aivazovsky","artistKo":"이반 아이바좁스키","artistKeys":["aivazovsky","ivan aivazovsky","aivazovskiy","ajvazovskij"],"titleEn":"The Black Sea","titleKo":"흑해","titleKeys":["black","sea"],"year":"1881","desc":"수평선을 경계로 어두운 하늘과 일렁이는 바다를 절제된 구성으로 그린 작품이다. 극적인 사건 없이 바다 자체의 힘과 호흡을 담아냈으며, 화가의 원숙기를 대표하는 그림으로 평가된다."},
  {"artistEn":"Ivan Aivazovsky","artistKo":"이반 아이바좁스키","artistKeys":["aivazovsky","ivan aivazovsky","aivazovskiy","ajvazovskij"],"titleEn":"The Ninth Wave","titleKo":"아홉 번째 파도","titleKeys":["ninth","wave"],"year":"1850","desc":"폭풍이 지나간 새벽 바다에서 돛대 잔해에 매달린 조난자들이 거대한 파도를 마주하는 장면이다. 태양빛이 투과하는 파도의 표현이 압권으로, 러시아 해양화의 최고 걸작으로 꼽힌다."},
  {"artistEn":"J.M.W. Turner","artistKo":"윌리엄 터너","artistKeys":["turner","jmw turner","william turner","joseph mallord william turner"],"titleEn":"Dido Building Carthage","titleKo":"카르타고를 건설하는 디도","titleKeys":["dido","carthage"],"year":"1815","desc":"카르타고의 여왕 디도가 도시를 건설하는 장면을 그린 역사 풍경화다. 클로드 로랭의 항구 풍경에 대한 오마주로, 터너 스스로 자신의 대표작으로 여겨 국가에 기증할 만큼 아꼈던 작품이다."},
  {"artistEn":"J.M.W. Turner","artistKo":"윌리엄 터너","artistKeys":["turner","jmw turner","william turner","joseph mallord william turner"],"titleEn":"Rain, Steam and Speed","titleKo":"비, 증기, 속도","titleKeys":["rain","steam","speed"],"year":"1844","desc":"폭우 속을 질주하는 증기 기관차를 빛과 대기의 소용돌이로 표현한 작품이다. 산업혁명의 속도감을 회화로 옮긴 선구적 시도로, 형태를 해체하는 붓질은 인상주의를 예고한 것으로 평가된다."},
  {"artistEn":"J.M.W. Turner","artistKo":"윌리엄 터너","artistKeys":["turner","jmw turner","william turner","joseph mallord william turner"],"titleEn":"Snow Storm: Steam-Boat off a Harbour's Mouth","titleKo":"눈보라 - 항구 어귀의 증기선","titleKeys":["snow","storm","steam","boat"],"year":"1842","desc":"눈보라 치는 바다 한가운데서 사투를 벌이는 증기선을 그린 작품이다. 화면 전체가 소용돌이치는 빛과 물보라로 뒤덮여 형태가 거의 사라졌으며, 터너 말년의 추상에 가까운 화풍을 보여준다."},
  {"artistEn":"J.M.W. Turner","artistKo":"윌리엄 터너","artistKeys":["turner","jmw turner","william turner","joseph mallord william turner"],"titleEn":"The Burning of the Houses of Lords and Commons","titleKo":"국회의사당의 화재","titleKeys":["burning","houses","parliament"],"year":"1835","desc":"1834년 런던 국회의사당 대화재를 직접 목격하고 그린 작품이다. 밤하늘로 치솟는 화염과 템스 강에 비친 불빛을 격정적인 색채로 담아, 재난마저 숭고한 빛의 스펙터클로 승화시켰다."},
  {"artistEn":"J.M.W. Turner","artistKo":"윌리엄 터너","artistKeys":["turner","jmw turner","william turner","joseph mallord william turner"],"titleEn":"The Fighting Temeraire","titleKo":"전함 테메레르","titleKeys":["fighting","temeraire"],"year":"1839","desc":"트라팔가르 해전의 영웅이었던 전함 테메레르가 증기 예인선에 끌려 해체장으로 가는 모습을 그린 작품이다. 석양을 배경으로 범선 시대의 종언을 애도하며, 영국인이 가장 사랑하는 그림으로 꼽힌다."},
  {"artistEn":"J.M.W. Turner","artistKo":"윌리엄 터너","artistKeys":["turner","jmw turner","william turner","joseph mallord william turner"],"titleEn":"The Slave Ship","titleKo":"노예선","titleKeys":["slave","ship"],"year":"1840","desc":"폭풍이 다가오자 병든 노예들을 바다에 던진 노예선의 실화를 소재로 한 작품이다. 핏빛 노을과 요동치는 바다가 참극의 공포를 증폭시키며, 노예제의 비인간성을 고발하는 그림으로 읽힌다."},
  {"artistEn":"Jacques-Louis David","artistKo":"자크루이 다비드","artistKeys":["david","jacques louis david"],"titleEn":"Napoleon Crossing the Alps","titleKo":"알프스를 넘는 나폴레옹","titleKeys":["napoleon","crossing","alps"],"year":"1801","desc":"백마를 타고 알프스를 넘는 나폴레옹을 극적으로 이상화한 초상이다. 실제로는 노새를 탔다고 전해지지만, 바람에 휘날리는 망토와 앞발을 든 말로 영웅의 이미지를 완성한 선전 회화의 걸작이다."},
  {"artistEn":"Jacques-Louis David","artistKo":"자크루이 다비드","artistKeys":["david","jacques louis david"],"titleEn":"Oath of the Horatii","titleKo":"호라티우스 형제의 맹세","titleKeys":["oath","horatii"],"year":"1784","desc":"로마를 위해 싸우겠다고 아버지 앞에서 맹세하는 세 형제를 그린 작품이다. 엄격한 구도와 절제된 색채로 애국적 희생을 강조하며, 신고전주의 회화의 선언과도 같은 그림으로 평가된다."},
  {"artistEn":"Jacques-Louis David","artistKo":"자크루이 다비드","artistKeys":["david","jacques louis david"],"titleEn":"Portrait of Madame Récamier","titleKo":"레카미에 부인의 초상","titleKeys":["madame","recamier"],"year":"1800","desc":"파리 사교계의 미인 레카미에 부인이 긴 의자에 비스듬히 기대앉은 모습을 그린 초상이다. 흰 드레스와 간결한 배경이 고대풍의 우아함을 자아내며, 미완성임에도 신고전주의 초상의 걸작으로 꼽힌다."},
  {"artistEn":"Jacques-Louis David","artistKo":"자크루이 다비드","artistKeys":["david","jacques louis david"],"titleEn":"The Coronation of Napoleon","titleKo":"나폴레옹 1세의 대관식","titleKeys":["coronation","napoleon"],"year":"1807","desc":"노트르담 대성당에서 나폴레옹이 황후 조제핀에게 관을 씌우는 장면을 그린 초대형 기록화다. 수많은 인물의 초상을 정밀하게 담았으며, 제정 프랑스의 위엄을 과시하는 궁정 회화의 정점이다."},
  {"artistEn":"Jacques-Louis David","artistKo":"자크루이 다비드","artistKeys":["david","jacques louis david"],"titleEn":"The Death of Marat","titleKo":"마라의 죽음","titleKeys":["death","marat"],"year":"1793","desc":"욕조에서 암살당한 혁명가 장폴 마라를 순교자처럼 그린 작품이다. 어두운 배경과 축 늘어진 팔이 비장함을 자아내며, 프랑스 혁명기의 정치적 회화 가운데 가장 강렬한 이미지로 꼽힌다."},
  {"artistEn":"Jacques-Louis David","artistKo":"자크루이 다비드","artistKeys":["david","jacques louis david"],"titleEn":"The Death of Socrates","titleKo":"소크라테스의 죽음","titleKeys":["death","socrates"],"year":"1787","desc":"독배를 앞에 두고도 제자들에게 의연히 철학을 설파하는 소크라테스를 그린 작품이다. 절제된 신고전주의 양식으로 신념을 위한 죽음을 영웅적으로 형상화했으며, 메트로폴리탄 미술관에 소장되어 있다."},
  {"artistEn":"Jacques-Louis David","artistKo":"자크루이 다비드","artistKeys":["david","jacques louis david"],"titleEn":"The Intervention of the Sabine Women","titleKo":"사비니 여인들의 중재","titleKeys":["intervention","sabine","women"],"year":"1799","desc":"로마군과 사비니군의 전투 사이에 여인들이 뛰어들어 싸움을 말리는 장면을 그린 작품이다. 혁명 후의 화해를 호소하는 정치적 메시지를 담았으며, 다비드의 고전적 구도가 완숙하게 드러난다."},
  {"artistEn":"James McNeill Whistler","artistKo":"제임스 맥닐 휘슬러","artistKeys":["whistler","james mcneill whistler","james whistler","mcneill whistler"],"titleEn":"Nocturne in Black and Gold - The Falling Rocket","titleKo":"검정과 금빛의 야상곡: 떨어지는 불꽃","titleKeys":["nocturne","falling","rocket","gold"],"year":"1875","desc":"밤하늘에 흩어지는 불꽃놀이를 거의 추상에 가깝게 그린 야상곡 연작의 하나다. 비평가 러스킨의 혹평에 휘슬러가 명예훼손 소송을 제기하며 예술의 자율성 논쟁을 촉발한 작품으로 유명하다."},
  {"artistEn":"James McNeill Whistler","artistKo":"제임스 맥닐 휘슬러","artistKeys":["whistler","james mcneill whistler","james whistler","mcneill whistler"],"titleEn":"Symphony in White, No. 1: The White Girl","titleKo":"흰색의 교향곡 1번: 하얀 소녀","titleKeys":["symphony","white","girl"],"year":"1862","desc":"흰 드레스를 입고 흰 커튼 앞에 선 붉은 머리 여인을 그린 작품이다. 이야기보다 색조의 조화를 앞세운 '예술을 위한 예술'의 선언으로 평가되며, 1863년 낙선전에서 화제를 모았다."},
  {"artistEn":"James McNeill Whistler","artistKo":"제임스 맥닐 휘슬러","artistKeys":["whistler","james mcneill whistler","james whistler","mcneill whistler"],"titleEn":"Whistler's Mother (Arrangement in Grey and Black No. 1)","titleKo":"화가의 어머니","titleKeys":["mother","arrangement","grey","black"],"year":"1871","desc":"회색과 검정의 절제된 색조 속에 옆모습으로 앉은 화가의 어머니를 그렸다. 원제는 '회색과 검정의 배열 1번'으로, 모성의 상징이 되어 미국 회화에서 가장 유명한 이미지 중 하나로 남았다."},
  {"artistEn":"Jan van Eyck","artistKo":"얀 반 에이크","artistKeys":["van eyck","eyck","vaneyck"],"titleEn":"Portrait of a Man in a Red Turban","titleKo":"붉은 터번을 쓴 남자의 초상","titleKeys":["man","red","turban"],"year":"1433","desc":"붉은 두건을 두른 남자를 가까이에서 포착한 초상으로, 화가 자신의 자화상으로 널리 추정된다. 얼굴의 주름과 수염, 천의 접힌 결까지 살려낸 세밀한 묘사가 돋보이며, 런던 내셔널 갤러리에 소장되어 있다."},
  {"artistEn":"Jan van Eyck","artistKo":"얀 반 에이크","artistKeys":["van eyck","eyck","vaneyck"],"titleEn":"The Arnolfini Portrait","titleKo":"아르놀피니 부부의 초상","titleKeys":["arnolfini","portrait"],"year":"1434","desc":"북유럽 르네상스 초상화의 걸작으로, 이탈리아 상인 아르놀피니 부부가 실내에 서 있는 모습을 담았다. 볼록 거울에 비친 인물들과 샹들리에, 강아지까지 이어지는 정교한 세부 묘사와 유화 기법의 섬세한 질감 표현으로 유명하다."},
  {"artistEn":"Jan van Eyck","artistKo":"얀 반 에이크","artistKeys":["van eyck","eyck","vaneyck"],"titleEn":"The Ghent Altarpiece","titleKo":"헨트 제단화","titleKeys":["ghent","altarpiece"],"year":"1432","desc":"여러 패널로 이루어진 대형 제단화로, 중앙의 어린 양에 대한 경배 장면을 비롯해 성서의 인물들이 정교하게 그려져 있다. 유화 기법을 완성 단계로 끌어올린 북유럽 르네상스의 기념비적 작품으로, 벨기에 헨트의 성 바보 대성당에 있다."},
  {"artistEn":"Jang Seung-eop","artistKo":"장승업","artistKeys":["jang seung-eop","jang seungeop","jangseungeop","owon"],"titleEn":"Hochwido (Brave Eagles)","titleKo":"호취도","titleKeys":["hochwido","eagles","hawks"],"year":"19세기 말","desc":"고목 가지에 앉은 매 두 마리를 호방한 필치로 그린 영모화다. 조선 말기 화단의 천재로 불린 장승업의 대표작으로, 거침없는 붓놀림과 대담한 구도에서 기량이 드러난다."},
  {"artistEn":"Jean-Auguste-Dominique Ingres","artistKo":"장오귀스트도미니크 앵그르","artistKeys":["ingres","jean auguste dominique ingres"],"titleEn":"La Grande Odalisque","titleKo":"그랑드 오달리스크","titleKeys":["grande","odalisque"],"year":"1814","desc":"터키 궁정의 여인을 등을 보인 채 비스듬히 누운 자세로 그린 작품이다. 해부학적으로 길게 늘인 허리가 논란을 낳았지만, 매끄러운 윤곽선과 이국적 관능미로 앵그르의 대표작이 되었다."},
  {"artistEn":"Jean-Auguste-Dominique Ingres","artistKo":"장오귀스트도미니크 앵그르","artistKeys":["ingres","jean auguste dominique ingres"],"titleEn":"Napoleon I on His Imperial Throne","titleKo":"옥좌의 나폴레옹 1세","titleKeys":["napoleon","imperial","throne"],"year":"1806","desc":"월계관을 쓴 나폴레옹이 정면을 향해 옥좌에 앉아 있는 대관식 초상이다. 신처럼 좌우대칭으로 배치된 구도와 화려한 의장 묘사가 황제의 절대 권력을 시각화한다."},
  {"artistEn":"Jean-Auguste-Dominique Ingres","artistKo":"장오귀스트도미니크 앵그르","artistKeys":["ingres","jean auguste dominique ingres"],"titleEn":"Princesse de Broglie","titleKo":"브로이 공주의 초상","titleKeys":["princesse","princess","broglie"],"year":"1853","desc":"푸른 새틴 드레스를 입은 브로이 공주를 그린 앵그르 만년의 초상화다. 비단의 광택과 레이스, 보석의 질감을 극도로 정밀하게 재현해 초상화가로서의 기량을 유감없이 보여준다."},
  {"artistEn":"Jean-Auguste-Dominique Ingres","artistKo":"장오귀스트도미니크 앵그르","artistKeys":["ingres","jean auguste dominique ingres"],"titleEn":"The Apotheosis of Homer","titleKo":"호메로스 예찬","titleKeys":["apotheosis","homer"],"year":"1827","desc":"호메로스를 중심으로 고대와 근대의 위대한 예술가들이 도열한 장면을 그린 작품이다. 라파엘로의 아테네 학당을 잇는 구성으로, 고전 전통에 대한 앵그르의 신념을 집약한 선언적 그림이다."},
  {"artistEn":"Jean-Auguste-Dominique Ingres","artistKo":"장오귀스트도미니크 앵그르","artistKeys":["ingres","jean auguste dominique ingres"],"titleEn":"The Turkish Bath","titleKo":"터키탕","titleKeys":["turkish","bath"],"year":"1862","desc":"원형 화면 안에 목욕하는 여인들을 빽빽하게 배치한 앵그르 말년의 작품이다. 평생 다뤄온 오리엔탈리즘과 누드 주제를 집대성했으며, 여든이 넘은 나이에 완성한 것으로 유명하다."},
  {"artistEn":"Jean-Auguste-Dominique Ingres","artistKo":"장오귀스트도미니크 앵그르","artistKeys":["ingres","jean auguste dominique ingres"],"titleEn":"The Valpinçon Bather","titleKo":"발팽송의 목욕하는 여인","titleKeys":["valpincon","bather"],"year":"1808","desc":"터번을 쓴 여인이 등을 돌리고 침대에 앉아 있는 누드화다. 매끄러운 등의 곡선과 정적인 실내 분위기가 고요한 아름다움을 자아내며, 앵그르 누드 연작의 출발점이 된 작품이다."},
  {"artistEn":"Jean-Baptiste-Siméon Chardin","artistKo":"장바티스트시메옹 샤르댕","artistKeys":["chardin","jean baptiste simeon chardin"],"titleEn":"Soap Bubbles","titleKo":"비눗방울","titleKeys":["soap","bubbles"],"year":"c. 1734","desc":"창가에서 소년이 비눗방울을 부는 모습을 조용히 담아낸 풍속화다. 금방 터질 비눗방울은 인생의 덧없음을 암시하며, 일상의 순간을 차분한 색조로 그려낸 샤르댕의 대표작 중 하나다."},
  {"artistEn":"Jean-Baptiste-Siméon Chardin","artistKo":"장바티스트시메옹 샤르댕","artistKeys":["chardin","jean baptiste simeon chardin"],"titleEn":"The Ray","titleKo":"가오리","titleKeys":["ray","raie"],"year":"1728","desc":"부엌 탁자 위에 걸린 가오리와 고양이, 식기들을 그린 정물화다. 내장이 드러난 가오리의 생생한 묘사가 강렬한 인상을 주며, 샤르댕이 왕립 아카데미에 입회하는 계기가 된 작품이다."},
  {"artistEn":"Jean-François Millet","artistKo":"장프랑수아 밀레","artistKeys":["millet","jean francois millet"],"titleEn":"Man with a Hoe","titleKo":"괭이를 든 남자","titleKeys":["man","hoe"],"year":"c. 1862","desc":"괭이에 몸을 기댄 채 지친 얼굴로 서 있는 농부를 그린 작품이다. 미화 없이 드러낸 고된 노동의 실상이 발표 당시 격렬한 논쟁을 불렀으며, 농민 화가 밀레의 문제작으로 남아 있다."},
  {"artistEn":"Jean-François Millet","artistKo":"장프랑수아 밀레","artistKeys":["millet","jean francois millet"],"titleEn":"The Angelus","titleKo":"만종","titleKeys":["angelus"],"year":"c. 1858","desc":"저녁 종소리에 맞춰 들판에서 기도하는 농부 부부를 그린 작품이다. 노동과 신앙이 어우러진 경건한 정경으로 세계적으로 사랑받았으며, 한국에서도 가장 널리 알려진 서양화 중 하나다."},
  {"artistEn":"Jean-François Millet","artistKo":"장프랑수아 밀레","artistKeys":["millet","jean francois millet"],"titleEn":"The Gleaners","titleKo":"이삭 줍는 여인들","titleKeys":["gleaners","glaneuses"],"year":"1857","desc":"추수가 끝난 들판에서 허리를 굽혀 이삭을 줍는 세 농촌 여인을 그린 작품이다. 가장 가난한 노동을 기념비적 존엄으로 끌어올린 사실주의 회화의 상징으로, 오르세 미술관에 소장되어 있다."},
  {"artistEn":"Jean-François Millet","artistKo":"장프랑수아 밀레","artistKeys":["millet","jean francois millet"],"titleEn":"The Sower","titleKo":"씨 뿌리는 사람","titleKeys":["sower","semeur"],"year":"1850","desc":"황혼의 들판에서 성큼성큼 걸으며 씨를 뿌리는 농부를 그린 작품이다. 역동적인 실루엣이 노동의 영웅적 이미지를 만들어내며, 고흐가 평생 모사하며 존경을 표한 그림으로도 유명하다."},
  {"artistEn":"Jean-Honoré Fragonard","artistKo":"장오노레 프라고나르","artistKeys":["fragonard","jean honore fragonard"],"titleEn":"The Stolen Kiss","titleKo":"훔친 키스","titleKeys":["stolen","kiss"],"year":"c. 1788","desc":"옆방에 사람들이 있는 사이 청년이 처녀의 뺨에 몰래 입 맞추는 순간을 포착한 작품이다. 비단 드레스의 광택 표현이 정교하며, 로코코의 연애 유희 주제를 세련되게 마무리한 후기 대표작이다."},
  {"artistEn":"Jean-Honoré Fragonard","artistKo":"장오노레 프라고나르","artistKeys":["fragonard","jean honore fragonard"],"titleEn":"The Swing","titleKo":"그네","titleKeys":["swing","escarpolette"],"year":"1767","desc":"숲속에서 그네를 타는 여인과 그 아래에서 그녀를 올려다보는 청년을 그린 작품이다. 분홍 드레스와 날아가는 신발이 경쾌한 분위기를 자아내며, 로코코 회화의 유희적 감성을 대표하는 그림이다."},
  {"artistEn":"Jean-Honoré Fragonard","artistKo":"장오노레 프라고나르","artistKeys":["fragonard","jean honore fragonard"],"titleEn":"Young Girl Reading","titleKo":"책 읽는 소녀","titleKeys":["girl","reading","reader"],"year":"c. 1770","desc":"노란 드레스를 입은 소녀가 옆모습으로 앉아 책에 몰두한 모습을 그린 작품이다. 빠르고 자유로운 붓질과 따뜻한 색조가 조화를 이루며, 프라고나르의 초상 습작 가운데 가장 사랑받는 그림이다."},
  {"artistEn":"Jeong Seon","artistKo":"정선","artistKeys":["jeong seon","jeongseon","jeong-seon","gyeomjae"],"titleEn":"Bakyeon Pokpo (Bakyeon Falls)","titleKo":"박연폭포","titleKeys":["bakyeon","pokpo","waterfall","falls"],"year":"18세기","desc":"개성 박연폭포의 웅장한 물줄기를 실제보다 과장된 수직 구도로 그렸다. 쏟아지는 물소리가 들리는 듯한 대담한 흑백 대비로 진경산수화의 정신을 잘 보여주는 작품이다."},
  {"artistEn":"Jeong Seon","artistKo":"정선","artistKeys":["jeong seon","jeongseon","jeong-seon","gyeomjae"],"titleEn":"Geumgang Jeondo (General View of Mount Geumgang)","titleKo":"금강전도","titleKeys":["geumgang","jeondo","geumgangjeondo","diamond"],"year":"1734","desc":"금강산 일만 이천 봉을 하늘에서 내려다보듯 원형 구도 안에 담아낸 진경산수의 걸작이다. 뾰족한 바위 봉우리와 부드러운 흙산을 대비시킨 필법이 돋보이는 국보다."},
  {"artistEn":"Jeong Seon","artistKo":"정선","artistKeys":["jeong seon","jeongseon","jeong-seon","gyeomjae"],"titleEn":"Inwang Jesaekdo (Clearing After Rain on Mount Inwang)","titleKo":"인왕제색도","titleKeys":["inwang","jesaekdo","inwangjesaekdo"],"year":"1751","desc":"비가 갠 뒤 안개가 피어오르는 인왕산의 모습을 힘찬 필묵으로 그렸다. 우리 산천을 직접 보고 그리는 진경산수화의 정점으로 평가되며 국보로 지정되어 있다."},
  {"artistEn":"Joaquin Sorolla","artistKo":"호아킨 소로야","artistKeys":["sorolla","joaquin sorolla","joaquinsorolla"],"titleEn":"Boys on the Beach","titleKo":"해변의 아이들","titleKeys":["boys","beach","children"],"year":"1909","desc":"물가 모래 위에 엎드려 노는 세 소년의 젖은 피부에 반사된 햇빛을 그렸다. 자연광 아래 인체 표현이 절정에 달한 소로야 해변 연작의 백미로, 프라도 미술관이 소장하고 있다."},
  {"artistEn":"Joaquin Sorolla","artistKo":"호아킨 소로야","artistKeys":["sorolla","joaquin sorolla","joaquinsorolla"],"titleEn":"Sewing the Sail","titleKo":"돛 꿰매기","titleKeys":["sewing","sail"],"year":"1896","desc":"포도 넝쿨 그늘 아래에서 가족들이 거대한 흰 돛을 함께 꿰매는 장면을 그렸다. 쏟아지는 지중해의 빛과 흰 천의 눈부신 표현으로 소로야에게 국제적 명성을 안겨 준 작품이다."},
  {"artistEn":"Joaquin Sorolla","artistKo":"호아킨 소로야","artistKeys":["sorolla","joaquin sorolla","joaquinsorolla"],"titleEn":"Walk on the Beach","titleKo":"해변의 산책","titleKeys":["walk","beach","paseo"],"year":"1909","desc":"발렌시아 해변을 거니는 아내와 딸을 흰 드레스와 베일에 부서지는 눈부신 빛으로 담았다. 지중해의 햇살을 평생 그린 '빛의 화가' 소로야의 가장 사랑받는 대표작이다."},
  {"artistEn":"Johannes Vermeer","artistKo":"요하네스 페르메이르","artistKeys":["vermeer","johannes"],"titleEn":"Girl with a Pearl Earring","titleKo":"진주 귀걸이를 한 소녀","titleKeys":["girl","pearl","earring"],"year":"c. 1665","desc":"네덜란드 황금기 회화의 대표작으로, 터번을 두른 소녀가 어깨 너머로 관람자를 돌아보는 순간을 포착했다. 진주 귀걸이에 맺힌 빛과 부드러운 명암 처리가 신비로운 분위기를 만든다."},
  {"artistEn":"Johannes Vermeer","artistKo":"요하네스 페르메이르","artistKeys":["vermeer","johannes"],"titleEn":"The Art of Painting","titleKo":"회화의 기술","titleKeys":["art","painting","allegory"],"year":"c. 1666–1668","desc":"화가가 월계관을 쓴 모델을 그리는 아틀리에 장면을 통해 회화 예술 자체를 알레고리로 표현한 작품이다. 걷힌 커튼 너머로 펼쳐지는 공간감과 벽의 지도, 샹들리에의 정밀한 묘사가 돋보인다."},
  {"artistEn":"Johannes Vermeer","artistKo":"요하네스 페르메이르","artistKeys":["vermeer","johannes"],"titleEn":"The Astronomer","titleKo":"천문학자","titleKeys":["astronomer"],"year":"c. 1668","desc":"천구의를 향해 손을 뻗은 학자의 모습을 그린 작품으로, 과학 혁명기 네덜란드의 지적 열망을 반영한다. 창에서 들어오는 빛이 탐구에 몰두한 학자의 순간을 조용히 비추며, 루브르 박물관에 있다."},
  {"artistEn":"Johannes Vermeer","artistKo":"요하네스 페르메이르","artistKeys":["vermeer","johannes"],"titleEn":"The Geographer","titleKo":"지리학자","titleKeys":["geographer"],"year":"c. 1669","desc":"지도와 컴퍼스를 앞에 두고 창밖을 바라보며 생각에 잠긴 지리학자를 그렸다. 천문학자와 짝을 이루는 작품으로 여겨지며, 항해와 지도 제작이 번성했던 네덜란드 황금기의 시대상을 보여준다."},
  {"artistEn":"Johannes Vermeer","artistKo":"요하네스 페르메이르","artistKeys":["vermeer","johannes"],"titleEn":"The Lacemaker","titleKo":"레이스를 뜨는 여인","titleKeys":["lacemaker","lace"],"year":"c. 1669–1670","desc":"레이스 뜨기에 몰두한 젊은 여인을 가까이에서 포착한 소품이다. 실과 바늘에 집중된 시선과 초점의 섬세한 처리로 일상의 집중이 지닌 아름다움을 담아냈으며, 루브르 박물관에 소장되어 있다."},
  {"artistEn":"Johannes Vermeer","artistKo":"요하네스 페르메이르","artistKeys":["vermeer","johannes"],"titleEn":"The Milkmaid","titleKo":"우유를 따르는 여인","titleKeys":["milkmaid","milk"],"year":"c. 1658–1660","desc":"부엌에서 우유를 따르는 하녀의 모습을 그린 작품으로, 일상의 노동을 기념비적인 존엄으로 끌어올렸다. 창으로 들어오는 빛과 빵의 오톨도톨한 질감 묘사가 페르메이르 특유의 정밀함을 보여준다."},
  {"artistEn":"Johannes Vermeer","artistKo":"요하네스 페르메이르","artistKeys":["vermeer","johannes"],"titleEn":"View of Delft","titleKo":"델프트 풍경","titleKeys":["view","delft"],"year":"c. 1660–1661","desc":"화가의 고향 델프트를 강 건너에서 바라본 도시 풍경화다. 구름 사이로 비치는 빛과 물에 반사된 건물들의 묘사가 뛰어나 서양 풍경화의 걸작으로 꼽히며, 헤이그 마우리츠하위스 미술관에 소장되어 있다."},
  {"artistEn":"Johannes Vermeer","artistKo":"요하네스 페르메이르","artistKeys":["vermeer","johannes"],"titleEn":"Woman in Blue Reading a Letter","titleKo":"편지를 읽는 푸른 옷의 여인","titleKeys":["woman","blue","reading","letter"],"year":"c. 1663","desc":"창가에서 편지를 읽는 파란 옷의 여인을 그린 실내화다. 고요한 아침 빛과 편지에 몰입한 여인의 표정이 사연을 궁금하게 만드는, 페르메이르다운 정적의 순간을 담고 있다."},
  {"artistEn":"John Constable","artistKo":"존 컨스터블","artistKeys":["constable","john constable"],"titleEn":"Flatford Mill","titleKo":"플랫퍼드 방앗간","titleKeys":["flatford","mill"],"year":"1817","desc":"아버지 소유의 방앗간 근처 운하에서 배를 끄는 소년들을 그린 풍경화다. 구름과 빛의 변화를 야외 관찰로 담아냈으며, 고향 스투어 강 유역을 향한 컨스터블의 애정이 배어 있는 작품이다."},
  {"artistEn":"John Constable","artistKo":"존 컨스터블","artistKeys":["constable","john constable"],"titleEn":"Salisbury Cathedral from the Meadows","titleKo":"초원에서 본 솔즈베리 대성당","titleKeys":["salisbury","cathedral","meadows"],"year":"1831","desc":"폭풍우 구름과 무지개 아래 솟은 솔즈베리 대성당을 그린 작품이다. 아내를 잃은 뒤의 격정적 심경이 하늘 표현에 투영된 것으로 해석되며, 컨스터블 후기의 대표작으로 꼽힌다."},
  {"artistEn":"John Constable","artistKo":"존 컨스터블","artistKeys":["constable","john constable"],"titleEn":"The Hay Wain","titleKo":"건초 마차","titleKeys":["hay","wain"],"year":"1821","desc":"서퍽 지방의 강을 건너는 건초 마차와 시골 풍경을 그린 작품이다. 고향의 일상을 이상화 없이 담아낸 영국 풍경화의 대표작으로, 파리 살롱에서 들라크루아 등에게 깊은 인상을 남겼다."},
  {"artistEn":"John Everett Millais","artistKo":"존 에버렛 밀레이","artistKeys":["millais","john everett millais"],"titleEn":"Christ in the House of His Parents","titleKo":"부모 집의 그리스도","titleKeys":["christ","house","parents"],"year":"1850","desc":"목수의 작업장에서 손을 다친 어린 예수와 가족을 그린 작품이다. 성가족을 평범한 노동자 가정으로 묘사해 발표 당시 신성모독 논란을 일으켰으며, 라파엘전파의 사실주의 정신을 보여준다."},
  {"artistEn":"John Everett Millais","artistKo":"존 에버렛 밀레이","artistKeys":["millais","john everett millais"],"titleEn":"Ophelia","titleKo":"오필리아","titleKeys":["ophelia"],"year":"1852","desc":"햄릿의 오필리아가 꽃을 든 채 시냇물에 떠내려가며 죽음을 맞는 장면을 그린 작품이다. 식물 하나하나까지 세밀하게 그린 라파엘전파 자연주의의 정수로, 테이트 브리튼의 대표 소장품이다."},
  {"artistEn":"John Singer Sargent","artistKo":"존 싱어 사전트","artistKeys":["sargent","john singer sargent","john sargent","singer sargent"],"titleEn":"Carnation, Lily, Lily, Rose","titleKo":"카네이션, 백합, 백합, 장미","titleKeys":["carnation","lily","rose"],"year":"1885-1886","desc":"해 질 녘 정원에서 두 소녀가 중국식 등롱에 불을 밝히는 장면을 그렸다. 황혼의 빛을 정확히 담기 위해 매일 저녁 몇 분씩만 그리며 두 해에 걸쳐 완성한 사전트의 대표작이다."},
  {"artistEn":"John Singer Sargent","artistKo":"존 싱어 사전트","artistKeys":["sargent","john singer sargent","john sargent","singer sargent"],"titleEn":"El Jaleo","titleKo":"엘 할레오","titleKeys":["el jaleo","jaleo","flamenco"],"year":"1882","desc":"스페인 무희가 기타 연주자들 앞에서 플라멩코를 추는 순간을 극적인 조명으로 포착했다. 스페인 여행에서 받은 인상을 담은 대형 걸작으로, 젊은 사전트의 이름을 알린 작품이다."},
  {"artistEn":"John Singer Sargent","artistKo":"존 싱어 사전트","artistKeys":["sargent","john singer sargent","john sargent","singer sargent"],"titleEn":"Lady Agnew of Lochnaw","titleKo":"레이디 애그뉴의 초상","titleKeys":["lady","agnew","lochnaw"],"year":"1892","desc":"안락의자에 비스듬히 기댄 레이디 애그뉴의 여유롭고 도발적인 시선이 인상적인 초상이다. 이 작품의 성공으로 사전트는 런던 사교계에서 가장 인기 있는 초상화가로 떠올랐다."},
  {"artistEn":"John Singer Sargent","artistKo":"존 싱어 사전트","artistKeys":["sargent","john singer sargent","john sargent","singer sargent"],"titleEn":"Madame X","titleKo":"마담 X","titleKeys":["madame","x","gautreau"],"year":"1884","desc":"파리 사교계의 미인 고트로 부인을 검은 드레스 차림으로 그린 초상이다. 흘러내린 어깨끈 묘사가 살롱에서 스캔들을 일으켜 사전트가 파리를 떠나 런던에 정착하는 계기가 되었다."},
  {"artistEn":"John Singer Sargent","artistKo":"존 싱어 사전트","artistKeys":["sargent","john singer sargent","john sargent","singer sargent"],"titleEn":"The Daughters of Edward Darley Boit","titleKo":"에드워드 달리 보이트의 딸들","titleKeys":["daughters","boit"],"year":"1882","desc":"어두운 실내에 흩어져 선 네 자매를 벨라스케스풍 구도로 담은 초상이다. 인물들 사이의 거리감과 깊은 그늘이 유년의 고독을 암시한다는 해석으로도 널리 알려진 작품이다."},
  {"artistEn":"John William Waterhouse","artistKo":"존 윌리엄 워터하우스","artistKeys":["waterhouse","john william waterhouse"],"titleEn":"Echo and Narcissus","titleKo":"에코와 나르키소스","titleKeys":["echo","narcissus"],"year":"1903","desc":"물에 비친 자신의 모습에 빠진 나르키소스와 그를 바라보는 님프 에코를 그린 작품이다. 오비디우스의 신화를 서정적 풍경 속에 재현했으며, 짝사랑의 비극이 화면의 거리감으로 표현되어 있다."},
  {"artistEn":"John William Waterhouse","artistKo":"존 윌리엄 워터하우스","artistKeys":["waterhouse","john william waterhouse"],"titleEn":"Hylas and the Nymphs","titleKo":"힐라스와 님프들","titleKeys":["hylas","nymphs"],"year":"1896","desc":"물을 길으러 온 미소년 힐라스를 연못의 님프들이 물속으로 유혹하는 장면을 그린 작품이다. 수련이 떠 있는 어두운 수면과 님프들의 창백한 피부가 몽환적이면서도 불길한 분위기를 자아낸다."},
  {"artistEn":"John William Waterhouse","artistKo":"존 윌리엄 워터하우스","artistKeys":["waterhouse","john william waterhouse"],"titleEn":"The Lady of Shalott","titleKo":"샬럿의 여인","titleKeys":["lady","shalott"],"year":"1888","desc":"테니슨의 시를 바탕으로, 저주를 안고 배에 올라 카멜롯으로 떠나는 여인을 그린 작품이다. 촛불과 태피스트리 등 상징적 소품이 비극을 암시하며, 빅토리아 시대 회화 중 가장 사랑받는 그림의 하나다."},
  {"artistEn":"Joshua Reynolds","artistKo":"조슈아 레이놀즈","artistKeys":["reynolds","joshua reynolds"],"titleEn":"Sarah Siddons as the Tragic Muse","titleKo":"비극의 뮤즈로 분한 사라 시돈스","titleKeys":["siddons","tragic","muse"],"year":"1784","desc":"당대 최고의 비극 배우 사라 시돈스를 비극의 뮤즈 멜포메네로 형상화한 초상이다. 미켈란젤로풍의 웅장한 구도로 배우의 위엄을 신화적 차원으로 끌어올린 그랜드 매너 초상화의 대표작이다."},
  {"artistEn":"Joshua Reynolds","artistKo":"조슈아 레이놀즈","artistKeys":["reynolds","joshua reynolds"],"titleEn":"The Age of Innocence","titleKo":"순수의 시대","titleKeys":["age","innocence"],"year":"c. 1788","desc":"흰 드레스를 입은 어린 소녀가 두 손을 모으고 앉아 있는 모습을 그린 작품이다. 아이의 순수함을 이상화한 18세기 아동 초상의 전형으로, 이후 수많은 복제와 인쇄물로 널리 사랑받았다."},
  {"artistEn":"Katsushika Hokusai","artistKo":"가쓰시카 호쿠사이","artistKeys":["hokusai","katsushika hokusai","katsushikahokusai"],"titleEn":"Fine Wind, Clear Morning (Red Fuji)","titleKo":"개풍쾌청(붉은 후지)","titleKeys":["red","fuji","fine","wind","clear"],"year":"c. 1831","desc":"이른 가을 아침 햇살에 산 표면이 붉게 물든 후지산을 간결한 구도로 담았다. '붉은 후지'라는 애칭으로 불리며, 가나가와의 파도와 함께 후가쿠 36경의 쌍벽을 이루는 걸작이다."},
  {"artistEn":"Katsushika Hokusai","artistKo":"가쓰시카 호쿠사이","artistKeys":["hokusai","katsushika hokusai","katsushikahokusai"],"titleEn":"Kirifuri Waterfall at Kurokami Mountain","titleKo":"기리후리 폭포","titleKeys":["kirifuri","waterfall"],"year":"c. 1832","desc":"닛코 구로카미산의 기리후리 폭포를 생명체처럼 갈라져 흘러내리는 물줄기로 표현했다. 일본 각지의 폭포를 기행하듯 담은 '여러 지방 폭포 순례' 연작 중 가장 유명한 장면이다."},
  {"artistEn":"Katsushika Hokusai","artistKo":"가쓰시카 호쿠사이","artistKeys":["hokusai","katsushika hokusai","katsushikahokusai"],"titleEn":"The Great Wave off Kanagawa","titleKo":"가나가와 해변의 높은 파도 아래","titleKeys":["great","wave","kanagawa"],"year":"c. 1831","desc":"후가쿠 36경 연작 중 가장 유명한 판화로, 거대한 파도가 배들을 삼킬 듯 굽이치고 그 사이로 멀리 후지산이 보인다. 서양 인상주의와 자포니슴에 큰 영향을 미친 우키요에의 상징이다."},
  {"artistEn":"Katsushika Hokusai","artistKo":"가쓰시카 호쿠사이","artistKeys":["hokusai","katsushika hokusai","katsushikahokusai"],"titleEn":"Thunderstorm Beneath the Summit (Black Fuji)","titleKo":"산하백우(검은 후지)","titleKeys":["thunderstorm","summit","black","fuji"],"year":"c. 1831","desc":"맑은 하늘 아래 솟은 후지산 정상과 달리 산기슭에는 번개가 내리치는 극적인 대비를 담았다. 어두운 산체 때문에 '검은 후지'로도 불리며, 붉은 후지와 짝을 이루는 후가쿠 36경의 걸작이다."},
  {"artistEn":"Kim Hong-do","artistKo":"김홍도","artistKeys":["kim hong-do","kim hongdo","kimhongdo","hongdo","danwon"],"titleEn":"Mudong (Dancing Boy)","titleKo":"무동","titleKeys":["mudong","dancing","boy"],"year":"18세기 후반","desc":"삼현육각 연주에 맞춰 덩실덩실 춤추는 소년의 흥겨운 동작을 포착했다. 연주에 몰입한 악사들의 표정과 소년의 나부끼는 옷자락에서 음악의 리듬이 느껴지는 단원 풍속화첩의 명장면이다."},
  {"artistEn":"Kim Hong-do","artistKo":"김홍도","artistKeys":["kim hong-do","kim hongdo","kimhongdo","hongdo","danwon"],"titleEn":"Ppallaeteo (Washing Place)","titleKo":"빨래터","titleKeys":["ppallaeteo","washing","laundry"],"year":"18세기 후반","desc":"냇가에서 빨래하는 아낙들과 바위 뒤에서 부채로 얼굴을 가린 채 훔쳐보는 선비를 함께 그렸다. 서민의 일상과 은근한 해학이 공존하는 단원 풍속화첩의 한 장면이다."},
  {"artistEn":"Kim Hong-do","artistKo":"김홍도","artistKeys":["kim hong-do","kim hongdo","kimhongdo","hongdo","danwon"],"titleEn":"Seodang (Village School)","titleKo":"서당","titleKeys":["seodang","school"],"year":"18세기 후반","desc":"훈장 앞에서 훌쩍이는 학동과 그 모습에 웃음을 참는 아이들을 그린 풍속화다. 조선 후기 서당의 일상을 따뜻한 해학으로 담아낸 단원 풍속화첩의 가장 유명한 장면 중 하나다."},
  {"artistEn":"Kim Hong-do","artistKo":"김홍도","artistKeys":["kim hong-do","kim hongdo","kimhongdo","hongdo","danwon"],"titleEn":"Ssireum (Korean Wrestling)","titleKo":"씨름","titleKeys":["ssireum","wrestling"],"year":"18세기 후반","desc":"씨름꾼 두 사람의 승부 순간을 중심에 두고 구경꾼들을 둥글게 배치한 풍속화다. 인물들의 생생한 표정과 홀로 딴청인 엿장수의 모습까지 어우러진 단원 풍속화첩의 대표작이다."},
  {"artistEn":"Kim Hong-do","artistKo":"김홍도","artistKeys":["kim hong-do","kim hongdo","kimhongdo","hongdo","danwon"],"titleEn":"Tajak (Threshing)","titleKo":"타작","titleKeys":["tajak","threshing"],"year":"18세기 후반","desc":"볏단을 통나무에 내리치며 타작하는 일꾼들과 자리를 깔고 비스듬히 누워 이를 지켜보는 마름을 대비시켰다. 노동의 활기와 신분 질서를 한 화면에 담은 단원 풍속화첩의 명작이다."},
  {"artistEn":"Kim Jeong-hui","artistKo":"김정희","artistKeys":["kim jeong-hui","kim jeonghui","kimjeonghui","chusa","kim jung-hee"],"titleEn":"Sehando (Winter Scene)","titleKo":"세한도","titleKeys":["sehando","winter"],"year":"1844","desc":"제주 유배 중이던 추사가 변함없이 귀한 책을 보내 준 제자 이상적에게 그려 준 문인화다. 초라한 집 한 채와 소나무, 잣나무만으로 지조와 의리를 표현했으며 국보로 지정되어 있다."},
  {"artistEn":"Kitagawa Utamaro","artistKo":"기타가와 우타마로","artistKeys":["utamaro","kitagawa utamaro","kitagawautamaro"],"titleEn":"Three Beauties of the Present Day","titleKo":"당대 세 미인","titleKeys":["three","beauties"],"year":"c. 1793","desc":"에도에서 이름난 세 미인의 얼굴을 삼각 구도로 배치한 미인화다. 상반신을 크게 담는 '오쿠비에' 형식으로 미묘하게 다른 세 사람의 인상을 구별해 낸 우타마로 미인화의 정수다."},
  {"artistEn":"Kitagawa Utamaro","artistKo":"기타가와 우타마로","artistKeys":["utamaro","kitagawa utamaro","kitagawautamaro"],"titleEn":"Young Woman Blowing a Poppin","titleKo":"포핀을 부는 여인","titleKeys":["poppin","blowing","vidro","glass"],"year":"c. 1792","desc":"유리 장난감 포핀을 입에 대고 부는 젊은 여인의 한가로운 한때를 담았다. 체크무늬 기모노의 섬세한 표현이 돋보이는 작품으로, 우타마로 미인화 중 가장 널리 알려진 이미지의 하나다."},
  {"artistEn":"Leonardo da Vinci","artistKo":"레오나르도 다 빈치","artistKeys":["da vinci","davinci","leonardo","vinci"],"titleEn":"Ginevra de' Benci","titleKo":"지네브라 데 벤치의 초상","titleKeys":["ginevra","benci"],"year":"c. 1474–1478","desc":"피렌체 귀족 여성 지네브라 데 벤치를 그린 초기 초상화로, 창백한 피부와 배경의 노간주나무가 인상적이다. 미국 워싱턴 국립미술관이 소장한 유일한 레오나르도 회화로 알려져 있다."},
  {"artistEn":"Leonardo da Vinci","artistKo":"레오나르도 다 빈치","artistKeys":["da vinci","davinci","leonardo","vinci"],"titleEn":"Lady with an Ermine","titleKo":"흰 담비를 안은 여인","titleKeys":["lady","ermine"],"year":"c. 1489–1491","desc":"흰 담비를 안은 젊은 여인을 그린 초상으로, 밀라노 궁정의 체칠리아 갈레라니를 모델로 한 것으로 알려져 있다. 몸을 살짝 돌린 자연스러운 자세와 섬세한 손의 묘사가 당시로서는 혁신적이라는 평가를 받는다."},
  {"artistEn":"Leonardo da Vinci","artistKo":"레오나르도 다 빈치","artistKeys":["da vinci","davinci","leonardo","vinci"],"titleEn":"Mona Lisa","titleKo":"모나리자","titleKeys":["mona","lisa","monalisa","gioconda"],"year":"c. 1503–1506","desc":"세계에서 가장 유명한 초상화로, 신비로운 미소를 띤 여인의 모습을 그렸다. 윤곽선을 부드럽게 흐리는 스푸마토 기법과 안개 낀 배경 풍경이 어우러져 독특한 분위기를 만들며, 루브르 박물관에 소장되어 있다."},
  {"artistEn":"Leonardo da Vinci","artistKo":"레오나르도 다 빈치","artistKeys":["da vinci","davinci","leonardo","vinci"],"titleEn":"Saint John the Baptist","titleKo":"세례자 성 요한","titleKeys":["saint","john","baptist"],"year":"c. 1513–1516","desc":"어둠 속에서 하늘을 가리키며 미소 짓는 세례자 요한을 그린 레오나르도 만년의 작품이다. 극단적인 명암 대비와 모나리자를 연상시키는 모호한 미소가 신비로운 분위기를 자아내며, 루브르 박물관에 소장되어 있다."},
  {"artistEn":"Leonardo da Vinci","artistKo":"레오나르도 다 빈치","artistKeys":["da vinci","davinci","leonardo","vinci"],"titleEn":"The Annunciation","titleKo":"수태고지","titleKeys":["annunciation"],"year":"c. 1472","desc":"천사 가브리엘이 마리아에게 예수의 잉태를 알리는 수태고지 장면을 그린 초기작이다. 정교한 원근법과 식물 묘사에서 젊은 레오나르도의 관찰력이 드러나며, 천사의 날개는 실제 새의 날개를 연구해 그린 것으로 전해진다."},
  {"artistEn":"Leonardo da Vinci","artistKo":"레오나르도 다 빈치","artistKeys":["da vinci","davinci","leonardo","vinci"],"titleEn":"The Last Supper","titleKo":"최후의 만찬","titleKeys":["last","supper"],"year":"1495–1498","desc":"예수가 제자들과의 마지막 만찬에서 배신을 예고하는 순간을 그린 벽화다. 충격에 휩싸인 제자들의 다양한 반응과 정교한 원근법 구성이 돋보이며, 밀라노 산타 마리아 델레 그라치에 수도원 식당 벽에 그려졌다."},
  {"artistEn":"Leonardo da Vinci","artistKo":"레오나르도 다 빈치","artistKeys":["da vinci","davinci","leonardo","vinci"],"titleEn":"Virgin of the Rocks","titleKo":"암굴의 성모","titleKeys":["virgin","rocks","madonna"],"year":"c. 1483–1486","desc":"바위 동굴 속에서 성모와 아기 예수, 어린 세례자 요한, 천사가 함께 있는 장면을 그렸다. 어두운 배경 속 인물들을 부드러운 빛으로 감싸는 명암 처리가 특징이며, 루브르와 런던 내셔널 갤러리에 두 판본이 전해진다."},
  {"artistEn":"Leonardo da Vinci","artistKo":"레오나르도 다 빈치","artistKeys":["da vinci","davinci","leonardo","vinci"],"titleEn":"Vitruvian Man","titleKo":"비트루비우스적 인간","titleKeys":["vitruvian","man"],"year":"c. 1490","desc":"원과 정사각형 안에 팔다리를 뻗은 인체를 겹쳐 그린 소묘로, 고대 건축가 비트루비우스의 인체 비례론을 시각화했다. 예술과 과학을 결합한 르네상스 정신의 상징으로 꼽히며, 베네치아 아카데미아 미술관이 소장하고 있다."},
  {"artistEn":"Marc Chagall","artistKo":"마르크 샤갈","artistKeys":["chagall","marc chagall","marcchagall"],"titleEn":"I and the Village","titleKo":"나와 마을","titleKeys":["i","village"],"year":"1911","desc":"고향 비테프스크의 기억을 몽환적으로 재구성한 초기 대표작이다. 초록 얼굴의 남자와 염소가 마주 보고, 마을 풍경과 인물들이 중력을 무시한 채 꿈처럼 뒤섞여 있다."},
  {"artistEn":"Marc Chagall","artistKo":"마르크 샤갈","artistKeys":["chagall","marc chagall","marcchagall"],"titleEn":"Over the Town","titleKo":"도시 위에서","titleKeys":["over","town","city"],"year":"1918","desc":"샤갈과 벨라가 서로를 안은 채 고향 비테프스크의 하늘 위를 날아가는 장면을 담았다. 사랑에 빠진 연인이 하늘을 떠다니는 이미지는 이후 샤갈 예술 전체의 상징이 되었다."},
  {"artistEn":"Marc Chagall","artistKo":"마르크 샤갈","artistKeys":["chagall","marc chagall","marcchagall"],"titleEn":"The Birthday","titleKo":"생일","titleKeys":["birthday"],"year":"1915","desc":"생일을 맞은 샤갈에게 꽃을 든 벨라가 찾아온 순간, 몸이 공중에 떠올라 입 맞추는 연인을 그렸다. 결혼 직전 아내 벨라와의 사랑을 담은 샤갈의 가장 서정적인 작품으로 꼽힌다."},
  {"artistEn":"Marc Chagall","artistKo":"마르크 샤갈","artistKeys":["chagall","marc chagall","marcchagall"],"titleEn":"The Promenade","titleKo":"산책","titleKeys":["promenade","walk"],"year":"1917-1918","desc":"샤갈이 한 손으로 하늘에 연처럼 떠오른 벨라의 손을 잡고 있는 행복한 장면이다. 러시아 혁명기의 혼란 속에서도 사랑의 환희를 밝은 초록 들판과 경쾌한 색채로 노래했다."},
  {"artistEn":"Mary Cassatt","artistKo":"메리 커샛","artistKeys":["cassatt","mary cassatt"],"titleEn":"Little Girl in a Blue Armchair","titleKo":"파란 안락의자에 앉은 어린 소녀","titleKeys":["little","girl","blue","armchair"],"year":"1878","desc":"파란 안락의자에 나른하게 몸을 파묻은 소녀와 옆 의자에서 잠든 강아지를 그린 작품이다. 아이의 꾸밈없는 자세를 솔직하게 포착했으며, 친구였던 드가가 배경 일부를 손봐준 것으로 알려져 있다."},
  {"artistEn":"Mary Cassatt","artistKo":"메리 커샛","artistKeys":["cassatt","mary cassatt"],"titleEn":"The Boating Party","titleKo":"뱃놀이","titleKeys":["boating","party"],"year":"1893-1894","desc":"노 젓는 사공과 아이를 안은 여인이 마주 앉은 보트 안 풍경을 그린 작품이다. 사공의 짙은 실루엣과 과감하게 잘린 구도, 선명한 색면이 일본 판화의 영향을 보여주는 커샛 후기의 대표작이다."},
  {"artistEn":"Mary Cassatt","artistKo":"메리 커샛","artistKeys":["cassatt","mary cassatt"],"titleEn":"The Child's Bath","titleKo":"아이의 목욕","titleKeys":["child","bath","childs"],"year":"1893","desc":"어머니가 무릎에 앉힌 아이의 발을 씻겨주는 다정한 순간을 그린 커샛의 대표작이다. 위에서 내려다보는 구도와 줄무늬 옷의 평면적 패턴에서 일본 판화의 영향이 뚜렷하며, 모자간의 친밀함이 따뜻하게 전해진다."},
  {"artistEn":"Mary Cassatt","artistKo":"메리 커샛","artistKeys":["cassatt","mary cassatt"],"titleEn":"The Cup of Tea","titleKo":"차 한 잔","titleKeys":["cup","tea"],"year":"1880-1881","desc":"분홍 드레스를 입은 여인이 오후의 차를 마시는 모습을 그린 작품으로, 모델은 커샛의 언니 리디아이다. 파리 부르주아 여성의 일상 의례를 반짝이는 붓질로 담아냈으며, 인상파 전시에도 출품되었다."},
  {"artistEn":"Michelangelo","artistKo":"미켈란젤로","artistKeys":["michelangelo","buonarroti"],"titleEn":"David","titleKo":"다비드","titleKeys":["david"],"year":"1501–1504","desc":"돌팔매로 골리앗과 맞서기 직전의 다윗을 표현한 대리석 조각상이다. 긴장감이 감도는 표정과 이상적인 인체 비례로 르네상스 조각의 정점으로 평가되며, 피렌체 아카데미아 미술관에 소장되어 있다."},
  {"artistEn":"Michelangelo","artistKo":"미켈란젤로","artistKeys":["michelangelo","buonarroti"],"titleEn":"Doni Tondo","titleKo":"도니 톤도(성가족)","titleKeys":["doni","tondo","holy","family"],"year":"c. 1507","desc":"원형 화면에 성모와 요셉, 아기 예수로 이루어진 성가족을 그린 패널화다. 조각처럼 견고한 인체 표현과 선명한 색채가 특징으로, 미켈란젤로가 완성한 몇 안 되는 패널화 중 하나이며 우피치 미술관에 있다."},
  {"artistEn":"Michelangelo","artistKo":"미켈란젤로","artistKeys":["michelangelo","buonarroti"],"titleEn":"Pietà","titleKo":"피에타","titleKeys":["pieta"],"year":"1498–1499","desc":"십자가에서 내려진 예수를 무릎에 안은 성모 마리아를 표현한 대리석 조각이다. 젊고 아름다운 성모의 모습과 섬세한 옷 주름 표현이 특징이며, 바티칸 성 베드로 대성당에 있는 미켈란젤로 초기의 걸작이다."},
  {"artistEn":"Michelangelo","artistKo":"미켈란젤로","artistKeys":["michelangelo","buonarroti"],"titleEn":"The Creation of Adam","titleKo":"아담의 창조","titleKeys":["creation","adam"],"year":"c. 1512","desc":"시스티나 예배당 천장화의 중심 장면으로, 신이 손끝으로 아담에게 생명을 불어넣는 순간을 그렸다. 맞닿을 듯 말 듯 떨어져 있는 두 손가락은 서양 미술에서 가장 유명한 이미지 중 하나가 되었다."},
  {"artistEn":"Michelangelo","artistKo":"미켈란젤로","artistKeys":["michelangelo","buonarroti"],"titleEn":"The Last Judgment","titleKo":"최후의 심판","titleKeys":["last","judgment","judgement"],"year":"1536–1541","desc":"시스티나 예배당 제단 벽면을 가득 채운 대형 벽화로, 그리스도의 재림과 최후의 심판 장면을 그렸다. 수백 명의 인물이 소용돌이치듯 배치된 역동적 구성이 압도적이며, 미켈란젤로 만년의 대표작이다."},
  {"artistEn":"Nicolas Poussin","artistKo":"니콜라 푸생","artistKeys":["poussin","nicolas"],"titleEn":"A Dance to the Music of Time","titleKo":"시간의 음악에 맞춘 춤","titleKeys":["dance","music","time"],"year":"c. 1634–1636","desc":"시간의 신이 연주하는 리라에 맞춰 네 인물이 원을 그리며 춤추는 알레고리화다. 빈곤과 노동, 부, 쾌락이 돌고 도는 인생의 수레바퀴를 우의적으로 표현했으며, 런던 월리스 컬렉션에 소장되어 있다."},
  {"artistEn":"Nicolas Poussin","artistKo":"니콜라 푸생","artistKeys":["poussin","nicolas"],"titleEn":"Et in Arcadia Ego","titleKo":"아르카디아의 목자들","titleKeys":["arcadia","shepherds","ego"],"year":"c. 1638–1640","desc":"이상향 아르카디아의 목자들이 무덤에 새겨진 글귀를 읽으며 생각에 잠긴 장면을 그렸다. 낙원에도 죽음이 있다는 명제를 균형 잡힌 고전적 구도로 표현한 프랑스 고전주의 회화의 대표작이다."},
  {"artistEn":"Nicolas Poussin","artistKo":"니콜라 푸생","artistKeys":["poussin","nicolas"],"titleEn":"The Abduction of the Sabine Women","titleKo":"사비니 여인들의 납치","titleKeys":["abduction","sabine","women"],"year":"c. 1634–1635","desc":"로마 건국 신화에서 사비니 여인들이 납치되는 혼란의 순간을 그렸다. 격렬한 움직임조차 치밀하게 계산된 무대 같은 구도 속에 배치한 데서 푸생의 고전주의적 질서 감각이 잘 드러난다."},
  {"artistEn":"Odilon Redon","artistKo":"오딜롱 르동","artistKeys":["redon","odilon redon"],"titleEn":"Bouquet of Flowers","titleKo":"꽃다발","titleKeys":["bouquet","flowers"],"year":"1900-1905","desc":"화병에 꽂힌 들꽃과 양귀비 등을 파스텔로 그린 르동 후기의 꽃 정물이다. 젊은 시절 목탄의 검은 환상 세계에 몰두했던 르동은 만년에 이르러 빛나는 색채의 꽃 그림으로 전환했으며, 꿈꾸는 듯한 색의 향연이 펼쳐진다."},
  {"artistEn":"Odilon Redon","artistKo":"오딜롱 르동","artistKeys":["redon","odilon redon"],"titleEn":"The Cyclops","titleKo":"키클롭스","titleKeys":["cyclops"],"year":"1914","desc":"그리스 신화의 외눈 거인 폴리페모스가 산 너머에서 잠든 님프 갈라테이아를 수줍게 바라보는 장면을 그린 작품이다. 무시무시한 괴물을 애틋한 존재로 그려낸 상징주의적 상상력과 몽환적인 색채가 인상적이다."},
  {"artistEn":"Paul Cézanne","artistKo":"폴 세잔","artistKeys":["cezanne","paul cezanne"],"titleEn":"Boy in a Red Vest","titleKo":"붉은 조끼를 입은 소년","titleKeys":["boy","red","vest"],"year":"1888-1890","desc":"붉은 조끼를 입은 이탈리아 소년 모델을 그린 인물화 연작 중 하나다. 팔꿈치를 괴고 생각에 잠긴 자세가 인상적이며, 해부학적 정확성보다 화면의 조형적 균형을 우선한 세잔 인물화의 정수를 보여준다."},
  {"artistEn":"Paul Cézanne","artistKo":"폴 세잔","artistKeys":["cezanne","paul cezanne"],"titleEn":"Mont Sainte-Victoire","titleKo":"생트빅투아르 산","titleKeys":["mont","sainte-victoire","victoire"],"year":"1902-1904","desc":"고향 엑상프로방스의 생트빅투아르 산을 평생에 걸쳐 80회 이상 반복해 그린 연작이다. 자연을 색면의 구축으로 재해석한 후기 연작은 형태의 해체와 재구성을 통해 입체주의 탄생에 결정적 영향을 주었다."},
  {"artistEn":"Paul Cézanne","artistKo":"폴 세잔","artistKeys":["cezanne","paul cezanne"],"titleEn":"Still Life with Apples and Oranges","titleKo":"사과와 오렌지가 있는 정물","titleKeys":["apples","oranges"],"year":"1899","desc":"구겨진 흰 천 위에 사과와 오렌지가 쌓인 화려한 정물화로, 세잔 정물의 완숙기를 대표한다. 과일과 그릇, 직물이 서로 밀고 당기는 긴장 속에 배치되어 정물화를 조형적 구축의 문제로 끌어올렸다."},
  {"artistEn":"Paul Cézanne","artistKo":"폴 세잔","artistKeys":["cezanne","paul cezanne"],"titleEn":"The Basket of Apples","titleKo":"사과 바구니","titleKeys":["basket","apples"],"year":"1893","desc":"기울어진 바구니에서 쏟아질 듯한 사과와 병, 접시 위 비스킷을 그린 정물화이다. 하나의 화면에 여러 시점을 공존시켜 전통 원근법을 해체했으며, 사과 하나로 파리를 놀라게 하겠다던 세잔의 야심을 보여준다."},
  {"artistEn":"Paul Cézanne","artistKo":"폴 세잔","artistKeys":["cezanne","paul cezanne"],"titleEn":"The Bay of Marseilles, Seen from L'Estaque","titleKo":"레스타크에서 본 마르세유 만","titleKeys":["bay","marseilles","estaque"],"year":"1885","desc":"남프랑스 레스타크 언덕에서 내려다본 마르세유 만의 짙푸른 바다와 주황빛 지붕들을 그린 작품이다. 바다를 벽처럼 세운 수직적 구성과 색면의 대비가 훗날 입체주의 화가들에게 깊은 인상을 남겼다."},
  {"artistEn":"Paul Cézanne","artistKo":"폴 세잔","artistKeys":["cezanne","paul cezanne"],"titleEn":"The Card Players","titleKo":"카드놀이 하는 사람들","titleKeys":["card","players"],"year":"1890-1895","desc":"엑상프로방스의 농부들이 탁자에 마주 앉아 카드놀이에 몰두하는 모습을 그린 연작이다. 인물들을 기념비처럼 견고하게 구축한 화면이 특징이며, 연작 중 한 점은 2011년 약 2억 5천만 달러에 거래되어 화제가 되었다."},
  {"artistEn":"Paul Cézanne","artistKo":"폴 세잔","artistKeys":["cezanne","paul cezanne"],"titleEn":"The House of the Hanged Man","titleKo":"목맨 사람의 집","titleKeys":["house","hanged","man"],"year":"1873","desc":"오베르쉬르우아즈의 시골집과 갈라진 길을 그린 초기 대표작으로, 1874년 첫 인상파 전시에 출품되었다. 피사로의 영향 아래 밝은 색채를 받아들이면서도 두껍게 쌓아 올린 물감층에서 견고한 구축성이 드러난다."},
  {"artistEn":"Paul Cézanne","artistKo":"폴 세잔","artistKeys":["cezanne","paul cezanne"],"titleEn":"The Large Bathers","titleKo":"대수욕도","titleKeys":["large","bathers","baigneuses"],"year":"1898-1905","desc":"강가에서 목욕하는 여인들을 아치형으로 기운 나무 아래 배치한 세잔 최후의 대작이다. 인체를 풍경의 구조 속에 통합한 기하학적 구성은 피카소와 마티스 등 20세기 화가들에게 지대한 영향을 미쳤다."},
  {"artistEn":"Paul Gauguin","artistKo":"폴 고갱","artistKeys":["gauguin","paul gauguin"],"titleEn":"Ia Orana Maria (Hail Mary)","titleKo":"이아 오라나 마리아","titleKeys":["orana","maria","hail mary"],"year":"1891","desc":"성모자와 수태고지의 도상을 타히티 사람들의 모습으로 재해석한 작품이다. 어깨에 아기 예수를 얹은 타히티 여인 마리아와 경배하는 두 여인이 열대의 풍요로운 색채 속에 그려져, 기독교와 폴리네시아 문화가 융합되었다."},
  {"artistEn":"Paul Gauguin","artistKo":"폴 고갱","artistKeys":["gauguin","paul gauguin"],"titleEn":"Spirit of the Dead Watching","titleKo":"죽은 자의 혼이 지켜본다","titleKeys":["spirit","dead","watching","manao"],"year":"1892","desc":"침대에 엎드린 타히티 소녀 뒤로 죽은 자의 혼령이 검은 형상으로 앉아 있는 작품이다. 마네의 올랭피아를 의식한 구도에 폴리네시아의 정령 신앙을 결합했으며, 보랏빛 어둠이 신비와 공포의 분위기를 자아낸다."},
  {"artistEn":"Paul Gauguin","artistKo":"폴 고갱","artistKeys":["gauguin","paul gauguin"],"titleEn":"Tahitian Women on the Beach","titleKo":"해변의 타히티 여인들","titleKeys":["tahitian","women","beach"],"year":"1891","desc":"타히티에 도착한 첫해에 그린 작품으로, 해변에 앉은 두 원주민 여인의 육중하고 조용한 존재감이 화면을 채운다. 단순화된 형태와 평면적 색면을 통해 남태평양의 원시적 평온을 담아냈다."},
  {"artistEn":"Paul Gauguin","artistKo":"폴 고갱","artistKeys":["gauguin","paul gauguin"],"titleEn":"The Yellow Christ","titleKo":"황색 그리스도","titleKeys":["yellow","christ"],"year":"1889","desc":"브르타뉴의 가을 들판을 배경으로 노란색 그리스도 십자가상과 기도하는 농촌 여인들을 그린 작품이다. 현실의 색을 벗어난 상징적 색채와 단순화된 형태로 종합주의 회화의 대표작으로 꼽힌다."},
  {"artistEn":"Paul Gauguin","artistKo":"폴 고갱","artistKeys":["gauguin","paul gauguin"],"titleEn":"Vision After the Sermon","titleKo":"설교 후의 환상","titleKeys":["vision","sermon"],"year":"1888","desc":"설교를 들은 브르타뉴 여인들이 야곱과 천사의 씨름 환상을 목격하는 장면을 그린 작품이다. 현실과 환상이 강렬한 붉은 땅 위에서 하나로 만나며, 상징주의 회화의 문을 연 기념비적 작품으로 평가된다."},
  {"artistEn":"Paul Gauguin","artistKo":"폴 고갱","artistKeys":["gauguin","paul gauguin"],"titleEn":"When Will You Marry? (Nafea Faa Ipoipo)","titleKo":"언제 결혼하니","titleKeys":["when","marry","nafea"],"year":"1892","desc":"타히티의 두 여인을 열대의 색채 속에 그린 작품으로, 앞쪽 여인은 전통 의상을, 뒤쪽 여인은 선교사풍 드레스를 입고 있다. 2015년 개인 거래에서 약 3억 달러에 팔리며 세계에서 가장 비싼 그림 중 하나로 화제가 되었다."},
  {"artistEn":"Paul Gauguin","artistKo":"폴 고갱","artistKeys":["gauguin","paul gauguin"],"titleEn":"Where Do We Come From? What Are We? Where Are We Going?","titleKo":"우리는 어디서 왔는가, 우리는 무엇인가, 우리는 어디로 가는가","titleKeys":["where","come","going"],"year":"1897-1898","desc":"타히티에서 그린 고갱 필생의 대작으로, 탄생에서 죽음에 이르는 인간의 생애를 오른쪽에서 왼쪽으로 펼쳐 보인다. 딸의 죽음과 절망 속에서 유언처럼 그린 작품으로, 삶의 근원에 대한 물음을 화폭에 담았다."},
  {"artistEn":"Paul Signac","artistKo":"폴 시냐크","artistKeys":["signac","paul signac"],"titleEn":"Portrait of Félix Fénéon","titleKo":"펠릭스 페네옹의 초상","titleKeys":["felix","feneon"],"year":"1890","desc":"신인상주의라는 명칭을 만든 비평가 펠릭스 페네옹을 그린 초상화로, 소용돌이치는 추상적 문양을 배경으로 꽃을 든 옆모습이 그려져 있다. 장식적 배경과 점묘 기법이 결합된 실험적 초상화의 대표작이다."},
  {"artistEn":"Paul Signac","artistKo":"폴 시냐크","artistKeys":["signac","paul signac"],"titleEn":"The Papal Palace, Avignon","titleKo":"아비뇽 교황청","titleKeys":["papal","palace","avignon"],"year":"1900","desc":"론 강 너머로 바라본 아비뇽 교황청을 보랏빛과 주황빛 색점으로 그린 작품이다. 쇠라 사후 신인상주의를 이끈 시냐크는 점을 더 크고 자유로운 모자이크식 터치로 발전시켰으며, 이 작품에서 그 원숙미가 드러난다."},
  {"artistEn":"Peter Paul Rubens","artistKo":"페테르 파울 루벤스","artistKeys":["rubens","peter paul"],"titleEn":"Massacre of the Innocents","titleKo":"무고한 자들의 학살","titleKeys":["massacre","innocents"],"year":"c. 1611–1612","desc":"헤롯왕의 명령으로 베들레헴의 아기들이 학살당하는 성서의 비극을 격렬한 몸싸움으로 표현했다. 뒤엉킨 인체와 절박한 감정 묘사가 바로크 회화의 극적인 힘을 유감없이 보여주는 작품이다."},
  {"artistEn":"Peter Paul Rubens","artistKo":"페테르 파울 루벤스","artistKeys":["rubens","peter paul"],"titleEn":"The Descent from the Cross","titleKo":"십자가에서 내림","titleKeys":["descent","cross"],"year":"1612–1614","desc":"십자가에서 내려지는 그리스도의 시신을 흰 천을 중심으로 한 사선 구도로 그린 대형 제단화다. 안트베르펜 대성당에 소장되어 있으며, 플랑드르 바로크 종교화의 대표작으로 꼽힌다."},
  {"artistEn":"Peter Paul Rubens","artistKo":"페테르 파울 루벤스","artistKeys":["rubens","peter paul"],"titleEn":"The Elevation of the Cross","titleKo":"십자가를 세움","titleKeys":["elevation","raising","cross"],"year":"1610–1611","desc":"그리스도가 달린 십자가를 병사들이 힘겹게 일으켜 세우는 순간을 그린 세 폭 제단화다. 근육질 인체와 사선의 역동적 구도에서 이탈리아에서 돌아온 루벤스의 넘치는 에너지가 그대로 드러난다."},
  {"artistEn":"Peter Paul Rubens","artistKo":"페테르 파울 루벤스","artistKeys":["rubens","peter paul"],"titleEn":"The Garden of Love","titleKo":"사랑의 정원","titleKeys":["garden","love"],"year":"c. 1633","desc":"우아한 정원에서 사랑을 속삭이는 남녀들과 큐피드들을 그린 화려한 연회 장면이다. 두 번째 아내 헬레나와의 행복한 결혼 생활이 반영된 작품으로 해석되며, 프라도 미술관에 소장되어 있다."},
  {"artistEn":"Peter Paul Rubens","artistKo":"페테르 파울 루벤스","artistKeys":["rubens","peter paul"],"titleEn":"The Three Graces","titleKo":"삼미신","titleKeys":["three","graces"],"year":"c. 1630–1635","desc":"서로 손을 맞잡고 둘러선 세 여신을 그린 신화화로, 루벤스 특유의 풍만하고 생동감 있는 인체 표현이 잘 드러난다. 두 번째 아내 헬레나를 모델로 삼은 것으로 알려져 있으며, 프라도 미술관에 있다."},
  {"artistEn":"Pierre-Auguste Renoir","artistKo":"피에르 오귀스트 르누아르","artistKeys":["renoir","auguste renoir","pierre-auguste renoir"],"titleEn":"Bal du moulin de la Galette","titleKo":"물랭 드 라 갈레트의 무도회","titleKeys":["moulin","galette","bal"],"year":"1876","desc":"몽마르트르 야외 무도회장에서 춤추고 담소하는 파리 시민들의 흥겨운 오후를 그린 대작이다. 나뭇잎 사이로 쏟아지는 햇빛이 인물들 위에 얼룩덜룩 어른거리는 표현이 백미로, 인상주의 풍속화의 걸작으로 꼽힌다."},
  {"artistEn":"Pierre-Auguste Renoir","artistKo":"피에르 오귀스트 르누아르","artistKeys":["renoir","auguste renoir","pierre-auguste renoir"],"titleEn":"Dance at Bougival","titleKo":"부지발의 춤","titleKeys":["dance","bougival"],"year":"1883","desc":"파리 근교 유원지 부지발에서 춤추는 한 쌍의 남녀를 실물 크기로 그린 작품이다. 여인의 모델은 화가 수잔 발라동으로 알려져 있으며, 붉은 보닛과 흰 드레스가 만드는 회전의 율동감이 화면에 가득하다."},
  {"artistEn":"Pierre-Auguste Renoir","artistKo":"피에르 오귀스트 르누아르","artistKeys":["renoir","auguste renoir","pierre-auguste renoir"],"titleEn":"Girls at the Piano","titleKo":"피아노 치는 소녀들","titleKeys":["girls","piano"],"year":"1892","desc":"피아노 앞에서 악보를 보며 연습하는 두 소녀를 그린 작품으로, 프랑스 정부가 뤽상부르 미술관을 위해 주문했다. 부드러운 색조와 따뜻한 실내 분위기가 어우러진 르누아르 후기의 대표작이다."},
  {"artistEn":"Pierre-Auguste Renoir","artistKo":"피에르 오귀스트 르누아르","artistKeys":["renoir","auguste renoir","pierre-auguste renoir"],"titleEn":"La Loge","titleKo":"라 로주 (극장의 특별석)","titleKeys":["loge"],"year":"1874","desc":"오페라 극장 특별석에 앉은 화려한 차림의 여인과 오페라글라스로 객석을 살피는 남자를 그린 작품이다. 1874년 첫 인상파 전시에 출품되었으며, 줄무늬 드레스의 질감 표현과 근대 사교 문화의 묘사가 돋보인다."},
  {"artistEn":"Pierre-Auguste Renoir","artistKo":"피에르 오귀스트 르누아르","artistKeys":["renoir","auguste renoir","pierre-auguste renoir"],"titleEn":"Luncheon of the Boating Party","titleKo":"뱃놀이 일행의 오찬","titleKeys":["luncheon","boating","party"],"year":"1880-1881","desc":"센 강변 레스토랑 테라스에서 뱃놀이를 마친 친구들이 어울려 식사하는 장면을 그린 작품이다. 강아지를 안고 있는 왼쪽 여인은 훗날 르누아르의 아내가 된 알린 샤리고로, 청춘의 여유와 우정이 화면에 넘친다."},
  {"artistEn":"Pierre-Auguste Renoir","artistKo":"피에르 오귀스트 르누아르","artistKeys":["renoir","auguste renoir","pierre-auguste renoir"],"titleEn":"The Swing","titleKo":"그네","titleKeys":["swing"],"year":"1876","desc":"몽마르트르 정원에서 그네에 기대선 여인과 대화하는 남자들을 그린 작품이다. 나무 사이로 스며든 햇살이 인물의 옷과 땅 위에 파란 얼룩으로 어른거리며, 물랭 드 라 갈레트의 무도회와 같은 시기에 그려졌다."},
  {"artistEn":"Pierre-Auguste Renoir","artistKo":"피에르 오귀스트 르누아르","artistKeys":["renoir","auguste renoir","pierre-auguste renoir"],"titleEn":"The Umbrellas","titleKo":"우산들","titleKeys":["umbrellas"],"year":"1881-1886","desc":"비 오는 파리 거리에서 우산을 쓴 군중을 그린 작품으로, 수년에 걸쳐 완성되어 두 가지 화풍이 공존한다. 오른쪽 인물들은 부드러운 인상주의 기법으로, 왼쪽 여인은 앵그르풍의 단단한 선묘로 그려져 화풍 전환기를 보여준다."},
  {"artistEn":"Pierre-Auguste Renoir","artistKo":"피에르 오귀스트 르누아르","artistKeys":["renoir","auguste renoir","pierre-auguste renoir"],"titleEn":"Two Sisters (On the Terrace)","titleKo":"테라스에서 (두 자매)","titleKeys":["two","sisters","terrace"],"year":"1881","desc":"센 강이 내려다보이는 테라스에서 붉은 모자를 쓴 젊은 여인과 꽃 장식 모자의 어린 소녀를 그린 작품이다. 털실 바구니의 알록달록한 색채와 화사한 봄 풍경이 어우러져 르누아르 특유의 생기가 빛난다."},
  {"artistEn":"Piet Mondrian","artistKo":"피트 몬드리안","artistKeys":["mondrian","piet mondrian","pietmondrian"],"titleEn":"Broadway Boogie Woogie","titleKo":"브로드웨이 부기우기","titleKeys":["broadway","boogie","woogie"],"year":"1942-1943","desc":"뉴욕 이주 후 재즈와 도시의 활기에서 영감을 받아 그린 말년의 대표작이다. 검은 선 대신 노란 격자와 색 점들이 맨해튼 거리의 불빛과 리듬을 경쾌하게 표현한다."},
  {"artistEn":"Piet Mondrian","artistKo":"피트 몬드리안","artistKeys":["mondrian","piet mondrian","pietmondrian"],"titleEn":"Composition with Red, Blue and Yellow","titleKo":"빨강, 파랑, 노랑의 구성","titleKeys":["composition","red","blue","yellow"],"year":"1930","desc":"흰 바탕을 검은 수직선과 수평선으로 나누고 삼원색 면을 배치한 신조형주의의 대표작이다. 자연의 재현을 완전히 배제하고 순수한 조형 요소만으로 보편적 조화를 추구했다."},
  {"artistEn":"Piet Mondrian","artistKo":"피트 몬드리안","artistKeys":["mondrian","piet mondrian","pietmondrian"],"titleEn":"Evening: The Red Tree","titleKo":"저녁: 붉은 나무","titleKeys":["evening","red","tree"],"year":"1908-1910","desc":"짙푸른 하늘을 배경으로 붉게 타오르는 듯한 나무를 그린 초기작이다. 야수파적 색채가 두드러지며, 이후 추상으로 이어지는 몬드리안 나무 연작의 출발점이 된 작품이다."},
  {"artistEn":"Piet Mondrian","artistKo":"피트 몬드리안","artistKeys":["mondrian","piet mondrian","pietmondrian"],"titleEn":"The Gray Tree","titleKo":"회색 나무","titleKeys":["gray","grey","tree"],"year":"1911","desc":"큐비즘의 영향 아래 나무의 형태를 회색조의 선과 면으로 해체한 작품이다. 구상에서 추상으로 나아가는 몬드리안의 전환기를 보여주는 나무 연작의 핵심작으로 꼽힌다."},
  {"artistEn":"Pieter Bruegel the Elder","artistKo":"피터르 브뤼헐","artistKeys":["bruegel","brueghel","breugel"],"titleEn":"Hunters in the Snow","titleKo":"눈 속의 사냥꾼들","titleKeys":["hunters","snow","winter"],"year":"1565","desc":"사냥에서 돌아오는 사냥꾼들과 눈 덮인 마을을 높은 곳에서 내려다보는 구도로 그린 겨울 그림이다. 계절 연작 중 하나로, 얼어붙은 연못에서 스케이트를 타는 사람들까지 담아 서양 미술에서 가장 유명한 겨울 풍경화가 되었다."},
  {"artistEn":"Pieter Bruegel the Elder","artistKo":"피터르 브뤼헐","artistKeys":["bruegel","brueghel","breugel"],"titleEn":"Landscape with the Fall of Icarus","titleKo":"이카로스의 추락이 있는 풍경","titleKeys":["fall","icarus"],"year":"c. 1560","desc":"밭을 가는 농부의 평온한 일상 뒤편 바다에 추락하는 이카로스의 다리를 작게 그려 넣었다. 비극에 무심한 세상을 표현한 역설적 구성으로 널리 알려졌으며, 여러 시인들이 이 그림을 소재로 시를 남겼다."},
  {"artistEn":"Pieter Bruegel the Elder","artistKo":"피터르 브뤼헐","artistKeys":["bruegel","brueghel","breugel"],"titleEn":"Netherlandish Proverbs","titleKo":"네덜란드 속담","titleKeys":["netherlandish","proverbs"],"year":"1559","desc":"백 개가 넘는 네덜란드 속담을 한 마을 풍경 안에 담아낸 그림이다. 인간의 어리석음을 풍자하는 장면들이 화면 곳곳에 숨어 있어 찾아보는 재미가 있으며, 베를린 국립회화관에 소장되어 있다."},
  {"artistEn":"Pieter Bruegel the Elder","artistKo":"피터르 브뤼헐","artistKeys":["bruegel","brueghel","breugel"],"titleEn":"The Harvesters","titleKo":"수확하는 사람들","titleKeys":["harvesters","harvest"],"year":"1565","desc":"황금빛 밀밭에서 수확하다 나무 그늘 아래에서 쉬는 농민들을 그린 계절 연작의 하나다. 이상화하지 않은 노동의 풍경을 있는 그대로 담아 서양 풍경화의 새 장을 연 작품으로 평가되며, 뉴욕 메트로폴리탄 미술관에 있다."},
  {"artistEn":"Pieter Bruegel the Elder","artistKo":"피터르 브뤼헐","artistKeys":["bruegel","brueghel","breugel"],"titleEn":"The Peasant Wedding","titleKo":"농민의 결혼식","titleKeys":["peasant","wedding"],"year":"c. 1567","desc":"헛간에서 벌어진 농민들의 혼례 잔치를 생생하게 그린 풍속화다. 음식을 나르는 사람들과 흥겨운 하객, 조용히 앉은 신부의 모습에서 16세기 플랑드르 농촌의 일상이 그대로 전해진다."},
  {"artistEn":"Pieter Bruegel the Elder","artistKo":"피터르 브뤼헐","artistKeys":["bruegel","brueghel","breugel"],"titleEn":"The Tower of Babel","titleKo":"바벨탑","titleKeys":["tower","babel"],"year":"1563","desc":"성서 속 바벨탑을 거대한 나선형 건축물로 상상해 그린 작품이다. 수많은 인부와 건설 장비, 항구의 배까지 세밀하게 묘사해 인간 야망의 웅대함과 허무함을 동시에 보여주며, 빈 미술사 박물관에 소장되어 있다."},
  {"artistEn":"Raphael","artistKo":"라파엘로","artistKeys":["raphael","raffaello","sanzio"],"titleEn":"Madonna della Sedia","titleKo":"의자의 성모","titleKeys":["madonna","sedia","chair"],"year":"c. 1513–1514","desc":"원형 화면에 아기 예수를 꼭 껴안은 성모를 그린 작품으로, 친밀하고 따뜻한 모자의 정을 담아냈다. 라파엘로의 성모자상 가운데 가장 대중적인 사랑을 받는 그림 중 하나로, 피렌체 피티 궁전에 소장되어 있다."},
  {"artistEn":"Raphael","artistKo":"라파엘로","artistKeys":["raphael","raffaello","sanzio"],"titleEn":"Madonna of the Goldfinch","titleKo":"검은방울새의 성모","titleKeys":["madonna","goldfinch"],"year":"c. 1506","desc":"성모 앞에서 아기 예수와 어린 세례자 요한이 검은방울새를 어루만지는 장면을 그린 피렌체 시기의 성모자상이다. 안정된 삼각형 구도와 부드러운 색채가 라파엘로 특유의 온화한 아름다움을 보여준다."},
  {"artistEn":"Raphael","artistKo":"라파엘로","artistKeys":["raphael","raffaello","sanzio"],"titleEn":"Portrait of Baldassare Castiglione","titleKo":"발다사레 카스틸리오네의 초상","titleKeys":["baldassare","castiglione"],"year":"c. 1514–1515","desc":"르네상스의 대표적 문인 발다사레 카스틸리오네를 그린 초상화다. 절제된 회색조 색채와 차분한 시선으로 이상적인 궁정인의 품격을 표현했으며, 이후 렘브란트 등 많은 화가에게 초상화의 모범이 되었다."},
  {"artistEn":"Raphael","artistKo":"라파엘로","artistKeys":["raphael","raffaello","sanzio"],"titleEn":"Sistine Madonna","titleKo":"시스티나의 성모","titleKeys":["sistine","madonna"],"year":"1512–1513","desc":"구름 위에 선 성모가 아기 예수를 안고 내려오는 모습을 그린 제단화다. 화면 아래에서 턱을 괴고 있는 두 아기 천사는 독립적인 이미지로도 세계적으로 사랑받으며, 드레스덴 고전거장미술관에 소장되어 있다."},
  {"artistEn":"Raphael","artistKo":"라파엘로","artistKeys":["raphael","raffaello","sanzio"],"titleEn":"The School of Athens","titleKo":"아테네 학당","titleKeys":["school","athens"],"year":"1509–1511","desc":"바티칸 궁전 서명의 방에 그려진 벽화로, 플라톤과 아리스토텔레스를 중심으로 고대 그리스 철학자들이 한자리에 모인 장면을 담았다. 완벽한 원근법 구성과 인물들의 조화로 전성기 르네상스의 정수로 꼽힌다."},
  {"artistEn":"Raphael","artistKo":"라파엘로","artistKeys":["raphael","raffaello","sanzio"],"titleEn":"The Transfiguration","titleKo":"그리스도의 변용","titleKeys":["transfiguration"],"year":"1516–1520","desc":"산 위에서 빛에 휩싸여 변모하는 그리스도와 산 아래에서 소년을 치유하지 못해 동요하는 제자들을 한 화면에 담았다. 라파엘로가 죽기 직전까지 매달린 마지막 걸작으로, 바티칸 미술관에 소장되어 있다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"Bathsheba at Her Bath","titleKo":"목욕하는 밧세바","titleKeys":["bathsheba","bath"],"year":"1654","desc":"다윗 왕의 편지를 손에 든 밧세바의 복잡한 심경을 그린 누드화다. 유혹적인 장면 대신 깊은 생각에 잠긴 여인의 내면 갈등을 담아낸 심리 묘사가 이 작품을 특별하게 만들며, 루브르 박물관에 있다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"Belshazzar's Feast","titleKo":"벨사살의 연회","titleKeys":["belshazzar","feast"],"year":"c. 1635–1638","desc":"연회 도중 벽에 나타난 신의 글씨를 보고 공포에 질린 바빌론 왕 벨사살의 순간을 그렸다. 어둠 속에서 빛나는 히브리 문자와 몸을 젖히며 놀라는 인물들의 극적인 포착이 압도적이며, 런던 내셔널 갤러리에 있다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"Danaë","titleKo":"다나에","titleKeys":["danae"],"year":"1636","desc":"황금빛으로 변해 찾아오는 제우스를 맞이하는 다나에를 실물 크기로 그린 신화화다. 부드러운 빛에 감싸인 인체 표현이 뛰어나며, 상트페테르부르크 예르미타시 미술관에 소장되어 있다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"Self-Portrait with Two Circles","titleKo":"두 개의 원이 있는 자화상","titleKeys":["self","portrait","circles"],"year":"c. 1665–1669","desc":"팔레트와 붓을 든 노년의 화가가 두 개의 원이 그려진 벽 앞에 서 있는 자화상이다. 평생에 걸쳐 자화상을 그린 렘브란트 만년의 원숙한 경지를 보여주는 작품으로, 원의 의미를 둘러싼 해석이 분분하다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"Syndics of the Drapers' Guild","titleKo":"포목상 조합 이사들","titleKeys":["syndics","drapers","guild"],"year":"1662","desc":"직물의 품질을 감독하던 조합 임원들을 그린 집단 초상화로, 회의 중 잠시 관람자 쪽을 바라보는 듯한 자연스러운 순간을 연출했다. 네덜란드 집단 초상화 전통의 정점으로 평가되는 만년의 걸작이다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"The Anatomy Lesson of Dr Nicolaes Tulp","titleKo":"니콜라스 튈프 박사의 해부학 강의","titleKeys":["anatomy","lesson","tulp"],"year":"1632","desc":"튈프 박사가 시신의 팔 근육 해부를 시연하는 장면을 그린 집단 초상화다. 긴장감 있게 몰입한 인물들의 배치와 극적인 조명으로, 스물여섯의 렘브란트가 암스테르담에서 명성을 얻는 계기가 된 초기 걸작이다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"The Jewish Bride","titleKo":"유대인 신부","titleKeys":["jewish","bride"],"year":"c. 1665–1669","desc":"다정하게 손을 포갠 부부를 그린 작품으로, 두텁게 쌓아 올린 물감으로 표현한 붉은 드레스와 황금빛 소매가 압권이다. 고흐가 이 그림 앞에서 깊이 감동했다는 일화로도 유명한 만년의 걸작이다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"The Night Watch","titleKo":"야경","titleKeys":["night","watch"],"year":"1642","desc":"암스테르담 민병대가 출동하는 순간을 그린 대형 집단 초상화다. 인물을 나란히 세우던 단체 초상의 관례를 깨고 빛과 움직임으로 극적인 장면을 연출했으며, 암스테르담 국립미술관의 대표 소장품이다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"The Return of the Prodigal Son","titleKo":"돌아온 탕자","titleKeys":["return","prodigal","son"],"year":"c. 1661–1669","desc":"무릎 꿇은 탕자를 말없이 감싸안는 아버지의 모습을 그린 만년의 걸작이다. 어둠 속에서 떠오르는 따뜻한 빛과 아버지의 두 손의 표현이 용서와 화해의 감정을 깊이 있게 전하며, 예르미타시 미술관에 있다."},
  {"artistEn":"Rembrandt","artistKo":"렘브란트","artistKeys":["rembrandt","van rijn","rijn"],"titleEn":"The Storm on the Sea of Galilee","titleKo":"갈릴리 호수의 폭풍","titleKeys":["storm","sea","galilee"],"year":"1633","desc":"갈릴리 호수의 폭풍 속에서 요동치는 배와 공포에 질린 제자들을 그린 렘브란트의 유일한 바다 그림이다. 1990년 보스턴의 미술관에서 도난당해 지금까지 행방을 알 수 없는 작품이기도 하다."},
  {"artistEn":"Sandro Botticelli","artistKo":"산드로 보티첼리","artistKeys":["botticelli","sandro"],"titleEn":"Madonna of the Magnificat","titleKo":"마니피카트의 성모","titleKeys":["madonna","magnificat"],"year":"1481","desc":"원형 화면 안에 성모가 아기 예수를 안고 찬가를 적어 내려가는 모습을 담았다. 천사들이 성모에게 관을 씌우는 구성과 부드러운 색채, 금빛 장식이 어우러진 보티첼리 성모화의 대표작이다."},
  {"artistEn":"Sandro Botticelli","artistKo":"산드로 보티첼리","artistKeys":["botticelli","sandro"],"titleEn":"Primavera","titleKo":"프리마베라(봄)","titleKeys":["primavera","spring"],"year":"c. 1480","desc":"봄의 정원에 비너스와 삼미신, 꽃의 여신 플로라 등 신화 속 인물들이 모여 있는 대형 알레고리화다. 수백 종의 식물이 세밀하게 그려진 배경과 우아한 인물 표현으로 르네상스 신화화의 대표작이 되었다."},
  {"artistEn":"Sandro Botticelli","artistKo":"산드로 보티첼리","artistKeys":["botticelli","sandro"],"titleEn":"The Adoration of the Magi","titleKo":"동방박사의 경배","titleKeys":["adoration","magi"],"year":"c. 1475","desc":"동방박사들이 아기 예수에게 경배하는 장면을 그린 작품으로, 메디치 가문 인물들이 등장인물로 그려진 것으로 알려져 있다. 화면 오른쪽 끝에는 관람자를 바라보는 화가 자신의 모습도 담겨 있다."},
  {"artistEn":"Sandro Botticelli","artistKo":"산드로 보티첼리","artistKeys":["botticelli","sandro"],"titleEn":"The Birth of Venus","titleKo":"비너스의 탄생","titleKeys":["birth","venus"],"year":"c. 1484–1486","desc":"조개껍데기 위에 선 비너스가 바다에서 태어나 해안에 다다르는 장면을 그렸다. 바람의 신이 불어보내는 미풍과 우아한 곡선의 인체가 어우러진 이탈리아 르네상스의 상징적 걸작으로, 우피치 미술관에 소장되어 있다."},
  {"artistEn":"Sandro Botticelli","artistKo":"산드로 보티첼리","artistKeys":["botticelli","sandro"],"titleEn":"Venus and Mars","titleKo":"비너스와 마르스","titleKeys":["venus","mars"],"year":"c. 1485","desc":"잠든 전쟁의 신 마르스와 그를 깨어 있는 눈으로 지켜보는 비너스를 그린 작품으로, 사랑이 전쟁을 이긴다는 의미로 해석된다. 마르스의 무기를 갖고 장난치는 어린 사티로스들이 화면에 유쾌함을 더한다."},
  {"artistEn":"Shin Yun-bok","artistKo":"신윤복","artistKeys":["shin yun-bok","shin yunbok","shinyunbok","yunbok","hyewon"],"titleEn":"Dano Pungjeong (Scenery on Dano Day)","titleKo":"단오풍정","titleKeys":["dano","pungjeong"],"year":"18세기 말","desc":"단오날 냇가에서 그네를 타고 몸을 씻는 여인들을 그렸으며, 바위 뒤 동자승들이 이를 훔쳐보고 있다. 국보 혜원전신첩에 실린 신윤복 풍속화의 대표작으로 꼽힌다."},
  {"artistEn":"Shin Yun-bok","artistKo":"신윤복","artistKeys":["shin yun-bok","shin yunbok","shinyunbok","yunbok","hyewon"],"titleEn":"Juyu Cheonggang (Boating on the Clear River)","titleKo":"주유청강","titleKeys":["juyu","cheonggang","boating"],"year":"18세기 말","desc":"양반들이 기녀들과 함께 배 위에서 풍류를 즐기는 뱃놀이 장면을 담았다. 생황과 대금 소리가 들려오는 듯한 순간을 세련된 필치와 색감으로 그린 혜원전신첩의 한 장면이다."},
  {"artistEn":"Shin Yun-bok","artistKo":"신윤복","artistKeys":["shin yun-bok","shin yunbok","shinyunbok","yunbok","hyewon"],"titleEn":"Miindo (Portrait of a Beauty)","titleKo":"미인도","titleKeys":["miindo","beauty","portrait"],"year":"18세기 말","desc":"트레머리에 옥색 치마와 삼회장저고리를 입은 여인의 전신을 그린 초상이다. 여인의 섬세한 아름다움을 독립된 주제로 삼은 조선 회화의 드문 걸작으로, 간송미술관이 소장하고 있다."},
  {"artistEn":"Shin Yun-bok","artistKo":"신윤복","artistKeys":["shin yun-bok","shin yunbok","shinyunbok","yunbok","hyewon"],"titleEn":"Wolha Jeongin (Lovers Under the Moon)","titleKo":"월하정인","titleKeys":["wolha","jeongin","lovers","moon"],"year":"18세기 말","desc":"초승달이 뜬 밤 담 모퉁이에서 은밀히 만난 연인을 그렸다. '달빛 침침한 삼경, 두 사람 마음은 두 사람만 안다'는 화제가 적혀 있는, 조선의 밤과 연애를 담은 명작이다."},
  {"artistEn":"Théodore Géricault","artistKo":"테오도르 제리코","artistKeys":["gericault","theodore gericault"],"titleEn":"The Charging Chasseur","titleKo":"돌격하는 근위 기병 장교","titleKeys":["charging","chasseur","officer"],"year":"1812","desc":"뒷발로 일어선 말 위에서 몸을 돌려 칼을 치켜든 기병 장교를 그린 작품이다. 스물한 살의 제리코가 살롱에 데뷔한 그림으로, 역동적인 동세와 격정적 붓질에서 낭만주의의 기운이 감지된다."},
  {"artistEn":"Théodore Géricault","artistKo":"테오도르 제리코","artistKeys":["gericault","theodore gericault"],"titleEn":"The Raft of the Medusa","titleKo":"메두사호의 뗏목","titleKeys":["raft","medusa"],"year":"1819","desc":"난파한 메두사호의 생존자들이 뗏목 위에서 구조선을 발견하는 순간을 그린 대작이다. 실제 사건을 소재로 한 고발적 주제와 극적인 피라미드 구도로 낭만주의 회화의 문을 연 작품으로 평가된다."},
  {"artistEn":"Thomas Gainsborough","artistKo":"토머스 게인즈버러","artistKeys":["gainsborough","thomas gainsborough"],"titleEn":"Mr and Mrs Andrews","titleKo":"앤드루스 부부","titleKeys":["mr","mrs","andrews"],"year":"c. 1750","desc":"젊은 지주 부부를 소유지 풍경과 함께 그린 초상화다. 인물과 영국 시골 풍경을 한 화면에 결합해 재산과 신분을 은근히 과시하며, 게인즈버러 초기의 대표작으로 꼽힌다."},
  {"artistEn":"Thomas Gainsborough","artistKo":"토머스 게인즈버러","artistKeys":["gainsborough","thomas gainsborough"],"titleEn":"The Blue Boy","titleKo":"파란 옷을 입은 소년","titleKeys":["blue","boy"],"year":"c. 1770","desc":"푸른 새틴 의상을 입은 소년이 당당한 자세로 서 있는 전신 초상이다. 반다이크풍 복장에 대한 오마주로 알려져 있으며, 차가운 청색을 주조로 삼은 과감한 색채 실험이 돋보이는 작품이다."},
  {"artistEn":"Thomas Gainsborough","artistKo":"토머스 게인즈버러","artistKeys":["gainsborough","thomas gainsborough"],"titleEn":"The Morning Walk","titleKo":"아침 산책","titleKeys":["morning","walk"],"year":"1785","desc":"신혼의 귀족 부부가 개와 함께 숲길을 산책하는 모습을 그린 전신 초상이다. 깃털처럼 가벼운 붓질로 드레스와 나뭇잎을 표현했으며, 게인즈버러 말년의 우아한 화풍이 잘 드러난다."},
  {"artistEn":"Titian","artistKo":"티치아노","artistKeys":["titian","tiziano","vecellio"],"titleEn":"Assumption of the Virgin","titleKo":"성모 승천","titleKeys":["assumption","virgin"],"year":"1516–1518","desc":"베네치아 프라리 성당의 대형 제단화로, 성모가 천사들에 둘러싸여 하늘로 들어올려지는 장면을 그렸다. 강렬한 붉은색과 역동적인 상승 구도로 젊은 티치아노의 명성을 단숨에 확립한 작품이다."},
  {"artistEn":"Titian","artistKo":"티치아노","artistKeys":["titian","tiziano","vecellio"],"titleEn":"Bacchus and Ariadne","titleKo":"바쿠스와 아리아드네","titleKeys":["bacchus","ariadne"],"year":"1520–1523","desc":"낙소스 섬에 버려진 아리아드네 앞에 술의 신 바쿠스가 마차에서 뛰어내리는 극적인 순간을 그렸다. 선명한 군청색 하늘과 생동감 넘치는 인물 묘사가 돋보이는 신화화의 걸작으로, 런던 내셔널 갤러리에 있다."},
  {"artistEn":"Titian","artistKo":"티치아노","artistKeys":["titian","tiziano","vecellio"],"titleEn":"Danaë","titleKo":"다나에","titleKeys":["danae"],"year":"c. 1544–1546","desc":"황금 비로 변한 제우스가 다나에에게 내려오는 신화의 장면을 그렸다. 부드러운 붓질과 관능적인 인체 표현이 베네치아 화파 색채주의의 정점을 보여주며, 티치아노는 이 주제를 여러 판본으로 남겼다."},
  {"artistEn":"Titian","artistKo":"티치아노","artistKeys":["titian","tiziano","vecellio"],"titleEn":"Sacred and Profane Love","titleKo":"신성한 사랑과 세속적인 사랑","titleKeys":["sacred","profane","love"],"year":"c. 1514","desc":"샘가에 옷을 입은 여인과 누드의 여인이 나란히 앉아 있는 알레고리화다. 두 인물이 각각 무엇을 상징하는지를 두고 오랫동안 다양한 해석이 이어져 왔으며, 로마 보르게세 미술관에 소장되어 있다."},
  {"artistEn":"Titian","artistKo":"티치아노","artistKeys":["titian","tiziano","vecellio"],"titleEn":"Venus of Urbino","titleKo":"우르비노의 비너스","titleKeys":["venus","urbino"],"year":"1538","desc":"침대에 비스듬히 누운 비너스가 관람자를 정면으로 바라보는 관능적인 누드화다. 따뜻한 색채와 부드러운 살결 표현이 베네치아 화파의 특징을 잘 보여주며, 마네의 올랭피아 등 이후 누드화 전통에 큰 영향을 주었다."},
  {"artistEn":"Utagawa Hiroshige","artistKo":"우타가와 히로시게","artistKeys":["hiroshige","utagawa hiroshige","ando hiroshige","utagawahiroshige"],"titleEn":"Kanbara: Night Snow","titleKo":"간바라: 밤의 눈","titleKeys":["kanbara","night","snow","tokaido"],"year":"c. 1833","desc":"밤눈이 소복이 쌓인 간바라 역참 마을을 지나는 행인들을 고요하게 담았다. 에도와 교토를 잇는 길을 그린 '도카이도 53차' 연작 중에서도 서정성이 가장 뛰어난 장면으로 꼽힌다."},
  {"artistEn":"Utagawa Hiroshige","artistKo":"우타가와 히로시게","artistKeys":["hiroshige","utagawa hiroshige","ando hiroshige","utagawahiroshige"],"titleEn":"Plum Park in Kameido","titleKo":"가메이도의 매화 정원","titleKeys":["plum","kameido","garden"],"year":"1857","desc":"매화나무 굵은 가지를 화면 맨 앞에 크게 배치하고 그 사이로 정원 풍경을 바라보는 파격적 구도다. 고흐가 그대로 유화로 모사한 것으로 유명한 '명소에도 백경'의 한 장면이다."},
  {"artistEn":"Utagawa Hiroshige","artistKo":"우타가와 히로시게","artistKeys":["hiroshige","utagawa hiroshige","ando hiroshige","utagawahiroshige"],"titleEn":"Sudden Shower over Shin-Ohashi Bridge and Atake","titleKo":"오하시 다리에 내리는 소나기","titleKeys":["sudden","shower","ohashi","bridge","atake"],"year":"1857","desc":"소나기가 쏟아지는 다리 위로 행인들이 몸을 숙인 채 종종걸음 치는 순간을 포착했다. '명소에도 백경' 연작의 하나로, 고흐가 유화로 모사할 만큼 서양 화가들을 매료시킨 작품이다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Almond Blossom","titleKo":"아몬드 꽃","titleKeys":["almond","blossom"],"year":"1890","desc":"푸른 하늘을 배경으로 활짝 핀 아몬드 나뭇가지를 그린 작품으로, 갓 태어난 조카 빈센트의 탄생을 축하하며 동생 테오 부부에게 선물했다. 일본 판화의 영향이 짙은 구도로, 새 생명과 희망을 상징한다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Café Terrace at Night","titleKo":"밤의 카페 테라스","titleKeys":["cafe","terrace","night"],"year":"1888","desc":"아를의 포룸 광장에 있는 카페의 야외 테라스를 별이 총총한 밤하늘 아래 그린 작품이다. 검은색을 쓰지 않고 노란 가스등 불빛과 파란 밤하늘의 대비만으로 밤을 표현한 것이 특징이다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Irises","titleKo":"붓꽃","titleKeys":["irises","iris"],"year":"1889","desc":"생레미 요양원 정원에 핀 보랏빛 붓꽃 무리를 그린 작품이다. 요양원 입원 첫 주에 그렸으며, 굽이치는 잎사귀의 선과 생명력 넘치는 색채가 돋보인다. 현재 로스앤젤레스 게티 미술관이 소장하고 있다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"L'Arlésienne (Madame Ginoux)","titleKo":"아를의 여인 (지누 부인)","titleKeys":["arlesienne","ginoux"],"year":"1888","desc":"아를의 카페 주인 지누 부인을 책과 함께 그린 초상화로, 노란 배경 앞 검은 옷의 여인이 강렬한 대비를 이룬다. 고흐는 단 한 시간 만에 밑그림을 그렸다고 전해지며, 이후 여러 버전을 반복해 그렸다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Portrait of Dr. Gachet","titleKo":"닥터 가셰의 초상","titleKeys":["doctor","gachet","dr"],"year":"1890","desc":"생의 마지막 시기 오베르에서 고흐를 돌본 의사 폴 가셰를 그린 초상화이다. 손으로 머리를 괴고 우울한 표정을 짓는 모습에 시대의 슬픔을 담고자 했으며, 1990년 경매에서 당시 최고가를 기록해 화제가 되었다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Portrait of the Postman Joseph Roulin","titleKo":"우체부 조제프 룰랭의 초상","titleKeys":["postman","roulin"],"year":"1888","desc":"아를에서 고흐와 깊은 우정을 나눈 우체부 조제프 룰랭을 그린 초상 연작 중 하나다. 파란 제복과 풍성한 수염이 인상적이며, 고흐는 룰랭 가족 전체를 여러 차례 그리며 각별한 애정을 표현했다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Self-Portrait","titleKo":"자화상 (1889)","titleKeys":["self","portrait","selfportrait"],"year":"1889","desc":"생레미 요양원 시절에 그린 자화상으로, 소용돌이치는 청록색 배경 앞에 화가의 강렬한 눈빛이 빛난다. 고흐는 평생 35점 이상의 자화상을 남겼으며, 이 작품은 오르세 미술관 소장의 대표작이다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Self-Portrait with Bandaged Ear","titleKo":"귀에 붕대를 감은 자화상","titleKeys":["bandaged","ear","self","portrait"],"year":"1889","desc":"고갱과의 갈등 끝에 자신의 귀를 자른 직후 그린 자화상이다. 붕대를 감은 채 초록 코트를 입고 담담히 정면을 응시하는 모습 뒤로 일본 판화와 이젤이 보이며, 고통 속에서도 그림에 대한 의지를 드러낸다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Self-Portrait with Grey Felt Hat","titleKo":"회색 펠트 모자를 쓴 자화상","titleKeys":["grey","felt","hat","portrait"],"year":"1887","desc":"파리 시절 말기에 그린 자화상으로, 회색 펠트 모자를 쓴 얼굴 주위로 색점과 색선이 후광처럼 퍼져 나간다. 점묘법을 자기식으로 소화해 격렬한 붓 터치로 발전시킨 과정을 잘 보여주는 작품이다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Starry Night Over the Rhône","titleKo":"론 강의 별이 빛나는 밤","titleKeys":["starry","night","rhone"],"year":"1888","desc":"아를의 론 강변에서 바라본 밤하늘과 강물에 비친 가스등 불빛을 그린 작품이다. 북두칠성이 빛나는 하늘과 금빛 반영이 어우러지며, 이듬해의 별이 빛나는 밤보다 앞서 그려진 야경 걸작이다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Sunflowers","titleKo":"해바라기","titleKeys":["sunflowers"],"year":"1888","desc":"아를의 노란 집을 꾸미기 위해 그린 해바라기 정물 연작으로, 고갱의 방문을 기다리며 제작했다. 노란색만으로 화면을 채우는 대담한 실험이 이루어졌으며, 고흐 자신도 가장 아끼는 그림으로 꼽았다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"The Bedroom","titleKo":"아를의 침실","titleKeys":["bedroom","arles"],"year":"1888","desc":"아를의 노란 집에 있던 자신의 침실을 그린 작품으로, 고흐는 이 그림이 휴식을 표현하기를 바랐다. 원근법을 일부러 단순화하고 벽의 파랑과 침대의 노랑 등 평평한 색면으로 안식의 느낌을 살렸으며, 세 가지 버전이 전해진다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"The Church at Auvers","titleKo":"오베르의 교회","titleKeys":["church","auvers"],"year":"1890","desc":"오베르쉬르우아즈의 고딕 교회를 짙푸른 하늘 아래 일렁이는 윤곽선으로 그린 만년의 작품이다. 건물이 녹아내릴 듯 흔들리는 형태와 두 갈래로 갈라지는 길이 화가의 내면적 동요를 반영한다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"The Night Café","titleKo":"밤의 카페","titleKeys":["night","cafe"],"year":"1888","desc":"아를의 밤샘 카페 내부를 붉은 벽과 초록 당구대의 강렬한 보색 대비로 그린 작품이다. 고흐는 이 그림에서 인간의 끔찍한 정념을 빨강과 초록으로 표현하고자 했다고 편지에 적었다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"The Olive Trees","titleKo":"올리브 나무","titleKeys":["olive","trees"],"year":"1889","desc":"생레미 요양원 주변의 올리브 과수원을 그린 연작 중 하나로, 나무와 산, 구름이 모두 물결치듯 굽이친다. 고흐는 올리브 나무에서 남프랑스의 정신을 발견했으며, 별이 빛나는 밤과 짝을 이루는 낮 풍경으로 평가된다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"The Potato Eaters","titleKo":"감자 먹는 사람들","titleKeys":["potato","eaters"],"year":"1885","desc":"네덜란드 뉘넌 시절, 램프 불빛 아래 감자를 나눠 먹는 농민 가족을 그린 초기 대표작이다. 흙빛의 어두운 색조와 투박한 인물 묘사를 통해 노동하는 사람들의 정직한 삶을 담고자 했다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"The Red Vineyard","titleKo":"붉은 포도밭","titleKeys":["red","vineyard"],"year":"1888","desc":"석양 아래 붉게 물든 포도밭에서 수확하는 사람들을 그린 작품이다. 고흐 생전에 공식적으로 판매된 것이 확인되는 거의 유일한 그림으로 유명하며, 벨기에 화가 안나 보흐가 400프랑에 구입했다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"The Sower","titleKo":"씨 뿌리는 사람","titleKeys":["sower"],"year":"1888","desc":"거대한 태양을 등지고 밭에 씨를 뿌리는 농부를 그린 작품으로, 존경하던 밀레의 주제를 자신만의 색채로 재해석했다. 노랗게 타오르는 하늘과 보랏빛 밭의 보색 대비가 생명의 순환이라는 주제를 강렬하게 전한다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"The Starry Night","titleKo":"별이 빛나는 밤","titleKeys":["starry","night"],"year":"1889","desc":"생레미 요양원에서 그린 밤하늘 풍경으로, 소용돌이치는 별과 달이 사이프러스 나무 위로 흐른다. 고흐 특유의 두꺼운 붓질과 격정적 색채가 정점에 이른 작품으로, 뉴욕 현대미술관이 소장하고 있다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"The Yellow House","titleKo":"노란 집","titleKeys":["yellow","house"],"year":"1888","desc":"고흐가 아를에서 세 들어 살며 화가 공동체를 꿈꾸었던 노란 집과 그 주변 거리를 그린 작품이다. 강렬한 노란 벽과 코발트빛 하늘의 대비가 인상적이며, 고갱과의 공동생활이 이곳에서 시작되고 끝났다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Wheat Field with Cypresses","titleKo":"사이프러스가 있는 밀밭","titleKeys":["wheatfield","cypresses","wheat"],"year":"1889","desc":"생레미 시절 황금빛 밀밭과 검푸른 사이프러스, 소용돌이치는 구름을 함께 그린 작품이다. 고흐는 사이프러스를 이집트 오벨리스크처럼 아름답다고 여겨 즐겨 그렸으며, 여름 프로방스의 열기가 화면에 넘실댄다."},
  {"artistEn":"Vincent van Gogh","artistKo":"빈센트 반 고흐","artistKeys":["van gogh","gogh","vangogh","vincent"],"titleEn":"Wheatfield with Crows","titleKo":"까마귀가 나는 밀밭","titleKeys":["wheatfield","crows"],"year":"1890","desc":"오베르쉬르우아즈의 밀밭 위로 폭풍우 치는 하늘과 까마귀 떼를 그린 만년의 작품이다. 세 갈래로 갈라진 길과 요동치는 하늘이 불안과 고독을 강렬하게 전하며, 죽음을 앞둔 고흐의 심경을 담은 그림으로 자주 언급된다."},
  {"artistEn":"Wassily Kandinsky","artistKo":"바실리 칸딘스키","artistKeys":["kandinsky","wassily kandinsky","wassilykandinsky"],"titleEn":"Composition VII","titleKo":"구성 VII","titleKeys":["composition","vii","composition 7"],"year":"1913","desc":"칸딘스키가 스스로 추상의 정점으로 꼽은 대작으로, 소용돌이치는 색과 형태가 화면을 가득 채운다. 최후의 심판과 부활 같은 종교적 주제가 비구상적으로 녹아 있다고 해석되는 초기 추상의 걸작이다."},
  {"artistEn":"Wassily Kandinsky","artistKo":"바실리 칸딘스키","artistKeys":["kandinsky","wassily kandinsky","wassilykandinsky"],"titleEn":"Composition VIII","titleKo":"구성 VIII","titleKeys":["composition","viii","composition 8"],"year":"1923","desc":"바우하우스 시기의 대표작으로, 원과 직선, 삼각형 등 기하학적 요소들이 화면을 구성한다. 초기의 격정적 추상에서 질서와 균형의 추상으로 옮겨 간 칸딘스키의 변화를 보여주는 작품이다."},
  {"artistEn":"Wassily Kandinsky","artistKo":"바실리 칸딘스키","artistKeys":["kandinsky","wassily kandinsky","wassilykandinsky"],"titleEn":"Several Circles","titleKo":"여러 개의 원","titleKeys":["several","circles"],"year":"1926","desc":"검은 바탕 위에 크고 작은 원들이 겹치며 우주처럼 떠 있는 순수 추상 작품이다. 칸딘스키는 원을 가장 평온하면서도 무한한 긴장을 품은 형태로 여겼으며, 그 사유가 응축된 대표작이다."},
  {"artistEn":"Wassily Kandinsky","artistKo":"바실리 칸딘스키","artistKeys":["kandinsky","wassily kandinsky","wassilykandinsky"],"titleEn":"The Blue Rider","titleKo":"청기사","titleKeys":["blue","rider","blaue reiter"],"year":"1903","desc":"푸른 망토를 두른 기수가 초원을 질주하는 장면을 그린 초기 인상주의풍 작품이다. 훗날 프란츠 마르크와 함께 결성한 표현주의 그룹 '청기사파'의 이름이 이 그림에서 유래했다."},
  {"artistEn":"Wassily Kandinsky","artistKo":"바실리 칸딘스키","artistKeys":["kandinsky","wassily kandinsky","wassilykandinsky"],"titleEn":"Yellow-Red-Blue","titleKo":"노랑 빨강 파랑","titleKeys":["yellow","red","blue"],"year":"1925","desc":"삼원색을 화면의 축으로 삼아 기하학적 형태와 자유곡선을 대비시킨 작품이다. 색과 형태가 음악처럼 감정을 전달한다는 칸딘스키의 이론이 집약된 바우하우스 시기의 대표작이다."},
  {"artistEn":"William-Adolphe Bouguereau","artistKo":"윌리엄 아돌프 부그로","artistKeys":["bouguereau","william adolphe bouguereau"],"titleEn":"Dante and Virgil","titleKo":"단테와 베르길리우스","titleKeys":["dante","virgil"],"year":"1850","desc":"지옥에서 두 망령이 격렬하게 뒤엉켜 싸우는 모습을 단테와 베르길리우스가 지켜보는 장면이다. 이를 드러내고 목을 무는 폭력적 묘사가 충격적이며, 부그로 초기의 이례적으로 격정적인 작품이다."},
  {"artistEn":"William-Adolphe Bouguereau","artistKo":"윌리엄 아돌프 부그로","artistKeys":["bouguereau","william adolphe bouguereau"],"titleEn":"Nymphs and Satyr","titleKo":"님프와 사티로스","titleKeys":["nymphs","satyr"],"year":"1873","desc":"숲속 님프들이 사티로스를 물속으로 끌어들이며 장난치는 장면을 그린 작품이다. 빛나는 살결과 율동적인 군상 구성이 돋보이며, 신화 주제를 다룬 부그로의 대작 가운데 가장 유명하다."},
  {"artistEn":"William-Adolphe Bouguereau","artistKo":"윌리엄 아돌프 부그로","artistKeys":["bouguereau","william adolphe bouguereau"],"titleEn":"The Birth of Venus","titleKo":"비너스의 탄생","titleKeys":["birth","venus"],"year":"1879","desc":"조개껍데기 위에 선 비너스가 바다에서 탄생하는 장면을 그린 작품이다. 도자기처럼 매끄러운 피부 표현과 완벽한 인체 묘사로, 19세기 아카데미 회화의 기교가 정점에 달한 그림으로 꼽힌다."},
  {"artistEn":"Winslow Homer","artistKo":"윈즐로 호머","artistKeys":["homer","winslow homer","winslowhomer"],"titleEn":"Breezing Up (A Fair Wind)","titleKo":"순풍","titleKeys":["breezing","fair","wind"],"year":"1873-1876","desc":"순풍을 받아 기울어진 돛단배 위의 어부와 세 소년을 그린 작품이다. 미국 건국 100주년 무렵 발표되어 젊은 국가의 낙관적인 미래를 상징하는 그림으로 큰 사랑을 받았다."},
  {"artistEn":"Winslow Homer","artistKo":"윈즐로 호머","artistKeys":["homer","winslow homer","winslowhomer"],"titleEn":"Snap the Whip","titleKo":"채찍놀이","titleKeys":["snap","whip"],"year":"1872","desc":"붉은 시골 학교 앞에서 맨발의 소년들이 손을 잡고 채찍놀이를 하는 장면을 그렸다. 남북전쟁 이후 미국인들이 그리워한 순수한 전원의 유년을 담아 국민적 사랑을 받은 작품이다."},
  {"artistEn":"Winslow Homer","artistKo":"윈즐로 호머","artistKeys":["homer","winslow homer","winslowhomer"],"titleEn":"The Fog Warning","titleKo":"안개 경보","titleKeys":["fog","warning"],"year":"1885","desc":"안개가 밀려오는 바다에서 잡은 생선을 싣고 본선으로 돌아가려 노를 젓는 어부의 긴박한 순간을 담았다. 바다에서의 생존이라는 주제를 다룬 호머 해양화의 백미로 꼽힌다."},
  {"artistEn":"Winslow Homer","artistKo":"윈즐로 호머","artistKeys":["homer","winslow homer","winslowhomer"],"titleEn":"The Gulf Stream","titleKo":"멕시코 만류","titleKeys":["gulf","stream"],"year":"1899","desc":"돛이 부러진 작은 배 위의 흑인 선원이 상어 떼가 도는 거친 바다 한가운데 홀로 놓여 있다. 인간과 자연의 대결이라는 호머의 평생 주제 의식이 응축된 대표작으로 꼽힌다."},
  {"artistEn":"Yi Am","artistKo":"이암","artistKeys":["yi am","yiam","lee am"],"titleEn":"Mogyeondo (Mother Dog and Puppies)","titleKo":"모견도","titleKeys":["mogyeondo","dog","puppies"],"year":"16세기","desc":"나무 그늘 아래 어미 개가 강아지들을 품에 안고 있는 모습을 따뜻한 시선으로 그렸다. 조선 전기 왕족 출신 화가 이암의 대표작으로, 정감 어린 동물 그림의 걸작으로 꼽힌다."}
];
